const e=[{id:1,code:"FACT-101",icon:"HardHat",accent:"#ea580c",title:"کەرەستەیێن خوەپاراستنێ (PPE)",subtitle:"Personal Protective Equipment",summary:"ناسینا کەرەستەیێن خوەپاراستنێ و بکارئینانا وان یا دروست",blocks:[{body:"کەرەستەیێن خوەپاراستنا کەسی (PPE) دوماهیک هێلا بەرگریێ نە دژی برینداربوونێ: بەری وان، دڤێت مەترسی ب ڕێکێن ئەندازیاری و ڕێکارێن کاری بهێتە لادان یان کێمکرن (Hierarchy of Controls). ل کارگەهان بکارئینانا PPE نە دلخوازییە، بەلکو فەرزە."},{heading:"١. جۆرێن سەرەکی یێن PPE",body:"بۆ هەر ئەندامەکێ لەشی کەرەستەیەکێ تایبەت هەیە:",points:["سەر: کلاوێ پاراستنێ (Hard Hat) — پاراستن دژی کەفتنا تشتان و لێدانێ.","چاڤ: بەرچاڤکێن سەلامەتیێ (Safety Glasses) — پاراستن دژی تۆز، ماددەیێن کیمیایی، و پریشکان.","گوهـ: گوهگر (Earmuffs / Earplugs) — دژی دەنگێ بلند یێ ئامێران (٨٥ dB(A) و پتر).","دەست: دەستکێش — دژی بڕین، گەرمی، و ماددەیێن کیمیایی.","پێ: پێلاڤێن سەلامەتیێ ب سەرێ ئاسنی (Steel Toe) — دژی پەلچقین و کەفتنا تشتێن گران.","لەش: جلێن ئاشکرا (Hi-Vis) ب ڕەنگێن گەش — دا شوفێر و کارگەرێن دی تە ببینن."]}],media:[{kind:"video",src:"media/videos/ppe_tutorial.mp4",title:"PPE",description:"ڕێکا دروست یا لبەرکرنێ"}],quiz:[{question:"ل دویڤ ستانداردێن ئەورووپی، کەنگی بکارئینانا گوهگران فەرز دبیت؟",options:[{text:"٥٠ dB",correct:!1},{text:"٧٠ dB(A) و پتر (تێکڕایا ٨ دەمژمێرێن کاری)",correct:!1},{text:"٨٥ dB(A) و پتر (تێکڕایا ٨ دەمژمێرێن کاری)",correct:!0},{text:"١٢٠ dB(A) و پتر (تێکڕایا ٨ دەمژمێرێن کاری)",correct:!1}],explanation:"ل دویڤ ڕێنمایا ئەورووپی 2003/10/EC، دەمێ تێکڕایا دەنگی د ٨ دەمژمێرێن کاری دا دگەهیتە ٨٥ dB(A)، دڤێت گوهگر بهێنە بکارئینان. OSHA ژی ل ٨٥ dBA بەرنامەیێ پاراستنا گوهان داخواز دکەت."},{question:"کەرەستەیێن خوەپاراستنێ (PPE) دوماهیک هێلا بەرگریێ نە دژی برینداربوونێ. دڤێت چ بەری وان بهێتە کرن؟",options:[{text:"کڕینا کەرەستەیێن پاراستنێ یێن گرانبهاتر",correct:!1},{text:"لادان یان کێمکرنا مەترسیێ",correct:!0},{text:"داخوازکرن ژ کارگەران کو ب لەزتر کار بکەن دا دەمێ مەترسیێ کێم ببیت",correct:!1},{text:"چاڤەڕێکرن هەتا برینداربوونەک جهێ مەترسیێ دیار بکەت",correct:!1}],explanation:"بەری PPE، دڤێت مەترسی ب ڕێکێن ئەندازیاری و ڕێکارێن کاری بهێتە لادان یان کێمکرن (Hierarchy of Controls)؛ PPE دوماهیک هێلا بەرگریێ نە و ل کارگەهان بکارئینانا وان هەر فەرزە."},{question:"بۆچی کارگەر جلێن ئاشکرا (Hi-Vis) ب ڕەنگێن گەش لبەر دکەن؟",options:[{text:"دا پێستی ژ ماددەیێن کیمیایی و گەرمیێ بپارێزن",correct:!1},{text:"دا دیار ببیت هەر کارگەرەک ژ کیش پشکێ یە",correct:!1},{text:"دا لەشی ل کارگەهێن سار گەرم بهێلن",correct:!1},{text:"دا شوفێر و کارگەرێن دی وان ببینن",correct:!0}],explanation:"جلێن ئاشکرا ب ڕەنگێن گەش کارگەری دیار دکەن دا شوفێر و کارگەرێن دی وی ببینن؛ پاراستن ژ ماددەیێن کیمیایی و گەرمیێ کارێ کەرەستەیێن دی یە، وەک دەستکێشان."}]},{id:2,code:"FACT-102",icon:"Cog",accent:"#2563eb",title:"سەلامەتیا ئامێران",subtitle:"Machine Safety & Guarding",summary:"پاراستنا کارگەران ژ پشکێن ئامێران یێن کو دلڤن",blocks:[{body:"ئامێرێن پیشەسازی خودان هێزەکا مەزنن و دشێن د چرکەیەکێ دا برینێن گران یان ژدەستدانا ئەندامەکێ لەشی پەیدا بکەن."},{heading:"١. گاردێن ئامێران (Machine Guards)",body:"دڤێت ئەڤ پاراستنە ل سەر هەمی ئامێرێن مەترسیدار هەبن:",points:["گاردێن جێگیر: بۆ داپۆشینا قایش و گێرێن کو دلڤن.","دوگمەیا ڕاوەستاندنا تەنگاڤیێ (E-Stop): دڤێت نێزیکی دەستێ کارگەری بیت و ب ڕەنگێ سۆر ل سەر بنەکێ زەرد بیت.","سێنسۆرێن ڕاوەستاندنێ: ئامێر دوەستیت ئەگەر دەست یان لەش نێزیکی جهێ مەترسیدار ببیت."]},{heading:"٢. ڕێسایێن زێڕین",body:"بەری کاری و ل دەمێ کاری:",points:["چ جاران گاردێ ئامێری لانەدە دەمێ ئامێر کار دکەت.","جلێن شل، زنجیر، و ئەنگوستیلان لبەر نەکە و پرچا درێژ گرێبدە، دا د ئامێری دا نەئێنە گرتن.","ئەگەر ئامێر تێکچوو، ئێکسەر ب دوگمەیا E-Stop ڕاوەستینە و بێی ڕێکارا LOTO دەستێ خوە نەکە ناڤ ئامێری."]}],media:[{kind:"image",src:"media/images/machine_guard.png",title:"گاردێن ئامێران",description:"نموونەیا گاردەکێ دروست"}],quiz:[{question:"ئەرێ دروستە گاردێ ئامێری بهێتە لادان دەمێ ئامێر کار دکەت؟",options:[{text:"بەلێ، ئەگەر پێدڤی بوو",correct:!1},{text:"نەخێر، ب چ شێوەیان دروست نینە",correct:!0},{text:"تەنێ بۆ پاقژکرنێ",correct:!1},{text:"تەنێ ب دەستووریا بەرپرسی",correct:!1}],explanation:"لادانا گاردێ ئامێری دەمێ ئامێر کار دکەت ئێک ژ مەترسیدارترین ڕەفتارانە. پاقژکرن و چاککرن تەنێ پشتی ڕاوەستاندن و قوفلکرنا ئامێری (LOTO) دهێنە کرن."},{question:"ئەگەر ئامێر ل دەمێ کاری تێکچوو، دێ چ کەی؟",options:[{text:"ئێکسەر ب دوگمەیا E-Stop ڕادوەستینم",correct:!0},{text:"ب لەز دەستێ خوە دکەمە ناڤ ئامێری و تشتێ گیرکری دەردئێخم",correct:!1},{text:"دهێلم کار بکەت و پاشان بەرپرسی ئاگەهدار دکەم",correct:!1},{text:"گاردێ ئامێری لادبەم دا ببینم کا چ تێکچوویە",correct:!1}],explanation:"ئەگەر ئامێر تێکچوو، ئێکسەر ب دوگمەیا E-Stop ڕاوەستینە و بێی ڕێکارا LOTO دەستێ خوە نەکە ناڤ ئامێری."},{question:"بۆچی نابیت جلێن شل، زنجیر یان ئەنگوستیلان ل نێزیک ئامێران لبەر بکەی؟",options:[{text:"چونکو خواندنا دوگمەیێن ئامێری زەحمەت دکەن",correct:!1},{text:"تەنێ چونکو دژی ڕێسایێن جلێن کارگەهێ نە",correct:!1},{text:"چونکو دشێن د ئامێری دا بهێنە گرتن",correct:!0},{text:"چونکو دشێن گاردێن ئامێری خراب بکەن",correct:!1}],explanation:"جلێن شل، زنجیر، ئەنگوستیلە و پرچا درێژ دشێن د ئامێری دا بهێنە گرتن، و ئامێر دشێت د چرکەیەکێ دا برینێن گران پەیدا بکەت؛ ژبەر هندێ پرچا درێژ ژی گرێبدە."}]},{id:3,code:"FACT-103",icon:"PlugZap",accent:"#ca8a04",title:"سەلامەتیا کارەبێ",subtitle:"Industrial Electrical Safety (LOTO)",summary:"مەترسیێن کارەبێ و سیستەمێ قوفلکرن و نیشانکرنێ (LOTO)",blocks:[{body:"کارەبا ل کارگەهان ب ڤۆلتێجەکا بلند کار دکەت؛ لێدانا کارەبێ دشێت ببیتە ئەگەرێ مرنێ یان سووتنێن گران."},{heading:"١. سیستەمێ قوفلکرن و نیشانکرنێ (Lockout/Tagout — LOTO)",body:"ئەڤە گرنگترین ڕێکارە بەری چاککرن یان پاقژکرنا ئامێران:",points:["قوفلکرن (Lockout): سەرچاڤێ کارەبێ یێ سەرەکی ببڕە و قوفلەکێ کەسی لێ بدە.",'نیشانکرن (Tagout): کارتەکێ پێڤە بکە کو ل سەر هاتبیتە نڤیسین: "کار ل سەر دهێتە کرن — هەلنەکە"، دگەل ناڤێ تە و مێژوویێ.',"کلیل تەنێ ل دەستێ وی کەسی بیت یێ چاککرنێ دکەت؛ و بەری دەستپێکرنێ پشتڕاست بە کو ئامێر ب ڕاستی بێ وزەیە (Verify)."]},{heading:"٢. پشکنینا کێبلان",body:"هەمیشە بپشکنە:",points:["کێبلێن بڕی یان یێن تێلێن وان دیار بکار نەئینە.","کارەبا و ئاڤ دوژمنێن هەڤن؛ ل جهێن تەڕ ئامێرێن کارەبێ بکار نەئینە."]}],media:[{kind:"video",src:"media/videos/loto_safety.mp4",title:"LOTO",description:"چەوا قوفلێ بکار دئینین؟"}],quiz:[{question:"مەبەست ژ LOTO چییە؟",options:[{text:"پاقژکرن",correct:!1},{text:"بڕین و قوفلکرنا وزەیێ بەری چاککرنێ",correct:!0},{text:"زێدەکرنا لەزا ئامێری",correct:!1},{text:"قوفلکرنا دەرگەهێ کارگەهێ ل دووماهیا دەوامی",correct:!1}],explanation:"سیستەمێ LOTO دهێتە بکارئینان دا کو کەسەک کارەبێ ڤەنەکەت دەمێ کارگەر ل سەر ئامێری کار دکەت (OSHA 29 CFR 1910.147)."},{question:"تە قوفلێ خوە یێ کەسی لێدا و کارت پێڤە کر. بەری دەستپێکرنا چاککرنێ دڤێت چ بکەی؟",options:[{text:"کلیلێ بدەمە هەڤالەکێ خوە دا بپارێزیت",correct:!1},{text:"ئامێری بۆ دەمەکێ کورت هەلکەم دا قوفلێ تاقی بکەم",correct:!1},{text:"پشتڕاست ببم کو ئامێر ب ڕاستی بێ وزەیە",correct:!0},{text:"ئێکسەر دەست پێ بکەم، چونکو تەنێ قوفل بەسە بۆ سەلامەتیێ",correct:!1}],explanation:"بەری دەستپێکرنێ پشتڕاست بە کو ئامێر ب ڕاستی بێ وزەیە (Verify)؛ کلیل تەنێ ل دەستێ وی کەسی دمینیت یێ چاککرنێ دکەت، دا کەس کارەبێ ڤەنەکەت."},{question:"ئەگەر تە کێبلەکا بڕی دیت کو تێلێن وێ دیار بن، دێ چ کەی؟",options:[{text:"تەنێ ل جهێن هشک بکار دئینم",correct:!1},{text:"بکار نائینم",correct:!0},{text:"ب شریتێ لکاندنێ دپێچم و بکارئینانا وێ بەردەوام دکەم",correct:!1},{text:"تەنێ بۆ ئامێرێن سڤک بکار دئینم",correct:!1}],explanation:"کێبلێن بڕی یان یێن تێلێن وان دیار بکار نەئینە؛ لێدانا کارەبێ دشێت ببیتە ئەگەرێ مرنێ یان سووتنێن گران."}]},{id:4,code:"FIRE-104",icon:"FireExtinguisher",accent:"#dc2626",title:"تەمرینکا ئاگری — ڕاهێنانا تەمام",subtitle:"Fire Extinguisher — Complete Training (PASS)",summary:"ناسینا جۆرێن تەمرینکان، پۆلێن ئاگری، و ڕێکارا PASS ب درێژی",blocks:[{body:"تەمرینکا ئاگری (Fire Extinguisher) ئامێرەکێ سەرەکییە بۆ ڤەمراندنا ئاگرێن بچووک د قۆناغا دەستپێکێ دا. ل کارگەهان هەر کارمەندەک دڤێت بزانیت چەوا ب لەز و ب دروستی تەمرینکێ بکاربینیت. زانینا جۆرێن تەمرینکان و پۆلێن ئاگری دێ ژیانا تە و هەڤالێن تە پارێزیت. تەمرینکا دەستی تەنێ چەند چرکەیان کار دکەت، ژبەرهندێ دڤێت ب دروستی بهێتە ئاراستەکرن. ئەگەر ئاگر مەزن بوو یان دوکێل زێدە بوو، تەمرینکێ بهێلە، دەرکەڤە، و گازی ١١٥ بکە."},{heading:"١. پۆلێن ئاگری ل دویڤ NFPA (Fire Classes)",body:"ل دویڤ سیستەمێ ئەمریکی (NFPA)، ئاگر بۆ ٥ پۆلان دابەش دبیت و هەر پۆلەک پێدڤی ب تەمرینکەکا گونجای هەیە. پۆلێن ئاگری ل ڤێرێ ب پیتێن NFPA 10 هاتینە نڤیسین وەک ژێدەرێ پرۆژەی؛ سیستەمێ فەرمی یێ دهۆکێ هێشتا نەهاتییە پشتڕاستکرن. بەرامبەرێن EN 2: NFPA A = EN A؛ NFPA B (شلەمەنی) = EN B؛ NFPA B (غاز) = EN C؛ NFPA C (ئامێرێن کارەبێ یێن کارەبا تێدا) چو پۆل د EN دا نینە؛ NFPA D = EN D؛ NFPA K = EN F.",points:["پۆلا A (تشتێن ڕەق): دار، کاغەز، قوماش، پلاستیک. تەمرینک: ئاڤ، کەف، تۆزا ABC.","پۆلا B (شلەمەنی و غازێن سووتەنێ): بەنزین، نەفت، ڕۆن، ئەلکهول، غاز. شلەمەنی: CO₂، تۆزا ABC یان کەف؛ بۆ ئەلکهولێ و شلەمەنیێن جەمسەری (polar solvents) یێن دی: CO₂، تۆزا هشک یان کەفا بەرگرێ ئەلکهولێ (AR foam)، چونکو کەفا ئاسایی ل سەر وان تێک دچیت. غاز: ئێکەم جار غازێ ڕاوەستینە ئەگەر سەلامەت بیت؛ چ جاران ئاگرێ غازێ ڤەنەمرینە ئەگەر نەشێی غازێ ڕاوەستینی. (چ جاران ئاڤێ بکار نەئینە!)","پۆلا C (ئامێرێن کارەبێ یێن کارەبا تێدا): سویچ، ترانسفۆرمەر، تابلۆ، جەنەڕەیتەر. تەمرینک: CO₂، تۆزا ABC، Clean Agent. (ئاڤ و کەفێ بکار نەئینە ئەگەر ل سەر لایبلێ پۆلا C یان نیشانا تاقیکرنا کارەبێ نەبیت، وەک هندەک تەمرینکێن ئاڤا هوور (water mist)!)","پۆلا D (کانزا): کانزایێن سووتەنێ — مەگنیسیۆم، تیتانیۆم، سۆدیۆم، و تۆزا ئەلەمنیۆمێ. تەمرینک: تەنێ تەمرینکەکا پۆلا D یان ماددەیەک یێ کو ناڤێ وی کانزای ل سەر لایبلا وی هاتی؛ ماددە ژ کانزایەکێ بۆ یێ دی جودایە. (ئاڤ دشێت تەقینێ چێبکەت!)","پۆلا K (مەتبەخ): ڕۆن و دۆهنێن خوارنپێژانێ. تەمرینک: Wet Chemical. (ئاڤ ڕۆنێ داخ بەلاڤ دکەت!) — ل EN 2 ئەڤە پۆلا F ە."]},{heading:"٢. جۆرێن تەمرینکان ل کارگەهان",body:"ڕەنگ نە پۆلا ئاگری یە. ل دویڤ BS EN 3، لەشێ تەمرینکێ سۆرە؛ ل بەریتانیا پارچەیەکا ڕەنگکری (BS 7863) ماددێ نیشان ددەت. وەلاتێن دی ڕەنگێن دی بکار دئینن و ڕەنگێن د دهۆکێ دا هێشتا نەهاتینە پشتڕاستکرن، لەوا هەمیشە لایبلێ و نیشانێن پۆلێ بخوینە. پۆلێن خوارێ ب پیتێن NFPA نە:",points:["تەمرینکا ئاڤێ (Water): تەمام سۆر، بێ پارچەیا ڕەنگکری — تەنێ بۆ پۆلا A (دار، کاغەز). چ جاران بۆ کارەبێ یان ڕۆنی بکار نەئینە!","تەمرینکا CO₂: پارچەیا ڕەش ل بەریتانیا — بۆ پۆلا B و ئامێرێن کارەبێ یێن کارەبا تێدا (B و C ل دویڤ NFPA؛ ل دویڤ EN 2، C غازە و CO₂ بۆ ئاگرێن غازێ نینە). غازەکا گەلەک سار دەردکەڤیت و لۆلە (Horn) گەلەک سار دبیت؛ تەنێ دەسکی بگرە و چ جاران دەست ب لۆلێ نەگرە، دێ دەستێ تە ب سەرمایێ سۆژیت! دووراتیا CO₂ کێمە و نە بۆ ئاگرێن کویر یێن دار و کاغەزی یە: ژ وێ دووراتیێ دەستپێبکە یا ل سەر لایبلا وێ هاتی و تەنێ دەمێ ئاگر بچووک دبیت نێزیکتر ببە. ل ژوورێن بچووک پشتی بکارئینانێ دەرکەڤە و هەوای بگوهۆڕە، چونکو CO₂ ئۆکسجینێ کێم دکەت.","تەمرینکا تۆزا ABC (Dry Powder): پارچەیا شین ل بەریتانیا — بۆ پۆلێن A، B، و C (نە بۆ D و K). بەلاڤترین جۆرە. تۆزەکا سپی دەردکەڤیت؛ کێماسی: دیتنێ کێم دکەت و ئامێران پیس دکەت.","تەمرینکا کەفێ (Foam/AFFF): پارچەیا کرێمی ل بەریتانیا — بۆ پۆلێن A و B. کەفێ ل سەر شلەمەنیێ ڕادخەت و ئۆکسجینێ ژێ دبڕیت. بۆ کارەبێ بکار نەئینە!","تەمرینکا Clean Agent: پۆلێن وێ ل دویڤ مۆدێلێ جودانە، لەوا لایبلێ بخوینە (گەلەک جاران B و C ب پیتێن NFPA؛ هندەک مۆدێل بۆ A ژی) — بۆ ئامێرێن هەستیار و ژوورێن سێرڤەران. پاشماوە ناهێلیت و زیانێ ناگەهینیتە ئامێرێن ئەلکترۆنی.","تەمرینکا تایبەت (Class D): بۆ کانزایێن سووتەنێ ل کارگەهان — دڤێت ناڤێ وی کانزایێ ل وێرێ بکار دهێت ل سەر لایبلا وێ هاتبیت. چ جاران ئاڤێ ل کانزایێ سووتەنێ نەکە!"]},{heading:"٣. ڕێکارا PASS — ب درێژی",body:"بەری تو تەمرینکێ بکار بینی، دڤێت هەمی بەرسڤ «بەلێ» بن: ئاگر بچووک و تازە دەستپێکری بیت، تەمرینک گونجای بیت، ڕێکا دەرکەفتنێ ل پشت تە بیت، ئاگەهداری هاتبیتە دان و گازی ١١٥ هاتبیتە کرن، تو ڕاهێنان دیتی بی، و چو دوکێل یان گەرمی ڕێکا تە نەگریت. ئەگەر ئاگر ئێکسەر ڤەنەمری، دەرکەڤە و دەرگەهی بگرە. PASS ڕێکارا گشتی یە بۆ پتریا تەمرینکێن دەستی؛ تەمرینکێن Class D، Wet Chemical، Clean Agent و یێن ل سەر چەرخان: ل دویڤ لایبلێ و ڕێنمایێن کۆمپانیا دروستکەر بکار بینە:",points:["P = Pull (بکێشە): مێخا سەلامەتیێ (Safety Pin) بکێشە. ئەڤ مێخە ناهێلیت تەمرینک ب خەلەتی کار بکەت.","A = Aim (ئاراستە بکە): لۆلا تەمرینکێ ئاراستەی بنێ ئاگری بکە — نە سەرێ گڕێ! سووتەمەنیا ئاگری ل بنی یە.","S = Squeeze (فشار بدە): دەسکێن تەمرینکێ ب هێز فشار بدە دا کو ماددە دەرکەڤیت.","S = Sweep (بلڤینە): لۆلێ ب چەپ و ڕاست ل سەر بنێ ئاگری بلڤینە هەتا ئاگر ب تەمامی ڤەدمریت؛ پاشان چاڤدێریا جهی بکە دا ئاگر دووبارە هەلنەبیت."]},{heading:"٤. پشکنینا هەیڤانە یا تەمرینکان",body:"پشکنینا ب چاڤ هەر هەیڤەکێ، ژ لایێ کەسێ بەرپرس ڤە (NFPA 10):",points:["فشارا ناڤ تەمرینکێ (Pressure Gauge)، ئەگەر هەبیت: دڤێت مێلک ل ناڤ دەڤەرا کەسک بیت. تەمرینکێن CO₂ پیڤەرا فشارێ نینە: هەلگرە دا هەست بکەی کو تژی یە.","مێخا سەلامەتیێ و مۆرا وێ: دڤێت ل جهێ خوە بن و نەهاتبنە شکاندن.","لۆلە (Nozzle): نابیت شکەستی یان گرتی بیت.","لەشێ تەمرینکێ: نابیت ژەنگی، قلیشی، یان زیانلێکەفتی بیت.","کارتا پشکنینێ و لایبل: دڤێت مێژوویا پشکنینا دوماهیێ ل سەر کارتێ بیت؛ لایبل بهێتە خواندن و ڕوویێ وێ بەرەڤ دەرڤە بیت؛ تەمرینک ل جهێ خوە بیت، دیار بیت و ب ساناهی بگەهیتێ.","تێبینی: ئەڤان ژێک جودا بکە. پشکنین و ساخکرنا سالانە ژ لایێ کەسەکێ شارەزا ڤە؛ تژیکرنەڤە (Recharge) پشتی هەر بکارئینانەکێ، هەتا ئەگەر کورت ژی بیت؛ ساخکرنا ٦ سالان: تەمرینکێن تۆزا هشک یێن فشارا هەلگرتی (stored-pressure) یێن کو پێدڤی ب تاقیکرنا هیدرۆستاتیکی یا ١٢ سالان هەی، هەر ٦ سالان جارەکێ ڤالا دکەن و ناڤا وان دپشکنن؛ تاقیکرنا هیدرۆستاتیکی (Hydrostatic Test، تاقیکرنا فشارێ یا لەشێ وێ) هەر ٥ سالان بۆ تەمرینکێن ئاڤێ، کەفێ (AFFF)، CO₂ و تۆزا هشک یا ستێنلێس ستیل (stainless steel)، و هەر ١٢ سالان بۆ تەمرینکێن تۆزا هشک یێن فشارا هەلگرتی یێن لەشێ وان ژ ئاسنێ نەرم (mild steel)، مسێ زەرد یێ لحیمکری (brazed brass) یان ئەلەمنیۆمێ. دەمێ تاقیکرنێ نە دەمێ گوهۆڕینێ یە. ڕێسایێن دهۆکێ هێشتا نەهاتینە پشتڕاستکرن."]},{heading:"٥. مەترسیێن تایبەت ل کارگەهان",body:"کارگەهـ جهەکێ هەستیارە ژبەر ڤان ئەگەران:",points:["ماددەیێن کیمیایی: سۆلڤێنت، ئەلکهول، تینەر — هەمی پۆلا B نە.","کارەبا ب ڤۆلتێجا بلند: تابلۆ و ترانسفۆرمەر — پۆلا C (NFPA).","تۆزا داری و ئاردی: ل هندەک کارگەهان دشێت تەقینا تۆزێ (Dust Explosion) پەیدا بکەت.","لەحیمکرن و بڕین: پریشکێن لەحیمکرنێ دشێن ئاگرێن پۆلێن A و B پەیدا بکەن.","کۆگەها سووتەمەنیێ: دڤێت ل ژوورەکا تایبەت یان ل دەرڤەی ئاڤاهی بیت، و تەمرینکا گونجای (کەف یان تۆز) نێزیک بیت.","جهێ دانانێ: تەمرینکان نێزیکی دەرگەه و ڕێڕەوان دانە؛ دووراتیا گەهشتنێ بۆ تەمرینکا پۆلا A نابیت ژ ٢٣ مەتران (٧٥ پێ) پتر بیت، و بۆ شلەمەنیان ٩-١٥ مەتر (NFPA 10)."],critical:!0}],media:[{kind:"video",src:"media/videos/fire_ext_factory.mp4",title:"تەمرینکا ئاگری ل کارگەهان",description:"ڕێکارا PASS و جۆرێن تەمرینکان ب ڤیدیۆ"}],quiz:[{question:"ب پیتێن NFPA، تەمرینکا CO₂ بۆ کیش پۆلێن ئاگری گونجایە؟",options:[{text:"A و D",correct:!1},{text:"B و C",correct:!0},{text:"A و K",correct:!1},{text:"D و K",correct:!1}],explanation:"CO₂ بۆ شلەمەنییێن سووتەنێ (B) و ئامێرێن کارەبێ (C) گونجایە، چونکو پاشماوە ناهێلیت و کارەبێ ناگوهێزیت. ل دویڤ EN 2، C ئاگرێن غازێ نە و CO₂ بۆ وان نینە."},{question:"ل ڕێکارا PASS، دڤێت لۆلا تەمرینکێ بەرەڤ کیڤە بیت؟",options:[{text:"سەرێ گڕێ",correct:!1},{text:"بنێ ئاگری",correct:!0},{text:"دوور ژ ئاگری",correct:!1},{text:"دوکێلا نێزیکی بانێ ژووری",correct:!1}],explanation:"هەمیشە لۆلێ بەرەڤ بنێ ئاگری بکە، چونکو سووتەمەنیا ئاگری ل وێرێ یە."},{question:"بۆچی ئاڤ ل سەر ئاگرێ ڕۆنی (پۆلا K) ناهێتە ڕژاندن؟",options:[{text:"چ تشتەکی ناکەت",correct:!1},{text:"ئاڤ ڕۆنێ سووتی بەلاڤ دکەت و گڕەکا مەزن پەیدا دکەت",correct:!0},{text:"ڕۆن ئاڤێ دمژیت، لەوما ئاگر تەنێ هێدیتر دسۆژیت",correct:!1},{text:"ئاڤ ب خوە دسوژیت",correct:!1}],explanation:"ئاڤ ل سەر ڕۆنێ داخ ئێکسەر دکەلیت و ڕۆنێ سووتی ب هەوا دئێخیت، و گڕەکا مەزن (Fireball) پەیدا دبیت. تەمرینکا Wet Chemical یان سەرپۆشەکێ بکاربینە و گەرمیێ ببڕە."}]},{id:5,code:"AID-105",icon:"HeartPulse",accent:"#db2777",title:"هەوارهاتنا ئێکێ و CPR",subtitle:"First Aid & CPR — Complete Training",summary:"ڕاهێنانا تەمام ل سەر هەوارهاتنا ئێکێ، CPR، و هەلسوکەفتێ ل دەمێ تەنگاڤیێ ل کارگەهان",blocks:[{body:"هەوارهاتنا ئێکێ (First Aid) ئەو هاریکاریا دەستپێکێ یە یا کو بەری گەهشتنا تیمێن پزیشکی دهێتە دان بۆ کەسێ بریندار یان نەخۆش. ل کارگەهان مەترسیا برینداربوونێ گەلەک یا بلندە — ژ بڕین و سووتنێ هەتا لێدانا کارەبێ و کەفتنا ژ جهێن بلند. هەر کارمەندەک دڤێت بزانیت چەوا گازی ئەمبوولانسێ (١٢٢) بکەت، CPR بکەت، خوینبەربوونێ ڕاگریت، و برینداری بپارێزیت هەتا ئەمبوولانس دگەهیت. ئەڤ وانەیە ل دویڤ ڕێنمایێن AHA 2025 و Stop the Bleed هاتیە ئامادەکرن."},{heading:"١. فشارا سنگی و هەناسەدان (CPR) — ب درێژی",body:"CPR ڕێکارەکا ڕزگارکرنا ژیانێ یە دەمێ دلێ مرۆڤی دوەستیت و هەناسەدانا ئاسایی نامینیت. ل دویڤ ڤان هەنگاڤان کار بکە:",points:["١. سەلامەتیا جهی: بەری هەر تشتەکی پشتڕاست بە کو جه سەلامەتە (کارەبا، ئاگر، یان غاز نینن)، دا تو نەبیە قوربانیا دووێ.",'٢. بەرسڤدان: ملێن برینداری ب هێز بهەژینە و ب دەنگەکێ بلند بپرسە: "تو باشی؟ تو من دبهیزی؟".',"٣. گازیکرن: ئەگەر بەرسڤ نەدا و هەناسە نەدا یان تەنێ هەناسێن نە ئاسایی دان، ئێکسەر گازی ١٢٢ بکە (یان کەسەکی بدە گازیکرنێ) و بخوازە ئامێرێ AED بهێتە ئینان.","٤. فشارێن سنگی (Compressions): پاژنا دەستەکێ بدانە ناڤەڕاستا سنگی (نیڤا خوارێ یا هەستیێ سنگی) و دەستێ دی بدانە سەر. ٣٠ فشارێن ب هێز و ب لەز بدە: کویراتی ٥-٦ سم، لەز ١٠٠-١٢٠ فشار د خولەکەکێ دا، و بهێلە سنگ ب تەمامی بزڤڕیت.","٥. هەناسەدان: سەری بەرەڤ پاش ببە و چەناکێ بلند بکە، دفنێ بگرە و ٢ هەناسەیان بدە (هەر ئێک نێزیکی ١ چرکە، هەتا سنگ بلند دبیت). ئەگەر نەشێی یان نەڤێی هەناسەیان بدەی، تەنێ فشارێن سنگی بەردەوام بکە.","٦. بەردەوامی (٣٠:٢): بەردەوام بە ل سەر ٣٠ فشاران و ٢ هەناسەیان هەتا ئەمبوولانس دگەهیت، AED ئامادە دبیت، یان بریندار دەست ب هەناسەدانا ئاسایی دکەت.","٧. بکارئینانا AED: ئێکسەر کو گەهشت، ڤەکە، پەدان (Pads) ب سنگێ ڕووت ڤە بنووسینە و فەرمانێن دەنگی یێن ئامێری جێبەجێ بکە؛ دەمێ شۆک دهێتە دان دەست ل برینداری نەدە."]},{heading:"٢. کۆنترۆلکرنا خوینبەربوونێ (Stop the Bleed)",body:"خوینبەربوونا توند دشێت د دەمەکێ کورت دا مرۆڤی بکوژیت، ژبەرهندێ گازی ١٢٢ بکە و ب لەز ڤان هەنگاڤان بکە:",points:["فشارا ڕاستەوخۆ: پارچەکا قوماشێ پاقژ بدانە سەر برینێ و ب هەردوو دەستان ب هێز فشار بدە. ئەگەر قوماش ب خوینێ تژی بوو، لانەدە؛ پارچەکا دی ل سەر بدانە و فشارێ بەردەوام بکە.","تژیکرنا برینێ (Wound Packing): ئەگەر برین کویر بوو (وەک ل ڕان، بن مل، یان ستۆی)، قوماشێ پاقژ یان گازا خوینڕاگر د ناڤ برینێ دا بتژینە و ب هێز فشار بدە. ئەندامێ بریندار بلند نەکە و ل خالێن فشارێ (Pressure Points) نەگەڕە.","تۆرنیکێت (Tourniquet): ئەگەر خوینبەربوونا دەست یان پێی مەترسیا ژیانێ هەبوو، ب زوویی تۆرنیکێتێ ٥-٧ سم ل سەر برینێ (بەرەڤ لەشی) ب قایمی ببەستە، دەمی بنڤیسە، و چ جاران سست نەکە.","تشتێ چەقی: ئەگەر ئاسن یان شووشە د ناڤ برینێ دا چەقی بوو، چ جاران دەرنەئینە! دێ خوینبەربوونێ زێدە کەت. ل دۆرا وی فشارێ بدە و جێگیر بکە."]},{heading:"٣. چارەسەرکرنا سووتنێ",body:"سووتن ل کارگەهان مەترسیدارە؛ ب ڤی ڕەنگی مامەلێ دگەل بکە، و بۆ سووتنێن مەزن یان ل ڕوو و دەستان گازی ١٢٢ بکە:",points:["سووتنا گەرمیێ: ئێکسەر ئاڤا فێنک یا ڕەوان (نە ئاڤا سەهۆلێ) بۆ ماوێ ٢٠ خولەک ب سەر سووتنێ دا بڕژینە. ئەنگوستیلک و دەمژمێرێ ب زوویی ڤەکە بەری کو ئەندام بوەرمیت.","سووتنا کیمیایی: جلێن پیس ڤەکە و پێستی ب ئاڤەکا گەلەک یا ڕەوان بۆ ماوێ ٢٠ خولەک یان پتر بشۆ، و وەرەقا SDS یا ماددەی بپشکنە.","سووتنا کارەبێ: ئێکەم کار کارەبێ ببڕە! پاشان سووتنێ وەک سووتنا گەرمیێ سار بکە و گازی ١٢٢ بکە، چونکو کارەبا دشێت زیانێ ب دلی و ناڤ لەشی بگەهینیت.","ئاگەهداری: بلقێن سووتنێ نەتەقینە، و سەهۆل، دۆهن، مەعجوونا ددانان، یان مەرهەمێن بێ ڕێنمایا پزیشکی بکار نەئینە."]},{heading:"٤. شکەستن و بریندارییێن ستوینا پشتێ",body:"ل دەمێ کەفتنا ژ جهێن بلند یان گومانا شکەستنێ:",points:["جێگیرکرن (Splinting): ئەگەر گومانا شکەستنێ هەبوو، ئەندامێ بریندار نەلڤینە. وەک کو هەی، ب دارەکێ یان کارتۆنەکێ جێگیر بکە دا ئێش کێم ببیت.","پاراستنا پشت و ستۆی: ئەگەر کەسەک ژ جهەکێ بلند کەفت، نەلڤینە مەگەر جه مەترسیدار بیت (وەک ئاگر)، چونکو لڤاندن دشێت ببیتە ئەگەرێ ئیفلیجبوونێ. سەری جێگیر بگرە و گازی ١٢٢ بکە.","سارکرن: بۆ کێمکرنا وەرمێ (Swelling)، سەهۆلێ د پارچە قوماشەکێ دا بپێچە و بۆ ماوێ ٢٠ خولەک بدانە سەر جهێ ئێشانێ؛ سەهۆلێ ڕاستەوخۆ نەدانە سەر پێستی."]},{heading:"٥. لێدانا کارەبێ و ڕزگارکرن",body:"کارەبا دشێت دلی ڕاوەستینیت؛ ڤان ڕێکاران جێبەجێ بکە:",points:["ئێکسەر کارەبێ ببڕە: هەتا کارەبا نەهێتە بڕین دەست ل برینداری نەدە، چونکو کارەبا دێ تە ژی گریت.","جوداکرنا سەلامەت: ئەگەر نەشیای کارەبێ ببڕی و ڤۆلتێج نزم بوو، ب دارەکێ هشک یان پلاستیکی تێلێ ژ برینداری دوور بێخە و ل سەر تشتەکێ هشک ڕاوەستە. نێزیکی هێلێن ڤۆلتێج بلند نەبە و گازی ١١٥ بکە.","پشکنینا پزیشکی: هەمی کەسێن کارەبا لێدای، حەتا ئەگەر هەست ب باشیێ بکەن ژی، دڤێت بچنە نەخۆشخانێ بۆ پشکنینا دلی؛ گازی ١٢٢ بکە."],critical:!0}],media:[{kind:"video",src:"media/videos/cpr_factory.mp4",title:"CPR و هەوارهاتنا ئێکێ",description:"ڕاهێنانا CPR و هاریکاریا برینداران ل کارگەهان"}],quiz:[{question:"د CPR دا، دڤێت لەزا فشارێن سنگی د خولەکەکێ دا چەند بیت؟",options:[{text:"٥٠-٧٠",correct:!1},{text:"٨٠-٩٠",correct:!1},{text:"١٠٠-١٢٠",correct:!0},{text:"١٤٠-١٦٠",correct:!1}],explanation:"ل دویڤ AHA 2025، لەزا فشاران ١٠٠-١٢٠ فشار د خولەکەکێ دا یە، ب کویراتیا ٥-٦ سم بۆ مەزنان، دا خوین بگەهیتە مێشکی."},{question:"ئەگەر تشتەکێ تیژ د ناڤ برینێ دا چەقی بوو، دێ چ کەی؟",options:[{text:"دەردئینم",correct:!1},{text:"ل جهێ خوە دهێلم و گازی ١٢٢ دکەم",correct:!0},{text:"دەستێ خوە ژێ دوور دئێخم و چ ناکەم",correct:!1},{text:"ب ئاڤێ دشۆم",correct:!1}],explanation:"دەرئینانا تشتی دێ خوینبەربوونێ زێدە کەت. دڤێت ل جهێ خوە بمینیت و جێگیر بهێتە کرن هەتا پزیشک ل نەخۆشخانێ دەردئینیت."},{question:"ئەگەر کارەبا ل کەسەکی دابیت، ئێکەم کارێ تو دکەی چییە؟",options:[{text:"دەستێ وی دگرم",correct:!1},{text:"CPR دکەم",correct:!1},{text:"کارەبێ دبڕم",correct:!0},{text:"ئاڤێ ب سەر دا دکەم",correct:!1}],explanation:"دڤێت ئێکەم جار سەرچاڤێ کارەبێ بهێتە بڕین دا کارەبا تە ژی نەگریت؛ پاشان گازی ١٢٢ بکە و ئەگەر پێدڤی بوو دەست ب CPR بکە."}]},{id:6,code:"CHEM-106",icon:"FlaskConical",accent:"#16a34a",title:"ماددەیێن کیمیایی (SDS)",subtitle:"Chemical Safety & Labelling",summary:"مامەلەکرن دگەل ماددەیێن کیمیایی و ناسینا مەترسیێن وان",blocks:[{body:"ماددەیێن کیمیایی ل کارگەهان دشێن ببنە ئەگەرێ سووتنا پێستی، ژەهراویبوونێ، ئاگری، یان تەقینێ."},{heading:"١. وەرەقا SDS چییە؟",body:"وەرەقا زانیاریێن سەلامەتیێ (Safety Data Sheet — SDS) زانیاریێن هەر ماددەیەکی د ١٦ پشکان دا ددەت، ژ وان:",points:["پێکهاتەیا ماددەی و مەترسیێن وی.","کیش PPE پێدڤییە (ماسک، دەستکێش، بەرچاڤک).","هەوارهاتنا ئێکێ ئەگەر ماددە بەر لەشی کەفت، و ڕێکێن ڤەمراندنا ئاگری."]},{heading:"٢. هێمایێن GHS",body:"هندەک ژ نیشانێن ل سەر قوتی و عەلبان:",points:["گڕ (Flame): ماددەیێ سووتەنێ.","کەلەسەر و هەستی (Skull and Crossbones): ماددەیێ ژەهراوی یێ کوژەر.","خوارن (Corrosion): ماددەیێ ئاسیدی یان ئەلکالی کو پێست و کانزایان دخوت."]}],media:[{kind:"image",src:"media/images/ghs_pictograms.png",title:"SDS",description:"نیشانێن مەترسیێ یێن GHS"}],quiz:[{question:"ل کیڤە دشێین بزانین کا کیش ماسک بۆ ماددەیەکێ کیمیایی پێدڤییە؟",options:[{text:"ل نیشانێن سەر دیواری",correct:!1},{text:"د وەرەقا SDS دا",correct:!0},{text:"ژ هەڤالێ خوە بپرسە",correct:!1},{text:"پێدڤی ب ماسکێ نینە",correct:!1}],explanation:"وەرەقا SDS هەمی زانیاریێن پاراستنێ یێن تایبەت ب وی ماددەی ددەت، ژ وان جۆرێ PPE یێ پێدڤی (پشکا ٨)."},{question:"هێمایا کەلەسەر و هەستی (Skull and Crossbones) ل سەر قوتیەکێ چ دگەهینیت؟",options:[{text:"ماددەیەکێ سووتەنێ کو ب هێسانی ئاگر دگریت",correct:!1},{text:"ماددەیەکێ ژەهراوی یێ کوژەر",correct:!0},{text:"ماددەیەکێ ئاسیدی یان ئەلکالی کو پێست و کانزایان دخوت",correct:!1},{text:"ماددەیەکێ کو تەنێ زیانێ دگەهینیتە ژینگەهێ",correct:!1}],explanation:"کەلەسەر و هەستی نیشانا ماددەیێ ژەهراوی یێ کوژەرە؛ گڕ (Flame) نیشانا ماددەیێ سووتەنێ یە، و خوارن (Corrosion) نیشانا ماددەیێ ئاسیدی یان ئەلکالی یە."},{question:"ژبلی مەترسیان و PPE یا پێدڤی، وەرەقا SDS چ زانیاریێن دی ددەت؟",options:[{text:"بهایێ ماددەی و ناڤێ فرۆشیاری",correct:!1},{text:"دەمێن پاقژکرنا کۆگەها ماددەیێن کیمیایی",correct:!1},{text:"ناڤێن وان کارگەران یێن دشێن بکاربینن",correct:!1},{text:"هەوارهاتنا ئێکێ و ڕێکێن ڤەمراندنا ئاگری",correct:!0}],explanation:"وەرەقا SDS زانیاریێن هەر ماددەیەکی د ١٦ پشکان دا ددەت، ژ وان: مەترسی، PPE یا پێدڤی، هەوارهاتنا ئێکێ ئەگەر ماددە بەر لەشی کەفت، و ڕێکێن ڤەمراندنا ئاگری."}]},{id:7,code:"HGHT-107",icon:"Construction",accent:"#0284c7",title:"کارکرن ل جهێن بلند",subtitle:"Fall Protection & Ladders",summary:"ڕێگرتن ل کەفتنێ ژ داربەست، بان، و پەیژەیان",blocks:[{body:"کەفتنا ژ جهێن بلند ئێک ژ ئەگەرێن سەرەکی یێن مرنێ یە ل کارگەه و جهێن ئاڤاهیسازیێ."},{heading:"١. پاراستن دژی کەفتنێ",body:"هەر کارەکێ ل بلندیێ (OSHA: ژ ١٫٢ مەتران ل کارگەهان و ژ ١٫٨ مەتران ل ئاڤاهیسازیێ) پێدڤی ب ڤان تشتانە:",points:["هارنەس (Full Body Harness): ب دروستی و ب قایمی لبەرکرن.","تێلا سەلامەتیێ (Lanyard): دڤێت ب خالەکا گرێدانێ یا قایم (Anchor Point) ڤە بیت.","ڕێلێن پاراستنێ (Guardrails): ل دۆرا داربەست، بان، و لێڤێن ڤەکری."]},{heading:"٢. سەلامەتیا پەیژێ (Ladders)",body:"ڕێسایا ٣ خالێن پێگرتنێ:",points:["هەمیشە دڤێت ٣ ئەندامێن لەشی (دوو پێ و دەستەک، یان دوو دەست و پێیەک) ل سەر پەیژێ بن.","گۆشەیا دانانا پەیژێ دڤێت ٤:١ بیت (بۆ هەر ٤ مەترێن بلندیێ، بنێ پەیژێ مەترەکێ ژ دیواری دوور بیت)."]}],media:[{kind:"video",src:"media/videos/fall_protection.mp4",title:"کارکرن ل بلندیێ",description:"بکارئینانا هارنەسی"}],quiz:[{question:"ڕێسایا ٣ خالان ل سەر پەیژێ واتە چییە؟",options:[{text:"نە پتر ژ ٣ کەسان پێکڤە ل سەر پەیژێ بن",correct:!1},{text:"٣ خولەک ل سەر بمینە",correct:!1},{text:"هەمیشە ٣ ئەندامێن لەشی ب پەیژێ ڤە بن",correct:!0},{text:"پەیژێ ب ٣ تێلان ببەستە",correct:!1}],explanation:"ڕێسایا ٣ خالان بۆ هندێ یە کو کارگەر هەڤسەنگیا خوە ژ دەست نەدەت و نەکەڤیت."},{question:"پەیژەیەک ٤ مەتران ل سەر دیواری بلند دبیت. دڤێت بنێ وێ چەند ژ دیواری دوور بیت؟",options:[{text:"نیڤ مەتر",correct:!1},{text:"١ مەتر",correct:!0},{text:"٢ مەتر",correct:!1},{text:"٤ مەتر",correct:!1}],explanation:"گۆشەیا دانانا پەیژێ دڤێت ٤:١ بیت: بۆ هەر ٤ مەترێن بلندیێ، بنێ پەیژێ مەترەکێ ژ دیواری دوور بیت."},{question:"دڤێت تێلا سەلامەتیێ (Lanyard) یا هارنەسی ب کیڤە ڤە بهێتە گرێدان؟",options:[{text:"ب پشتوێنا ئامێرێن کارگەری ب خوە ڤە",correct:!1},{text:"ب وێ پەیژێ ڤە یا کارگەر ل سەر ڕاوەستیای",correct:!1},{text:"ب خالەکا گرێدانێ یا قایم (Anchor Point) ڤە",correct:!0},{text:"ب هەر بۆری یان کێبلەکا نێزیک ڤە",correct:!1}],explanation:"تێلا سەلامەتیێ دڤێت ب خالەکا گرێدانێ یا قایم (Anchor Point) ڤە بیت، و هارنەس دڤێت ب دروستی و ب قایمی بهێتە لبەرکرن."}]},{id:8,code:"CONF-108",icon:"Container",accent:"#9333ea",title:"جهێن تەنگ و داخستی",subtitle:"Confined Space Safety",summary:"کارکرن د ناڤ تانک، بۆری، و مەنهۆلان دا",blocks:[{body:"جهێن داخستی مەترسیدارن چونکو هەوا تێدا ناهێتە گوهۆڕین، ئۆکسجین دشێت کێم ببیت، و غازێن کوژەر تێدا کۆم دبن."},{heading:"١. مەترسیێن سەرەکی",body:"بەری تو بچیە ژوور، بزانە:",points:["کێمیا ئۆکسجینێ (کێمتر ژ ١٩٫٥٪): دبیتە ئەگەرێ خەندقینێ.","غازێن ژەهراوی وەک CO (بێ بێهن) و H₂S (کو ل چڕیێن بلند هەستا بێهنێ ڕادگریت).","مەترسیا ئاگر و تەقینێ ئەگەر غاز یان هەلمێن سووتەنێ هەبن."]},{heading:"٢. ڕێکارێن چوونا ژوورێ",body:"دڤێت ئەڤ مەرجە هەبن:",points:["پشکنینا هەوای ب ئامێرێ پیڤانا غازێ (Gas Monitor) بەری چوونێ و ل دەمێ کاری.","هەبوونا چاڤدێرەکی (Attendant) کو ل دەرڤە بمینیت، چاڤێ وی ل کارگەرێ ژوورێ بیت، و ب چ ڕەنگان نەچیتە ژوور.","مۆلەتا کاری (Permit)، ئامرازێن پەیوەندیێ، و پلانا ڕزگارکرنێ دڤێت ئامادە بن."]}],media:[{kind:"image",src:"media/images/confined_entry.png",title:"جهێن داخستی",description:"پشکنینا هەوای"}],quiz:[{question:"ئەرێ دروستە چاڤدێرێ دەرڤە بێی ئامێر بچیتە ژوور بۆ ڕزگارکرنا هەڤالێ خوە؟",options:[{text:"بەلێ، ژبەر مرۆڤاتیێ",correct:!1},{text:"نەخێر، چونکو ئەو ژی دێ خەندقیت",correct:!0},{text:"بەلێ، ئەگەر هەناسا خوە بگریت",correct:!1},{text:"بەلێ، ئەگەر هەڤکار گەلەک نێزیکی دەرگەهی بیت",correct:!1}],explanation:"ل دویڤ لێکۆلینێن NIOSH، بەشەکێ مەزن ژ مرنێن جهێن داخستی ئەو کەسن یێن بێی ئامێر و ڕاهێنان چوویینە ژوور بۆ ڕزگارکرنێ. چاڤدێر دڤێت گازی تیما ڕزگارکرنێ و ١١٥ بکەت."},{question:"کەنگی دڤێت هەوایێ جهێ داخستی ب ئامێرێ پیڤانا غازێ (Gas Monitor) بهێتە پشکنین؟",options:[{text:"تەنێ جارەکێ، ل ڕۆژا ئێکێ یا کاری",correct:!1},{text:"تەنێ ئەگەر کەسەکی بێهنا تشتەکێ نەئاسایی کر",correct:!1},{text:"پشتی ب دوماهیک هاتنا کاری",correct:!1},{text:"بەری چوونا ژوورێ و ل دەمێ کاری",correct:!0}],explanation:"پشکنینا هەوای بەری چوونێ و ل دەمێ کاری دهێتە کرن، چونکو ئۆکسجین دشێت کێم ببیت و غازێن کوژەر کۆم ببن؛ CO بێ بێهنە، ژبەر هندێ بێهنکرن نابیتە پشکنین."},{question:"د ناڤ تانکەکێ دا، کارگەرەک ژ نشکەکێ ڤە بێهنا H₂S ناکەت. ئەڤە دشێت چ بگەهینیت؟",options:[{text:"غاز چوویە و هەوا بۆ هەناسێ سەلامەتە",correct:!1},{text:"غازێ هەستا بێهنێ ڕاگرتبیت",correct:!0},{text:"فەنا هەواگوهۆڕینێ ب دروستی کار دکەت",correct:!1},{text:"غاز بوویە هەلمەکا ئاڤێ یا بێ زیان",correct:!1}],explanation:"H₂S ل چڕیێن بلند هەستا بێهنێ ڕادگریت، ژبەر هندێ نەکرنا بێهنێ نە واتە کو غاز چوویە؛ تەنێ ئامێرێ پیڤانا غازێ (Gas Monitor) نیشان ددەت کا هەوا سەلامەتە یان نە."}]},{id:9,code:"NOIS-109",icon:"Ear",accent:"#db2777",title:"دەنگ و پاراستنا گوهان",subtitle:"Hearing Conservation",summary:"پاراستن دژی دەنگەدەنگا ئامێرێن مەزن",blocks:[{body:"کەڕبوون یان کێمبوونا بهیستنێ ژبەر دەنگێ کارگەهان هێدی هێدی چێدبیت و چارەسەر نابیت."},{heading:"١. ئاستێن دەنگی",body:"کەنگی دەنگ دبیتە مەترسی؟",points:["٨٥ dB(A): سنوورێ دەستپێکرنا مەترسیێ بۆ ٨ دەمژمێرێن کاری.","١٠٠ dB(A): بێی پاراستن تەنێ بۆ ١٥ خولەک د ڕۆژێ دا سەلامەتە (NIOSH).","نیشانە: ئەگەر پشتی کاری تە هەست ب زڕەزڕێ (Tinnitus) د گوهێن خوە دا کر، دەنگ گەلەک بلند بوویە."]},{heading:"٢. کەرەستەیێن پاراستنێ",body:"کەرەستەیێن پاراستنا گوهان (Hearing Protection Devices — HPD):",points:["گوهگرێن ناڤ گوهی (Earplugs): ئەگەر ب دروستی بهێنە دانان، پاراستنەکا باش ددەن.","گوهگرێن سەر گوهی (Earmuffs): ب هێسانی دهێنە لبەرکرن و بۆ دەنگێن بلند گونجاینە.","بکارئینانا هەردووکان پێکڤە ل جهێن گەلەک ب دەنگ."]}],media:[{kind:"video",src:"media/videos/hearing_protection.mp4",title:"دەنگ",description:"چەوا گوهگران بکار دئینی؟"}],quiz:[{question:"ئەگەر دەنگ گەهشتە ١٠٠ dB(A)، ل دویڤ NIOSH چەند دەم دشێی بێی گوهگر بمینی؟",options:[{text:"٤٥ خولەک",correct:!1},{text:"١٥ خولەک",correct:!0},{text:"٤ دەمژمێر",correct:!1},{text:"دەوامەکێ تەمام یێ ٨ دەمژمێران",correct:!1}],explanation:"ل دویڤ NIOSH، هەر ٣ dB زێدەبوون دەمێ سەلامەت دکەتە نیڤ: ٨٥ dB(A) بۆ ٨ دەمژمێران، و ١٠٠ dB(A) تەنێ بۆ ١٥ خولەک."},{question:"پشتی کاری، تە هەست ب زڕەزڕێ (Tinnitus) د گوهێن خوە دا کر. ئەڤە چ دگەهینیت؟",options:[{text:"گوهێن تە ب دەنگی ڕاهاتینە",correct:!1},{text:"دەنگ گەلەک بلند بوویە",correct:!0},{text:"گوهگرێن ناڤ گوهی گەلەک تەنگ بوون",correct:!1},{text:"ئاساییە و چ واتە نینە",correct:!1}],explanation:"زڕەزڕا گوهان پشتی کاری نیشانە کو دەنگ گەلەک بلند بوویە؛ کێمبوونا بهیستنێ هێدی هێدی چێدبیت و چارەسەر نابیت، ژبەر هندێ گوهگران بکاربینە."},{question:"ل جهێن گەلەک ب دەنگ، دڤێت پاراستنا گوهان چەوا بیت؟",options:[{text:"پەمبوو ل جهێ گوهگران",correct:!1},{text:"بێ پاراستن، بەلێ ب بێهنڤەدانێن کورت",correct:!1},{text:"گوهگرێن ناڤ گوهی و سەر گوهی پێکڤە",correct:!0},{text:"دانانا دەستان ل سەر گوهان دەمێ دەنگ بلند دبیت",correct:!1}],explanation:"ل جهێن گەلەک ب دەنگ هەردووکان پێکڤە بکاربینە: گوهگرێن ناڤ گوهی ئەگەر ب دروستی بهێنە دانان پاراستنەکا باش ددەن، و گوهگرێن سەر گوهی ب هێسانی دهێنە لبەرکرن و بۆ دەنگێن بلند گونجاینە."}]},{id:10,code:"ERGO-110",icon:"Package",accent:"#0d9488",title:"هەلگرتنا باران (Ergonomics)",subtitle:"Safe Lifting Techniques",summary:"ڕێگرتن ل ئێشانا پشتێ و ماسوولکەیان",blocks:[{body:"برینداربوونا پشتێ ئێک ژ بەلاڤترین برینانە ل کارگەهان، ژبەر هەلگرتنا خەلەت یا باران."},{heading:"١. ڕێکارا دروست یا هەلگرتنێ",body:"جێبەجێکرنا ڤان هەنگاڤان پشتێ دپارێزیت:",points:["چۆکێن خوە بچەمینە: هێزا پێیان بکاربینە، نە یا پشتێ.","باری نێزیکی لەشی بکە: هندی بار ژ تە دوورتر بیت، فشار ل سەر پشتێ زێدەتر دبیت.","پشتا خوە ڕاست ڕاگرە: دەمێ تشتەکێ گران هەلدگری، پشتا خوە نەچەمینە.","لەشێ خوە نەبادە: ئەگەر تە ڤیا باری بەرەڤ لایەکی ببەی، ب پێیان ب هەمی لەشی ڤە بزڤڕە."]}],media:[{kind:"image",src:"media/images/safe_lifting.png",title:"هەلگرتنا باری",description:"شێوازێ دروست"}],quiz:[{question:"ل دەمێ هەلگرتنا تشتەکێ گران، دڤێت هێز ل سەر چ بیت؟",options:[{text:"ماسوولکەیێن پشتا خوارێ",correct:!1},{text:"ماسوولکەیێن پێیان",correct:!0},{text:"ماسوولکەیێن ملان",correct:!1},{text:"تەنێ دەست",correct:!1}],explanation:"ماسوولکەیێن پێیان ب هێزترن و پشتێ ژ برینداربوونێ دپارێزن."},{question:"دەمێ هەلگرتنا بارەکێ گران، دڤێت بار ل کیڤە بیت؟",options:[{text:"ب درێژاهیا دەستان، دوور ژ لەشێ تە",correct:!1},{text:"ل سەر سەرێ تە",correct:!1},{text:"ل لایەکێ لەشێ تە",correct:!1},{text:"نێزیکی لەشێ تە",correct:!0}],explanation:"باری نێزیکی لەشی بکە: هندی بار ژ تە دوورتر بیت، فشار ل سەر پشتێ زێدەتر دبیت."},{question:"پێدڤییە باری بەرەڤ لایەکی ببەی. چەوا دزڤڕی؟",options:[{text:"لەشێ خوە دبادم و پێیان ل جهێ وان دهێلم",correct:!1},{text:"ب پێیان ب هەمی لەشی ڤە دزڤڕم",correct:!0},{text:"پشتا خوە بەرەڤ جهێ نوو دچەمینم",correct:!1},{text:"باری ب لەز دهاڤێمە لایێ دی دا هێزا کێمتر بکاربینم",correct:!1}],explanation:"لەشێ خوە نەبادە: ئەگەر تە ڤیا باری بەرەڤ لایەکی ببەی، ب پێیان ب هەمی لەشی ڤە بزڤڕە و پشتا خوە ڕاست ڕاگرە."}]},{id:11,code:"GAS-111",icon:"Wind",accent:"#0891b2",title:"غاز و هەواگوهۆڕین",subtitle:"Ventilation & Toxic Gases",summary:"کۆنترۆلکرنا هەوای و غازێن ژەهراوی",blocks:[{body:"هەواگوهۆڕینا دروست ل کارگەهێ گرنگە بۆ ڕێگرتن ل کۆمبوونا تۆز و غازێن کو دبنە ئەگەرێ نەخۆشیێن هەناسێ."},{heading:"١. مۆنۆکسیدا کاربۆنێ (CO)",body:"غازا کوژەر یا بێدەنگ:",points:["بێ ڕەنگ و بێ بێهنە.","ژ سووتنا سووتەمەنیێ و مەکینەیێن بەنزین و دیزلێ (وەک جەنەڕەیتەر و فۆرکلیفت) پەیدا دبیت.","نیشانە: سەرئێشان، گێژبوون، دلتێکهاتن، و بێهۆشبوون. ئەگەر هەست ب ڤان نیشانان کر، ئێکسەر دەرکەڤە دەرڤە و گازی ١٢٢ بکە."]},{heading:"٢. جۆرێن هەواگوهۆڕینێ",body:"چەوا هەوا دهێتە گوهۆڕین؟",points:["هەواگوهۆڕینا سرۆشتی: دەرگەه و پەنجەرێن ڤەکری.","هەواگوهۆڕینا دەستکرد: فەن و سیستەمێن ڕاکێشانا هەوای (Local Exhaust).","پاراستنا کەسی: ماسکێن فلتەردار ل دویڤ SDS؛ بەلێ ماسکێن فلتەری دژی CO و کێمیا ئۆکسجینێ ناپارێزن."]}],media:[{kind:"video",src:"media/videos/ventilation_safety.mp4",title:"غاز",description:"غازا CO"}],quiz:[{question:"بۆچی غازا CO مەترسیدارە؟",options:[{text:"چونکو بێهنا وێ خرابە",correct:!1},{text:"چونکو ناهێتە دیتن و بێهنکرن",correct:!0},{text:"چونکو ڕەنگێ وێ سۆرە",correct:!1},{text:"چونکو تەنێ ب شەڤ پەیدا دبیت",correct:!1}],explanation:"ژبەر کو هەست پێ ناهێتە کرن، کارگەر بێی کو بزانن ژەهراوی دبن. ئامێرێن ناسینا CO (CO Detector) ل وان جهان دانە یێن مەکینە لێ کار دکەن."},{question:"ل دەمێ کاری ل نێزیک جەنەڕەیتەرەکێ کو کار دکەت، تو تووشی سەرئێشان، گێژبوون و دلتێکهاتنێ دبی. دێ چ کەی؟",options:[{text:"حەبەکا ئێشانێ دخوم و کاری بەردەوام دکەم",correct:!1},{text:"ل نک جەنەڕەیتەری ڕادوینم و بێهنا خوە ڤەددەم",correct:!1},{text:"ماسکەکا فلتەردار لبەر دکەم و دمینم",correct:!1},{text:"ئێکسەر دەردکەڤمە دەرڤە و گازی ١٢٢ دکەم",correct:!0}],explanation:"سەرئێشان، گێژبوون و دلتێکهاتن دشێن نیشانێن ژەهراویبوونا ب CO بن؛ ئێکسەر دەرکەڤە دەرڤە و گازی ١٢٢ بکە، چونکو CO ناهێتە دیتن و بێهنکرن."},{question:"ئەرێ ماسکا فلتەردار کارگەری ژ غازا CO دپارێزیت؟",options:[{text:"نەخێر، دژی CO ناپارێزیت",correct:!0},{text:"بەلێ، هەر ماسکەکا فلتەردار CO ڕادگریت",correct:!1},{text:"بەلێ، ئەگەر کێمتر ژ دەمژمێرەکێ بهێتە لبەرکرن",correct:!1},{text:"تەنێ ئەگەر فلتەر هەر ڕۆژ بهێتە گوهۆڕین",correct:!1}],explanation:"ماسکێن فلتەری ل دویڤ SDS دهێنە هەلبژارتن، بەلێ دژی CO و کێمیا ئۆکسجینێ ناپارێزن؛ ل وان جهێن مەکینە لێ کار دکەن، هەواگوهۆڕین و ئامێرێن ناسینا CO پێدڤینە."}]},{id:12,code:"EVAC-112",icon:"Megaphone",accent:"#dc2626",title:"دەرکەفتنا لەزگین (Evacuation)",subtitle:"Emergency Assembly Points",summary:"پلانا چوونا دەرڤە ل دەمێ ئاگری یان کارەساتێ",blocks:[{body:"زانینا ڕێکا دەرکەفتنێ دشێت جوداهیێ د ناڤبەرا ژیان و مرنێ دا بکەت."},{heading:"١. ڕێسایێن دەرکەفتنێ",body:"دەمێ زەنگا مەترسیێ لێدەت:",points:["ب هێمنی و ب لەز بمەشە، نەڕەڤە، و ئەسانسۆرێ بکار نەئینە.","دەرگەهان ل پشت خوە بگرە دا ئاگر و دوکێل بەلاڤ نەبن، بەلێ قوفل نەکە.","بەرەڤ خالا کۆمبوونێ (Assembly Point) بچە دا ژمارا کارمەندان بهێتە کرن.","ب چ ڕەنگان نەزڤڕە ژوور هەتا بەرپرسێ سەلامەتیێ یان تیمێن ١١٥ ڕێ نەدەن."]}],media:[{kind:"video",src:"media/videos/evacuation_drill.mp4",title:"ڕاهێنانا دەرکەفتنێ",description:"ڕاهێنانا دەرکەفتنێ"}],quiz:[{question:"دەمێ زەنگا مەترسیێ لێدەت، دێ چ کەی؟",options:[{text:"کۆمکرنا کەرەستەیێن خوە و پاشان دەرکەفتن",correct:!1},{text:"ب هێمنی بەرەڤ دەرکەفتنێ چوون",correct:!0},{text:"خوە ل بن مێزێ ڤەشارتن هەتا زەنگ ڕادوەستیت",correct:!1},{text:"هاوارکرن",correct:!1}],explanation:"دەرکەفتنا ب هێمنی و ب لەز باشترین ڕێکارە بۆ پاراستنا ژیانێ."},{question:"ل دەمێ دەرکەفتنێ، دێ چ ب دەرگەهان کەی؟",options:[{text:"قوفل دکەم دا کەس نەزڤڕیتە ژوور",correct:!1},{text:"ب تەمامی ڤەکری دهێلم دا دوکێل دەرکەڤیت",correct:!1},{text:"ل پشت خوە دگرم، بەلێ قوفل ناکەم",correct:!0},{text:"ب تشتەکی ڤەکری دهێلم بۆ وان تیمێن پاشان دگەهن",correct:!1}],explanation:"دەرگەهان ل پشت خوە بگرە دا ئاگر و دوکێل بەلاڤ نەبن، بەلێ قوفل نەکە."},{question:"تو ل خالا کۆمبوونێ یی. کەنگی دشێی بزڤڕیە ژوور؟",options:[{text:"هەر دەمێ زەنگا مەترسیێ ل ئاڤاهیێ ڕاوەستیا",correct:!1},{text:"دەمێ بەرپرسێ سەلامەتیێ یان تیمێن ١١٥ ڕێ ددەن",correct:!0},{text:"دەمێ چ دوکێل ژ پەنجەرەیان دەرنەکەڤیت",correct:!1},{text:"پشتی ١٠ خولەکان، ئەگەر چ ئاگر دیار نەبیت",correct:!1}],explanation:"ب چ ڕەنگان نەزڤڕە ژوور هەتا بەرپرسێ سەلامەتیێ یان تیمێن ١١٥ ڕێ نەدەن؛ ل خالا کۆمبوونێ ژمارا کارمەندان ژی دهێتە کرن."}]},{id:13,code:"WELD-113",icon:"Sparkles",accent:"#2563eb",title:"سەلامەتیا لەحیمکرنێ",subtitle:"Welding & Cutting Hazards",summary:"پاراستن ژ تیشک، گەرمی و دوکێلا لەحیمکرنێ",blocks:[{body:"کارێ لەحیمکرنێ مەترسیا تیشکێن سەرووبنەفشی (UV)، سووتنێن گران، و غاز و دوکێلێن ژەهراوی تێدایە."},{heading:"١. پاراستنا چاڤان و پێستی",body:"پێدڤیێن لەحیمکاران:",points:["کلاوێ پاراستنێ یێ لەحیمکرنێ (Welding Helmet) ب فلتەرێ گونجای: بۆ پاراستنا چاڤان ژ تیشکێن UV و ڕۆناهیا توند یا قەوسا لەحیمکرنێ (Arc).","دەستکێشێن چەرمی یێن درێژ: بۆ پاراستن ژ گەرمی و پریشکان.","بەروانکا چەرمی (Apron): بۆ پاراستنا لەشی."]},{heading:"٢. مەترسیا ئاگری (Hot Work)",body:"بەری دەستپێکرنێ مۆلەتا کارێ گەرم (Hot Work Permit) وەربگرە و:",points:["دۆرا جهێ کاری ژ ماددەیێن سووتەنێ پاقژ بکە (NFPA 51B: ب دووراتیا ١١ مەتران / ٣٥ پێ)، یان ب پەردێن بەرگری داپۆشە.","تەمرینکەکا گونجای ل نێزیک خوە ئامادە بکە.","چاڤدێرێ ئاگری (Fire Watch): ل دەمێ کاری و کێمترین ١ دەمژمێر پشتی ب دوماهیک هاتنا کاری ل جهی بمینیت؛ پاشان جه هەتا ٣ دەمژمێرێن دی دهێتە چاڤدێریکرن، ل دویڤ بڕیارا بەرپرسێ مۆلەتێ (NFPA 51B)."]}],media:[{kind:"image",src:"media/images/welding_safety.png",title:"لەحیمکرن",description:"لبەرکرنا دروست"}],quiz:[{question:"بۆچی پشتی لەحیمکرنێ چاڤدێرێ ئاگری کێمترین ١ دەمژمێر ل جهی دمینیت؟",options:[{text:"بۆ پاقژکرنا پارچێن ئاسنی یێن مایی",correct:!1},{text:"دا ئاگرەکێ ڤەشارتی پەیدا نەبیت",correct:!0},{text:"دا چاڤەڕێ بکەت هەتا ئاسنێ لحیمکری سار دبیت",correct:!1},{text:"چ پێدڤی نینە",correct:!1}],explanation:"گەلەک جاران پریشک دکەڤنە ناڤ قلیش و کەرەستەیان و پشتی دەمەکی ئاگری پەیدا دکەن. ل دویڤ NFPA 51B (چاپا ٢٠١٩ و پشتی هنگێ)، چاڤدێری کێمترین ١ دەمژمێر پشتی کاری بەردەوام دبیت."},{question:"بەری دەستپێکرنا کارێ گەرم (Hot Work)، دڤێت چ ب ماددەیێن سووتەنێ یێن دۆرا جهێ کاری بهێتە کرن؟",options:[{text:"ل جهێ خوە بمینن، چونکو چاڤدێرێ ئاگری دێ ل وێرێ بیت",correct:!1},{text:"بهێنە لادان یان ب پەردێن بەرگری بهێنە داپۆشین",correct:!0},{text:"جارەکێ ئاڤ ل سەر بهێتە ڕژاندن و ئێکسەر لەحیمکرن دەست پێ بکەت",correct:!1},{text:"بهێنە دانان ل پشت لەحیمکاری، دوور ژ پریشکێن ڕاستەوخوە",correct:!1}],explanation:"بەری دەستپێکرنێ مۆلەتا کارێ گەرم (Hot Work Permit) وەربگرە و دۆرا جهێ کاری ژ ماددەیێن سووتەنێ پاقژ بکە (NFPA 51B: ب دووراتیا ١١ مەتران / ٣٥ پێ)، یان ب پەردێن بەرگری داپۆشە."},{question:"چ چاڤێن لەحیمکاری ژ تیشکێن UV و ڕۆناهیا توند یا قەوسا لەحیمکرنێ دپارێزیت؟",options:[{text:"بەرچاڤکێن سەلامەتیێ یێن ئاسایی، وەک یێن بۆ تۆزێ",correct:!1},{text:"بەرچاڤکێن ڕۆژێ یێن ڕەش ل بن کلاوێ پاراستنێ",correct:!1},{text:"کلاوێ پاراستنێ یێ لەحیمکرنێ ب فلتەرێ گونجای",correct:!0},{text:"سەحکرن ل قەوسێ تەنێ بۆ چەند چرکەیان",correct:!1}],explanation:"کلاوێ پاراستنێ یێ لەحیمکرنێ (Welding Helmet) ب فلتەرێ گونجای چاڤان ژ تیشکێن UV و ڕۆناهیا توند یا قەوسا لەحیمکرنێ دپارێزیت؛ دەستکێشێن چەرمی یێن درێژ و بەروانکا چەرمی دەست و لەشی دپارێزن."}]},{id:14,code:"FORK-114",icon:"Forklift",accent:"#475569",title:"ئامێرێن ڤەگوهاستنێ",subtitle:"Forklift & Vehicle Safety",summary:"سەلامەتیا فۆرکلیفتێ و ئاژۆتنێ ل کارگەهێ",blocks:[{body:"فۆرکلیفت ئامێرەکێ گرانە و مەترسیا پەلچقاندنێ و وەرگەڕیانێ هەیە ئەگەر ب دروستی نەهێتە ئاژۆتن."},{heading:"١. ڕێسایێن ئاژۆتنێ",body:"بۆ شوفێرێن فۆرکلیفتێ:",points:["تەنێ کەسێن ڕاهێنای و مۆلەتدار دشێن فۆرکلیفتێ بئاژۆن (OSHA 1910.178).","چ جاران کەسەکی ل سەر شاخێن (Forks) فۆرکلیفتێ یان ل کێلەکا خوە هەلنەگرە.","بار ژ کاپاسیتیا ئامێری زێدەتر نەکە دا وەرنەگەڕیت، و پشتوێنا سەلامەتیێ گرێبدە.","ل هەر کونجەکێ یان دەرگەهەکێ لەزێ کێم بکە و هۆرنێ (Horn) لێبدە."]},{heading:"٢. سەلامەتیا پیادەیان",body:"ئەگەر تو ل نێزیک فۆرکلیفتێ دمەشی:",points:["چاڤێ تە ل شوفێری بیت (Eye Contact) و دووراتیەکا سەلامەت بهێلە.","د ڕێڕەوێن نیشانکری یێن پیادەیان دا بمەشە."]}],media:[{kind:"video",src:"media/videos/forklift_safety.mp4",title:"فۆرکلیفت",description:"ناسینا خالێن نەدیار (Blind Spots)"}],quiz:[{question:"ئەگەر شوفێرێ فۆرکلیفتێ بارەکێ بلند هەبیت و پێشیا خوە نەبینیت، دێ چ کەت؟",options:[{text:"ب لەز بئاژۆت",correct:!1},{text:"ب پاشڤە (Reverse) بئاژۆت",correct:!0},{text:"هۆرنێ لێبدەت و چاڤێن خوە بگریت",correct:!1},{text:"چ ژ ڤان نینە",correct:!1,fixed:!0}],explanation:"دەمێ بار دیتنا شوفێری دگریت، دڤێت ب پاشڤە بئاژۆت دا ڕێکا خوە ببینیت (OSHA 1910.178)."},{question:"هەڤالەکێ تە داخواز دکەت ل سەر شاخێن (Forks) فۆرکلیفتا تە سوار ببیت. دێ چ کەی؟",options:[{text:"دهێلم سوار ببیت ئەگەر ب هێدی بئاژۆم",correct:!1},{text:"دهێلم ل سەر شاخان ڕاوەستیت و خوە ب فۆرکلیفتێ ڤە بگریت",correct:!1},{text:"دهێلم ل کێلەکا من ڕوینیت ل جهێ شاخان",correct:!1},{text:"ڕەت دکەم، چونکو چ کەس نابیت ل سەر شاخان سوار ببیت",correct:!0}],explanation:"چ جاران کەسەکی ل سەر شاخێن فۆرکلیفتێ یان ل کێلەکا خوە هەلنەگرە؛ فۆرکلیفت ئامێرەکێ گرانە و مەترسیا پەلچقاندنێ و وەرگەڕیانێ هەیە."},{question:"تو ل نێزیک فۆرکلیفتەکێ دمەشی کو دلڤیت. دڤێت چ بکەی؟",options:[{text:"چاڤێ تە ل شوفێری بیت و دووراتیەکا سەلامەت بهێلی",correct:!0},{text:"ل نێزیک وێ بمەشی دا شوفێر تە باشتر ببینیت",correct:!1},{text:"ب لەز ل پێشیا وێ دەرباز ببی بەری بگەهیتە تە",correct:!1},{text:"دەستێ خوە بلڤینی و بەردەوام بی، چونکو شوفێر دڤێت ڕاوەستیت",correct:!1}],explanation:"ل نێزیک فۆرکلیفتێ، چاڤێ تە ل شوفێری بیت (Eye Contact)، دووراتیەکا سەلامەت بهێلە و د ڕێڕەوێن نیشانکری یێن پیادەیان دا بمەشە؛ شوفێر دشێت تە د خالێن نەدیار (Blind Spots) دا نەبینیت."}]},{id:15,code:"SIGN-115",icon:"AlertTriangle",accent:"#ea580c",title:"نیشانێن سەلامەتیێ",subtitle:"Safety Signs & Symbols",summary:"ناسینا ڕەنگ و هێمایێن سەلامەتیێ (ISO 7010)",blocks:[{body:"نیشانێن سەلامەتیێ ب زمانەکێ جیهانی ئاگەهداریێ ل سەر مەترسیان ددەنە مە."},{heading:"١. واتایا ڕەنگان (ISO 7010)",body:"هەر ڕەنگەک پەیامەکا تایبەت دگەهینیت:",points:["سۆر: قەدەغەکرن یان ئامێرێن ئاگرکوژیێ (نموونە: جگارەکێشان قەدەغەیە).","زەرد: ئاگەهداری و مەترسی (نموونە: مەترسیا کارەبێ).","شین: فەرز (نموونە: دڤێت کلاوێ پاراستنێ لبەر بکەی).","کەسک: سەلامەتی و دەرکەفتن (نموونە: دەرگەهێ دەرکەفتنێ)."]}],media:[{kind:"image",src:"media/images/safety_signs.png",title:"نیشانێن سەلامەتیێ",description:"هێمایێن ستاندارد"}],quiz:[{question:"نیشانەکا ب ڕەنگێ زەرد واتە چییە؟",options:[{text:"قەدەغەکرنا کارەکێ",correct:!1},{text:"ئاگەهداری و مەترسی",correct:!0},{text:"جهێ سەلامەت و ڕێکا ڕەڤینێ",correct:!1},{text:"بکارئینانا ئاڤێ",correct:!1}],explanation:'ڕەنگێ زەرد هەمیشە واتە "ئاگەهدار بە" یان "مەترسی هەیە".'},{question:"نیشانەکا شین ل بەر دەرگەهێ کارگەهێ وێنەیێ کلاوێ پاراستنێ نیشان ددەت. واتە چییە؟",options:[{text:"کلاوێ پاراستنێ ل ڤێرێ قەدەغەیە",correct:!1},{text:"ئاگەهداری: دبیت تشت ل ڤێرێ بکەڤن",correct:!1},{text:"دڤێت ل ڤێرێ کلاوێ پاراستنێ لبەر بکەی",correct:!0},{text:"کلاوێن پاراستنێ ل پشت ڤی دەرگەهی دهێنە هەلگرتن",correct:!1}],explanation:"ڕەنگێ شین واتە فەرز، وەک: دڤێت کلاوێ پاراستنێ لبەر بکەی؛ سۆر قەدەغەکرن یان ئامێرێن ئاگرکوژیێ یە، زەرد ئاگەهداری و کەسک سەلامەتی و دەرکەفتن."},{question:"کیش ڕەنگ بۆ سەلامەتی و دەرکەفتنێ دهێتە بکارئینان، وەک دەرگەهێ دەرکەفتنێ؟",options:[{text:"سۆر",correct:!1},{text:"زەرد",correct:!1},{text:"شین",correct:!1},{text:"کەسک",correct:!0}],explanation:"ڕەنگێ کەسک سەلامەتی و دەرکەفتنێ نیشان ددەت، وەک دەرگەهێ دەرکەفتنێ؛ سۆر بۆ قەدەغەکرنێ یان ئامێرێن ئاگرکوژیێ یە."}]},{id:16,code:"HOUS-116",icon:"ClipboardCheck",accent:"#4f46e5",title:"پاقژی (Housekeeping)",subtitle:"Order & Maintenance",summary:"ڕێکخستنا جهێ کاری بۆ کێمکرنا مەترسیان",blocks:[{body:"جهێ کاری یێ پاقژ جهەکێ سەلامەتە. گەلەک ڕووداو ژبەر خلیسکین و کەفتنا ب سەر کەرەستەیێن بەلاڤ دا ڕوودەن."},{heading:"١. ڕێسایێن گشتی",body:"بۆ هەمی کارگەران:",points:["پاقژکرنا ڕۆن یان ئاڤا ڕژای ب زووترین دەم.","کۆمکرنا پاشماوەیان د سەلکێن تایبەت دا.","هێلانا ڕێڕەو و دەرکەفتنان ڤەکری و بێ ئاستەنگ.","زڤڕاندنا هەر ئامێرەکی بۆ جهێ وی پشتی ب دوماهیک هاتنا کاری."]}],media:[{kind:"image",src:"media/images/clean_factory.png",title:"پاقژی",description:"نموونەیا جهەکێ پاقژ"}],quiz:[{question:"ئەگەر تە دیت ڕۆن ل سەر عەردی ڕژایە، دێ چ کەی؟",options:[{text:"وەکی خوە دهێلم هەتا پاقژکەر د دەوامێ دی دا دهێت",correct:!1},{text:"پاقژ دکەم یان نیشانەکێ لێ ددانم و ئاگەهدار دکەم",correct:!0},{text:"ب سەر دا باز ددەم",correct:!1},{text:"گوهـ نادەمێ",correct:!1}],explanation:"هەر کارگەرەک بەرپرسە ژ پاقژی و سەلامەتیا جهێ کارێ خوە، دا کەس نەکەڤیت."},{question:"دڤێت ڕێڕەو و دەرکەفتن چەوا بهێنە هێلان؟",options:[{text:"ڤەکری و بێ ئاستەنگ",correct:!0},{text:"بۆ دانانا قوتیان دەمێ کۆگەهـ تژی دبیت",correct:!1},{text:"بۆ دەمەکێ کورت ل دەمێ کاری گرتی",correct:!1},{text:"تەنێ بەری سەرەدانا پشکنینێ ڤەکری",correct:!1}],explanation:"ڕێڕەو و دەرکەفتنان ڤەکری و بێ ئاستەنگ بهێلە؛ گەلەک ڕووداو ژبەر خلیسکین و کەفتنا ب سەر کەرەستەیێن بەلاڤ دا ڕوودەن."},{question:"تە کارێ خوە ب دوماهیک ئینا. دێ چ ب وان ئامێران کەی یێن تە بکارئیناین؟",options:[{text:"ل سەر عەردی دهێلم بۆ دەوامێ پاشان",correct:!1},{text:"هەر ئامێرەکی دزڤڕینمە جهێ وی",correct:!0},{text:"دگەل پاشماوەیان دکەمە د سەلکێ دا",correct:!1},{text:"ل ڕێڕەوێ نێزیکی دەرکەفتنێ کۆم دکەم",correct:!1}],explanation:"پشتی ب دوماهیک هاتنا کاری هەر ئامێرەکی بزڤڕینە جهێ وی و پاشماوەیان د سەلکێن تایبەت دا کۆم بکە؛ کەرەستەیێن بەلاڤ دبنە ئەگەرێ خلیسکین و کەفتنێ."}]},{id:17,code:"QUAK-117",icon:"Activity",accent:"#d97706",title:"عەردەهەژین ل کارگەهان",subtitle:"Earthquake Safety in Factories",summary:"سەلامەتیا کارگەران ل دەمێ عەردەهەژینێ و پشتی وێ",blocks:[{body:"عەردەهەژین ل کارگەهان مەترسیەکا دووقات پەیدا دکەت: هەم هەژینا ب خوە، و هەم کەفتنا ئامێرێن گران، ڕژانا ماددەیێن کیمیایی، شکەستنا بۆریان، و دزەکرنا غازێ. دڤێت هەر کارگەهەک پلانەکا عەردەهەژینێ هەبیت."},{heading:"١. خوە بدە عەردی، خوە بپارێزە، خوە بگرە (Drop, Cover, Hold On)",body:"ل دەمێ عەردەهەژینێ:",points:["خوە بدە عەردی (Drop) و بچە بن مێزەکێ یان مێزا کاری (Workbench) یا قایم — دوور ژ ئامێرێن گران، ڕەفان، و شووشەیان.","ئەگەر مێز نەبوو، ل نک دیوارەکێ ناڤخوەیی ب چۆکان ڕوینە و سەر و ستۆیێ خوە ب دەستان داپۆشە (Cover).","ب مێزێ ڤە بگرە (Hold On) هەتا هەژین ب تەمامی دوەستیت.","نەڕەڤە و نەچە بن ئامێران یان نک ڕەفان! ئامێرێن گران و ڕەف دشێن بلڤن یان بکەڤنە سەر تە."]},{heading:"٢. پشتی عەردەهەژینێ",body:"پشتی هەژین دوەستیت:",points:["ئامێران بۆ زیانێ بپشکنە، و ئامێرێن زیانلێکەفتی هەلنەکە هەتا بهێنە پشکنین.","ببینە کا ماددەیێن کیمیایی ڕژاینە یان نە، و ژ وان دوور بکەڤە.","ئەگەر بێهنا غازێ هات — ب لەز دەرکەڤە، کارگەهێ ڤالا بکە، و ژ دەرڤە گازی ١١٥ بکە.","تەنێ کارمەندێن ڕاهێنای و دەستنیشانکری غازێ دبڕن، و تەنێ ئەگەر بێهنا وێ هات یان دەنگێ دزەکرنێ هات و گەهشتن بۆ کێلۆنا غازێ سەلامەت بیت، بێ چوونا د وی جهی دا یێ غاز لێ کۆم بوویە و بێ چێکرنا چ چرووسکان؛ کارەبێ ببڕە ئەگەر زیان ب تێل یان تابلۆیان گەهشتبیت.","بەری زڤڕینا ژوور، دڤێت ئەندازیارەک ئاڤاهیێ کارگەهێ بۆ قلیشان بپشکنیت."]},{heading:"٣. ئامادەبوون",body:"پلانا پێشوەخت:",points:["بۆ هەر پشکەکێ پلانا عەردەهەژینێ ئامادە بکە.","ئامێرێن گران ب زنجیر یان بۆلتان جێگیر بکە.","دەبە و قوتیێن کیمیایی ل سەر ڕەفێن نزم و جێگیر دانە.","ڕێڕەوێن دەرکەفتنێ هەمیشە ڤەکری بن.","هەر ٦ هەیڤان جارەکێ ڕاهێنانێ بکە."]}],media:[{kind:"image",src:"media/images/factory_earthquake.png",title:"عەردەهەژین",description:"عەردەهەژین ل کارگەهێ"}],quiz:[{question:"ل دەمێ عەردەهەژینێ ل کارگەهەکێ، ئێکەم کار چییە؟",options:[{text:"ئێکسەر ب ڕێکا نێزیکترین دەرگەهی ڕەڤین بەرەڤ دەرڤە",correct:!1},{text:"خوە بدە عەردی و بچە بن مێزەکێ قایم",correct:!0},{text:"بەری هەر تشتەکێ دی هەمی ئامێران ڤەمرینە",correct:!1},{text:"بچە نێزیکی پەنجەرەیان",correct:!1}],explanation:"خوە بدە عەردی، خوە بپارێزە، خوە بگرە — ئێکەم ڕێکارە ل ناڤ ئاڤاهیان، دوور ژ ئامێر، ڕەف، و شووشەیان."},{question:"پشتی عەردەهەژینێ ل کارگەهەکا کیمیایی، ئێکەم پشکنین چییە؟",options:[{text:"پیڤەر و تابلۆیێن کارەبێ",correct:!1},{text:"ڕژانا ماددەیێن کیمیایی",correct:!0},{text:"بۆرییێن ئاڤێ",correct:!1},{text:"هێلێن تەلەفۆنێ",correct:!1}],explanation:"ڕژانا ماددەیێن کیمیایی مەترسیەکا مەزنە پشتی عەردەهەژینێ و پێدڤییە ب لەز بهێتە پشکنین."},{question:"پشتی هەژین دوەستیت، تو بێهنا غازێ ل کارگەهێ دکەی. دێ چ کەی؟",options:[{text:"دچمە نک کێلۆنا غازێ و ب خوە دبڕم",correct:!1},{text:"فەنێن ڕاکێشانا هەوای هەلدکەم دا غاز دەرکەڤیت",correct:!1},{text:"ب لەز دەردکەڤم و ژ دەرڤە گازی ١١٥ دکەم",correct:!0},{text:"ئێکەمجار ب تەلەفۆنا خوە گازی ١١٥ دکەم، پاشان دەردکەڤم",correct:!1}],explanation:"ئەگەر بێهنا غازێ هات، ب لەز دەرکەڤە، کارگەهێ ڤالا بکە و ژ دەرڤە گازی ١١٥ بکە؛ تەنێ کارمەندێن ڕاهێنای و دەستنیشانکری غازێ دبڕن، و تەنێ ئەگەر گەهشتن بۆ کێلۆنێ سەلامەت بیت، بێ چوونا د وی جهی دا یێ غاز لێ کۆم بوویە و بێ چێکرنا چ چرووسکان."}]},{id:18,code:"FLOOD-118",icon:"Waves",accent:"#2563eb",title:"لافاو و ئاڤبەربوون",subtitle:"Flood Emergency in Industrial Areas",summary:"پاراستنا کارگەه و کارگەران ل دەمێ لافاوێ",blocks:[{body:"لافاو دشێت کارگەهان ب تەمامی وێران بکەت: ئامێران خراب بکەت، ماددەیێن کیمیایی بەلاڤ بکەت، و کارەبێ بکەتە مەترسی. کارگەهێن نێزیکی ڕووبار و گەلیان پتر د مەترسیێ دانە."},{heading:"١. بەری لافاوێ",body:"ئامادەبوون:",points:["ئاگەهدارییێن کەشناسیێ (Meteorology) بشۆپینە.","کەرەستەیێن گرنگ و ماددەیێن کیمیایی بگوهێزە جهەکێ بلند.","سیستەمێ کارەبێ بۆ بڕینا خوەکار (Auto-shutoff) ئامادە بکە.","کیسێن لمێ (Sandbags) ل بەر دەرگەه و بنیاتا کارگەهێ دانە."]},{heading:"٢. ل دەمێ لافاوێ",body:"ڕێکارێن لەزگین:",points:["ئەگەر ب سەلامەتی بشێی و ئاڤ نەگەهشتبیتە تابلۆیێن کارەبێ، کارەبێ و غازێ ببڕە؛ د ناڤ ئاڤێ دا دەست ل کارەبێ نەدە!","نەچە ناڤ ئاڤا لافاوێ — ١٥ سم ئاڤا ب لەز دشێت مرۆڤی بێخیت، و ٣٠ سم دشێت ترومبێلێ ببەت.","بچە جهەکێ بلند — نهۆما دووێ یان سەر بانی.","گازی ١١٥ بکە و ل جهێ خوە بمینە هەتا تیمێن ڕزگارکرنێ دگەهن."]},{heading:"٣. پشتی لافاوێ",body:"زڤڕین و پاقژکرن:",points:["نەچە ناڤ کارگەهێ هەتا ئەندازیار پشتڕاست نەکەت کو ئاڤاهی سەلامەتە.","دەست ل ماددەیێن کیمیایی یێن ئاڤ تێکەفتی نەدە — ب ڕێکا ١١٥ تیما ماددەیێن مەترسیدار (HazMat) بخوازە.","کارەبێ ڤەنەکە هەتا سیستەم ژ لایێ کارەباچیەکێ شارەزا ڤە بهێتە پشکنین.","وێنەیێن هەمی زیانان بگرە بۆ بیمە و ڕاپۆرتێ."]}],media:[{kind:"image",src:"media/images/factory_flood.png",title:"لافاو",description:"لافاو ل کارگەهێ"}],quiz:[{question:"ل دەمێ لافاوێ ل کارگەهەکێ، ئێکەم کار چییە؟",options:[{text:"ئامێران بپارێزە ب داپۆشینا وان ب نایلۆنێن مەزن",correct:!1},{text:"کارەبێ و غازێ ببڕە، ئەگەر ب سەلامەتی بشێی",correct:!0},{text:"بچە مال",correct:!1},{text:"بەری هەر تشتەکێ دی ئاڤێ ب پەمپێ دەربێخە",correct:!1}],explanation:"کارەبا و غاز مەترسیێن ئێکەمن ل دەمێ لافاوێ؛ بەلێ ئەگەر ئاڤ گەهشتبیتە تابلۆیان، نێزیک نەبە و بچە جهەکێ بلند."},{question:"چەند ئاڤا ب لەز دشێت مرۆڤەکی بێخیت؟",options:[{text:"٥٠ سم",correct:!1},{text:"٧٥ سم",correct:!1},{text:"١٥ سم",correct:!0},{text:"١ مەتر",correct:!1}],explanation:"نەچە ناڤ ئاڤا لافاوێ: ١٥ سم ئاڤا ب لەز دشێت مرۆڤی بێخیت، و ٣٠ سم دشێت ترومبێلێ ببەت. بچە جهەکێ بلند و گازی ١١٥ بکە."},{question:"پشتی لافاوێ، تە دەبەیێن ماددەیێن کیمیایی دیتن کو ئاڤا لافاوێ گەهشتبوو وان. دێ چ کەی؟",options:[{text:"ب ئاڤا پاقژ دشۆم و دزڤڕینمە سەر ڕەفێ",correct:!1},{text:"دەستێ خوە لێ نادەم و ب ڕێکا ١١٥ تیما HazMat دخوازم",correct:!0},{text:"ب دەستێن خوە دبەمە دەرڤە بەری ئاڤ دیسا بلند ببیت",correct:!1},{text:"ڤەدکەم دا ببینم کا ئاڤ چوویە ناڤ دا یان نە",correct:!1}],explanation:"دەست ل ماددەیێن کیمیایی یێن ئاڤ تێکەفتی نەدە — ب ڕێکا ١١٥ تیما ماددەیێن مەترسیدار (HazMat) بخوازە."}]},{id:19,code:"FACT-119",icon:"Siren",accent:"#dc2626",title:"بەرسڤدانا بەرگرییا شارستانی ل کارگەهان",subtitle:"Industrial CD Response & Multi-Agency Coordination",summary:"پێکهاتنا تیما بەرسڤدانێ یا کارگەهێ ل دەمێ ڕووداوان و هەماهەنگی دگەل ١١٥",blocks:[{body:"کارگەهێن مەزن (نەفت، غاز، کیمیا، پۆلا) دڤێت تیمێن خوە یێن بەرسڤدانا تەنگاڤیێ هەبن کو بەری گەهشتنا تیمێن ١١٥ کار بکەن. ستانداردا NFPA 600 (Facility Fire Brigades) ڕێکخستن، ڕاهێنان، و ئامێرێن تیمێن ئاگرکوژیێ یێن کارگەهان دیار دکەت. خولەکێن ئێکێ یێن ڕووداوی گەلەک گرنگن، ژبەرهندێ تیما کارگەهێ دڤێت ئامادە و ڕاهێنای بیت."},{heading:"١. پێکهاتنا تیما بەرسڤدانێ یا کارگەهێ (ERT)",body:"بنەمایێن سەرەکی یێن تیما بەرسڤدانا تەنگاڤیێ (Emergency Response Team):",points:["قەبارەیا تیمێ: ل دویڤ هەلسەنگاندنا مەترسیێن کارگەهێ و ئەرکێن تیمێ دهێتە دیارکرن؛ NFPA 600 ڕێژەیەکا جێگیر یا ئەندامان بۆ ژمارا کارمەندان دیار ناکەت.","ڕاهێنان: ل دویڤ ئەرکێن هەر ئەندامەکی، دگەل ڕاهێنانا دووبارە (Refresher) ب کێمی سالێ جارەکێ.","فەرماندەرێ ڕووداوی (Incident Commander — IC): تەنێ ئێک کەس فەرمانێ ددەت، دا فەرمان تێکەل نەبن.","ئەرکێن سەرەکی: ڤەمراندنا ئاگری، ڕزگارکرن، هەوارهاتنا ئێکێ، و ڤالاکرنا ئاڤاهی.","پەیوەندی: بێتەل (Radio) ب کەنالەکێ تایبەت، و مۆبایل وەک ڕێکا یەدەگ.","دەمێ بەرسڤدانێ: ل پلانێ دا دیار بکە، ب ڕاهێنانان بپیڤە، و باشتر بکە.","پێشنیار: خولێن ICS-100 و ICS-200 (FEMA) بۆ فێربوونا سیستەمێ فەرماندەریا ڕووداوی."]},{heading:"٢. پلانا بەرسڤدانا تەنگاڤیێ (ERP)",body:"پلانا بەرسڤدانا تەنگاڤیێ (Emergency Response Plan) ل دویڤ ستانداردان:",points:["پلانا کارێ تەنگاڤیێ دڤێت ب نڤیسین بیت و ل کارگەهێ بەردەست بیت؛ کارگەهێن ١٠ کارمەند یان کێمتر دشێن ب دەڤی ڕابگەهینن (OSHA 29 CFR 1910.38).","پشکێن سەرەکی: ئەرک، ڕێکار، ڕێکێن دەرکەفتنێ، پەیوەندی، ژێدەر، ڕاهێنان، و هەلسەنگاندنا پشتی ڕووداوی.","خالێن کۆمبوونێ (Assembly Points): ئێکا سەرەکی و ئێکا یەدەگ، ل جهەکێ سەلامەت و دوور ژ ئاڤاهی و ڕێکا ترومبێلێن تەنگاڤیێ.","ڕێکێن دەرکەفتنێ: ب گشتی کێمترین ٢ ڕێک ژ هەر نهۆمەکێ (NFPA 101، ب هندەک بەدەرکرنان).","زەنگا ئاگری (Alarm): دڤێت ل هەمی جهێن ئاڤاهی بهێتە بهیستن یان دیتن (NFPA 72).","تیما هەوارهاتنا ئێکێ: د هەر دەوامەکێ (Shift) دا کارمەندێن ڕاهێنانا هەوارهاتنا ئێکێ و CPR وەرگرتی هەبن.","ڕاهێنان (Drill): ب ڕێک و پێک، و ئەنجامێن هەر ڕاهێنانەکێ بهێنە تۆمارکرن.","هەلسەنگاندنا پشتی ڕووداوی (Post-Response Critique): ب زووترین دەم پشتی هەر ڕووداوەکی."]},{heading:"٣. هەماهەنگی دگەل بەرگرییا شارستانی (١١٥)",body:"دەمێ ڕووداو چێدبیت و تیمێن ١١٥ دگەهن، دڤێت ERT ڤان هەنگاڤان بکەت:",points:["١. ئێکسەر گازی ١١٥ بکە، و ١٢٢ ئەگەر بریندار هەبن.","٢. زانیاریێن سەرەکی بدە: جه، جۆرێ ڕووداوی، ژمارا برینداران، ماددەیێن مەترسیدار، و ڕێکا گەهشتنێ.","٣. نەخشێ کارگەهێ (Site Map) ل بەر دەرگەهی ئامادە بکە، دگەل جهێن مەترسیێ و جهێن بڕینا کارەبێ و غازێ.","٤. کەسێ پەیوەندیێ (Liaison Officer): تەنێ ئێک کەس پەیوەندیێ دگەل ١١٥ دکەت.","٥. وەرەقێن SDS بۆ هەمی ماددەیێن کیمیایی ئامادە بکە.","٦. ناڤ و گۆتنێن شاهدان تۆمار بکە.","٧. ڤەگوهاستنا فەرمانێ: دەمێ ١١٥ دگەهیت، فەرمان دچیتە دەستێ فەرماندەرێ ١١٥ و ERT هاریکاریێ دکەت.","٨. بەلگەنامە: وێنە، ڤیدیۆ، و تۆمارا ڕووداوی (Incident Log) بۆ لێکۆلینێ و بیمێ."]},{heading:"٤. کارکرن دگەل تیما ماددەیێن مەترسیدار (HazMat)",body:"بۆ ڕووداوێن کیمیایی، تیما HazMat پێدڤییە:",points:["ئاستێن ڕاهێنانا HazMat (OSHA 1910.120 و NFPA 470، کو NFPA 472 تێدا هاتیە کۆمکرن):","• ئاستێ هشیاریێ (Awareness): ناسینا مەترسیێ، دوورکەفتن، و ئاگەهدارکرن — بۆ هەمی کارمەندان.","• ئاستێ کارپێکرنێ (Operations): پاراستنا خەلکی و دەوروبەری ب ڕێکێن بەرگری (Defensive) ژ دوور.","• ئاستێ تەکنیکی (Technician): ڕاگرتنا دزەکرنێ ژ نێزیک (Offensive) ب PPE یا تایبەت.","• ئاستێ پسپۆر (Specialist): زانیاریێن کویر ل سەر ماددەیێن دیارکری و پشتەڤانیا تەکنیکیان.","سێ ناڤچە: ناڤچا گەرم (Hot Zone)، ناڤچا نیڤەگەرم (Warm Zone)، و ناڤچا سار (Cold Zone).","ئاستێن PPE یێن HazMat: A، B، C، D (A بلندترین پاراستنە).","پاقژکرنا پیسبوونێ (Decontamination) ل ناڤچا نیڤەگەرم دهێتە کرن، بەری چوونا ناڤچا سار.","کارمەندێن نەڕاهێنای ناچنە ناڤچا گەرم؛ چاڤەڕێی تیمێن ١١٥ بن.","پلانا کارگەهێ دڤێت دیار بکەت کا تیمێن تایبەت یێن ماددەیێن مەترسیدار چەوا ب ڕێکا ١١٥ دهێنە داخوازکرن."]},{heading:"٥. بەرسڤدانا چەند دەزگەهان پێکڤە (Multi-Agency Response)",body:"ڕووداوێن مەزن پێدڤی ب چەند دەزگەهان دبن:",points:["١١٥ بەرگرییا شارستانی: ڤەمراندنا ئاگری، ڕزگارکرن، و ماددەیێن مەترسیدار.","١٢٢ ئەمبوولانس: چارەسەرکرنا پزیشکی و ڤەگوهاستنا برینداران.","١٠٤ پۆلیس: گرتنا دەوروبەری، هاتوچۆ، و لێکۆلینا یاسایی.","دەزگەهێن ئاسایشێ: ل دەمێ گومانا تەقەمەنیان یان تیرۆرێ — ب ڕێکا ١٠٤ دهێنە ئاگەهدارکرن.","وەزارەتا تەندروستیێ: ئامادەکرنا نەخۆشخانێن نێزیک.","فەرمانگەها کارەبێ: بڕینا کارەبێ ل دەوروبەری.","دەزگەهێن ئاڤێ و غازێ: بڕینا هێلێن ئاڤێ و غازێ.","دەستەیا ژینگەهێ: ئەگەر ماددەیێن کیمیایی د ژینگەهێ دا بەلاڤ بوون.","ناڤەندا کارێن تەنگاڤیێ (EOC): بۆ ڕووداوێن مەزن کو گەلەک دەزگەهـ تێدا بەشدار دبن."]},{heading:"٦. قۆناغێن بەرسڤدانێ (٥ قۆناغ)",body:"هەر ڕووداوەک ب ڤان ٥ قۆناغان دا دبۆریت:",points:["١. ناسین (Detection): سێنسۆر، زەنگا ئاگری، یان شاهد.","٢. ئاگەهدارکرن (Notification): گازیکرنا ١١٥، و ئاگەهدارکرنا ERT و کەسێ پەیوەندیێ.","٣. بەرسڤدان (Response): ERT کار دکەت هەتا تیمێن ١١٥ دگەهن.","٤. کێمکرنا مەترسیێ (Mitigation): ڤەمراندنا ئاگری، ڕزگارکرن، و پاقژکرنا پیسبوونێ.","٥. ڤەگەڕان (Recovery): پاقژکرن، شیکارکرن، و هەلسەنگاندنا پشتی ڕووداوی.","دڤێت هەر قۆناغەک بهێتە تۆمارکرن (Incident Action Plan — IAP).","دەمژمێرا زێڕین (Golden Hour): چارەسەریا لەز پشتی برینداربوونا گران شانسێ ژیانێ زێدە دکەت — ژبەرهندێ گازیکرنا لەز بۆ ١٢٢ گرنگە."]},{heading:"٧. مەشق و ڕاهێنان (Drills & Training)",body:"ڕاهێنان بنەمایێ ئامادەبوونێ یە (خشتەیا پێشنیارکری):",points:["ڕاهێنانا سەر مێزێ (Tabletop Exercise): هەر ٣ هەیڤان جارەکێ — سەناریۆ ل سەر مێزێ.","ڕاهێنانا کاری (Functional Drill): هەر ٦ هەیڤان جارەکێ — تەنێ تیما ERT، نە هەمی ئاڤاهی.","ڕاهێنانا تەمام (Full-Scale Drill): سالێ جارەکێ — هەمی کارگەهـ دگەل ١١٥.","هەلسەنگاندن: ڕاپۆرتا پشتی ڕاهێنانێ (After-Action Report) ب زووترین دەم.","ڕاهێنانا ERT: ب بەردەوامی و ل دویڤ ئەرکان، کێمترین سالێ جارەکێ.","ستانداردێن شارەزاییێ: NFPA 1081 (Facility Fire Brigade Member)، OSHA 1910 Subpart L، و ICS-100/200.","ڕاهێنانا هەڤپشک دگەل ١١٥: سالێ جارەکێ بۆ هەماهەنگیێ."]}],media:[{kind:"video",src:"media/videos/fact_ert_response.mp4",title:"ڕاهێنانا بەرسڤدانا ERT",description:"ڕاهێنانا تەمام ل کارگەهەکا نەفتێ"},{kind:"image",src:"media/images/fact_ics_chart.png",title:"پەیکەرێ فەرماندەریا ڕووداوی (ICS)",description:"پەیکەرێ فەرماندەریا ڕووداوی (ICS)"}],quiz:[{question:"قەبارەیا تیما بەرسڤدانا تەنگاڤیێ (ERT) ل کارگەهێ چەوا دهێتە دیارکرن؟",options:[{text:"ب ڕێژەیەکا جێگیر: ١ ئەندامێ ڕاهێنای بۆ هەر ١٠٠ کارمەندان د هەر دەوامەکێ دا",correct:!1},{text:"ل دویڤ هەلسەنگاندنا مەترسیێن کارگەهێ و ئەرکێن تیمێ",correct:!0},{text:"ب ڕێژەیەکا جێگیر: ١ بۆ ٢٠٠ کارمەندان",correct:!1},{text:"ب ڕێژەیەکا جێگیر: ١ بۆ ٢٥ کارمەندان",correct:!1}],explanation:"NFPA 600 ڕێژەیەکا جێگیر یا ئەندامان بۆ ژمارا کارمەندان دیار ناکەت؛ هەر کارگەهەک ل دویڤ مەترسی و ئەرکێن خوە قەبارەیا تیمێ دیار دکەت."},{question:"دەمژمێرا زێڕین (Golden Hour) چ واتە یە؟",options:[{text:"دەمژمێرا ئێکێ ژ هەر دەوامەکێ، دەمێ هەمی پشکنینێن سەلامەتیێ دڤێت بهێنە کرن",correct:!1},{text:"دەمێ دەستپێکێ پشتی برینداربوونا گران، کو چارەسەریا لەز تێدا گەلەک گرنگە",correct:!0},{text:"دەمێ نیڤرۆ",correct:!1},{text:"گەرمیا ڕۆژێ",correct:!1}],explanation:"Golden Hour ئەو دەمە یێ پشتی برینداربوونا گران کو گەهاندنا لەز یا برینداری بۆ چارەسەریێ شانسێ ژیانێ زێدە دکەت؛ ژبەرهندێ ئێکسەر گازی ١٢٢ بکە."},{question:"ل سیستەمێ ICS، کەسێ پەیوەندیێ (Liaison Officer) چ کار دکەت؟",options:[{text:"ئاگری ڤەدمرینیت",correct:!1},{text:"پەیوەندیێ دگەل دەزگەهێن دەرڤە دکەت",correct:!0},{text:"CPR دکەت",correct:!1},{text:"دەرگەهی دپارێزیت و چاڤدێریا هاتنا ژوورێ دکەت",correct:!1}],explanation:"کەسێ پەیوەندیێ (Liaison Officer) پەیوەندیێ دگەل ١١٥، پۆلیس (١٠٤)، ئەمبوولانس (١٢٢)، و دەزگەهێن دی دکەت."},{question:"ئاستێ Operations یێ HazMat چ کار دکەت؟",options:[{text:"تەنێ ئاگەهدارکرن",correct:!1},{text:"بەرگری (Defensive) — ڕێگرتنا بەلاڤبوونێ ژ دوور",correct:!0},{text:"Offensive — چوونا ناڤ ناڤچا گەرم بۆ گرتنا دزەکرنێ ژ نێزیک",correct:!1},{text:"پسپۆری (Specialist)",correct:!1}],explanation:"ئاستێ Operations بەرگرییە (Defensive): ڕێگرتنا بەلاڤبوونا ماددەی ژ دوور، نە کارێ ژ نێزیک (Offensive)."},{question:"ناڤچا گەرم (Hot Zone) ل HazMat چییە؟",options:[{text:"جهەکێ سار و سەلامەت کو بنکەیا فەرماندەیێ و تیمێن پشتەڤانیێ لێ دمینن",correct:!1},{text:"ئەو ناڤچە یا کو مرۆڤ و کەرەستە بەری دەرکەفتنێ تێدا ژ پیسبوونێ دهێنە پاقژکرن",correct:!1},{text:"ناڤچا هەرە مەترسیدار — تەنێ تەکنیکیێن HazMat ب PPE یا گونجای",correct:!0},{text:"ناڤچا کۆمبوونێ",correct:!1}],explanation:"ناڤچا گەرم جهێ ماددەیێ مەترسیدارە؛ تەنێ تەکنیکیێن HazMat ب PPE یا ئاستێ A یان B دچنە ناڤ."},{question:"دەمێ تیمێن ١١٥ دگەهنە جهێ ڕووداوی، فەرمان دچیتە دەستێ کێ؟",options:[{text:"ERT بەردەوام دبیت",correct:!1},{text:"فەرماندەرێ ١١٥",correct:!0},{text:"ڕێڤەبەرێ کارگەهێ",correct:!1},{text:"پۆلیس",correct:!1}],explanation:"ڤەگوهاستنا فەرمانێ (ICS Transfer): دەمێ ١١٥ دگەهیت، فەرمان دچیتە دەستێ فەرماندەرێ ١١٥ و ERT هاریکاریێ دکەت."}]},{id:20,code:"FACT-120",icon:"FlameKindling",accent:"#dc2626",title:"پۆلینکرنا ئاگری ل کارگەهان",subtitle:"Industrial Fire Classes — NFPA 30/484/654",summary:"پۆلینکرنا تایبەت بۆ کارگەهان: شلەمەنی، غاز، کانزا، و تۆزا سووتەنێ",blocks:[{body:"ئەڤ مۆدیولە سیستەمێ NFPA بکار دئینیت: A تشتێن ڕەق، B شلەمەنی و غازێن سووتەنێ، C ئامێرێن کارەبێ، D کانزا، K ڕۆنێ مەتبەخێ. پۆلێن ئاگری ل ڤێرێ ب پیتێن NFPA 10 هاتینە نڤیسین وەک ژێدەرێ پرۆژەی؛ سیستەمێ فەرمی یێ دهۆکێ هێشتا نەهاتییە پشتڕاستکرن. بەرامبەرێن EN 2: NFPA A = EN A؛ NFPA B (شلەمەنی) = EN B؛ NFPA B (غاز) = EN C؛ NFPA C (ئامێرێن کارەبێ یێن کارەبا تێدا) چو پۆل د EN دا نینە؛ NFPA D = EN D؛ NFPA K = EN F. ستانداردێن تایبەت ل کارگەهان: شلەمەنییێن سووتەنێ (NFPA 30)، کانزایێن سووتەنێ (NFPA 484)، و تۆزا سووتەنێ (NFPA 654). ژ چاپا ٢٠٢٥ ڤە، NFPA 484 و NFPA 654 د ستانداردا NFPA 660 دا هاتینە کۆمکرن."},{heading:"١. پۆلا A — تشتێن ڕەق یێن سووتەنێ ل کارگەهێ",body:"تشتێن ڕەق یێن بەلاڤ ل کارگەهان:",points:["سووتەمەنی: کاغەز، کارتۆن، قوماش، دار، لاستیک، پلاستیک، و پالێت (Pallets).","ئەڤ ماددە خەلووز و ئاگرێ ڤەشارتی دهێلن؛ پشتی ڤەمراندنێ جهی ب ئاڤێ سار بکە و چاڤدێری بکە.","ل کارگەهان: کۆگەهێن کاغەز و کارتۆنان و پالێتێن داری ئاگری ب لەز بەلاڤ دکەن.","تەمرینک: ئاڤ، کەف، تۆزا ABC.","پالێتێن ڤالا یێن کۆمکری مەترسیەکا مەزنن: ب بلندی کۆم نەکە، و ل دەرڤە یان ل جهەکێ ب سپرینکلەر هەلگرە.","ستاندارد: NFPA 13 (سیستەمێن سپرینکلەری)، کو پاراستنا کۆگەهان ژی تێدایە.","نموونە ل کارگەهان: کۆگەهـ و هێلێن پاکێتکرنێ (Packaging Lines)."]},{heading:"٢. پۆلا B — شلەمەنییێن سووتەنێ ل کارگەهێ",body:"ئێک ژ مەترسیدارترین پۆلان ل کارگەهان:",points:["سووتەمەنی: بەنزین، نەفت، دیزل، ئەسیتۆن (Acetone)، تۆلوین (Toluene)، زایلین (Xylene).","خالا هەلبوونێ (Flash Point): بەنزین نێزیکی -٤٣°C، ئەسیتۆن -٢٠°C، دیزل ٥٢°C یان پتر.","سنوورێن تەقینێ (LEL/UEL): کێمترین و زێدەترین چڕیا هەلمێ د هەوای دا کو دشێت بگریت:","• بەنزین: ١٫٤-٧٫٦٪.","• ئەسیتۆن: ٢٫٥-١٢٫٨٪.","• میتانۆل (Methanol): ٦-٣٦٪.","تەمرینک: کەف (AFFF یان کەفا بێ فلۆرین)، CO₂، تۆزا ABC. بۆ ئەسیتۆن، میتانۆل، ئەلکهول و شلەمەنیێن جەمسەری (polar solvents) یێن دی: CO₂، تۆزا هشک یان کەفا بەرگرێ ئەلکهولێ (AR foam)؛ کەفا ئاسایی ل سەر وان تێک دچیت.","جەتا ئاڤێ ل سەر شلەمەنیێ نەڕژینە — ئاگری بەلاڤ دکەت. BLEVE (Boiling Liquid Expanding Vapor Explosion) دەمێ تانکەکا ب فشار ب ئاگری گەرم دبیت چێدبیت.","پۆلێن شلەمەنیان ل دویڤ NFPA 30 (Flash Point = خالا هەلبوونێ، Boiling Point = خالا کەلینێ):","• Class I (Flammable): خالا هەلبوونێ کێمتر ژ ٣٧٫٨°C — IA (هەلبوون < ٢٢٫٨°C و کەلین < ٣٧٫٨°C)، IB (هەلبوون < ٢٢٫٨°C و کەلین ٣٧٫٨°C یان پتر)، IC (هەلبوون ٢٢٫٨ هەتا < ٣٧٫٨°C).","• Class II (Combustible): خالا هەلبوونێ ٣٧٫٨ هەتا < ٦٠°C.","• Class III (Combustible): IIIA ژ ٦٠ هەتا < ٩٣°C، و IIIB ٩٣°C یان پتر.","دیوارێن ڕاگرتنێ (Diking): ل دویڤ NFPA 30، قەبارەیا جهێ ڕاگرتنێ دڤێت کێمتر نەبیت ژ وێ شلەمەنیا کو ژ مەزنترین تانکا تژی دشێت بڕژیت (١٠٠٪)؛ ڕێژەیا ١١٠٪ ل هندەک یاسا و ڕێنمایێن دی دهێتە خواستن (بۆ ئاڤا بارانێ ژی).","چڕیا هەلمێ (Vapor Density): هەلما بەنزینێ ژ هەوای گرانترە (نێزیکی ٣-٤ جاران) و ل جهێن نزم کۆم دبیت."]},{heading:"٣. غازێن سووتەنێ — NFPA: پۆلا B، EN 2: پۆلا C",body:"غازێن کارگەهان: ئەسیتیلین، پرۆپان، هایدرۆجین:",points:["سەرچاڤە: ئەسیتیلین (Acetylene) بۆ لەحیمکرنێ، پرۆپان (Propane) بۆ هندەک فۆرکلیفتان، هایدرۆجین (Hydrogen) ژ بارکرنا باتریێن ئاسیدی (Lead-acid).","ئەڤ غازە ل گەرمیا ئاسایی غازن و ب هێسانی دگرن. سنوورێن تەقینێ ل هەوای: هایدرۆجین ٤-٧٥٪، پرۆپان ٢٫١-٩٫٥٪، ئەسیتیلین ژ ٢٫٥٪ و پتر. (-٢٥٣°C خالا کەلینا هایدرۆجینێ یە، نە خالا هەلبوونێ.)","گەرمیا گڕا ئۆکسی-ئەسیتیلین (Oxy-Acetylene) ژ ٣٠٠٠°C پترە.","ئەسیتیلین دگەل مسی (Copper) ماددەیەکێ تەقەمەنی چێدکەت (Copper Acetylide)؛ بۆری و ئامێرێن مسی یێن نەگونجای بکار نەئینە.","ڤەمراندن: ئێکەم، ئەگەر بێ مەترسی بیت، ڤالڤا غازێ بگرە. ئاگرێ غازێ ڤەنەمرینە ئەگەر نەشێی هاتنا غازێ ڕاوەستینی — غازا دزەکری دشێت تەقینێ چێبکەت.","تیمێن ١١٥ سپرەیا ئاڤێ (Water Spray) ژ دوور بۆ سارکرنا سیلەندەر و تانکان بکار دئینن، نە بۆ ڤەمراندنا گڕا غازێ.","ئامێرێن ناسینا غازێ (Gas Detectors) ل کۆگەهێن غازێ: زەنگا ئاگەهداریێ دڤێت گەلەک بەری گەهشتنا LEL لێبدەت (ب گشتی ل ١٠-٢٠٪ یێن LEL).","ل کارگەهان: جهێن لەحیمکرنێ، جهێن بارکرنا فۆرکلیفتان، و ژوورێن باتریان."]},{heading:"٤. پۆلا D — کانزایێن سووتەنێ (NFPA 484)",body:"کانزایێن سووتەنێ — ئێک ژ مەترسیدارترین جۆران:",points:["سووتەمەنی: مەگنیسیۆم، تیتانیۆم، تۆزا ئەلەمنیۆمێ، سۆدیۆم، و لیتیۆمێ کانزایی (Lithium Metal).","ئەڤ کانزا ب گەرمیەکا گەلەک بلند دسوژن و ڕۆناهیەکا گەلەک توند ددەن؛ ڕاستەوخۆ بەرێ خوە نەدە گڕێ.","ئاڤ قەدەغەیە! Mg + H₂O → MgO + H₂ (هایدرۆجین پەیدا دبیت و دشێت بتەقیت).","CO₂ قەدەغەیە! 2Mg + CO₂ → 2MgO + C (مەگنیسیۆم د CO₂ دا ژی دسوژیت).","تەنێ تەمرینکێن پۆلا D، و تەنێ ئەو یا کو ناڤێ وی کانزای ل سەر لایبلا وێ هاتی: ماددە ژ کانزایەکێ بۆ یێ دی جودایە (بۆ نموونە تۆزا ل سەر بنەمایێ کلۆریدا سۆدیۆمێ (NaCl) یان گرافیت؛ تۆزا مسی بۆ لیتیۆمێ). چ جاران ئاڤ، تۆزا ئاسایی یان کەف بکار نەئینە. لمێ هشک تەنێ ئەگەر پلانا ئاگری یا جهی یان SDS یا کانزای ناڤێ وی بینیت و تەمام هشک بیت.","نموونە ل کارگەهان: هەلاندنا ئەلەمنیۆمێ، تراشکرنا مەگنیسیۆمێ، و باتریێن لیتیۆمێ کانزایی.","NFPA 484: هەلگرتن، مامەلەکرن، و پاراستنا کانزایێن سووتەنێ (ئێستا پشکەک ژ NFPA 660).","تۆزا ئەلەمنیۆمێ: مەترسیا تەقینا تۆزێ ژی هەیە (NFPA 654 / 660).","بەرسڤ: ئێکسەر گازی ١١٥ بکە و تەنێ تەمرینکا پۆلا D بکاربینە یا کو ناڤێ وی کانزای ل سەر لایبلا وێ هاتی. باتریێن لیتیۆم-ئایۆن (Li-ion) لیتیۆمێ کانزایی تێدا نینە و ب ئاڤێ سار دبن."]},{heading:"٥. تۆزا سووتەنێ — تەقینا تۆزێ (NFPA 654)",body:"مەترسیەکا کوژەر ل کارگەهان:",points:["پێنجگۆشەیا تۆزێ (Dust Pentagon): سووتەمەنی (تۆز) + ئۆکسجین + گەرمی + بەلاڤبوون د هەوای دا + جهێ داخستی.","سەرچاڤە: ئارد، شەکر، دار، خەلووز، تۆزا کانزایان، و پلاستیک.","کێمترین گەرمیا هەلبوونێ (MIT) ل دویڤ جۆرێ تۆزێ دگوهۆڕیت؛ ل SDS یان ئەنجامێن تاقیکرنا تۆزێ بنێڕە.","کێمترین چڕیا تەقینێ (MEC) ژی ل دویڤ جۆرێ تۆزێ دگوهۆڕیت؛ تۆزا بەلاڤ د هەوای دا هەمیشە مەترسیدارە.","تەقینا ئێکێ (Primary): د ناڤ ئامێرەکێ دا (وەک فلتەر یان ئاشی).","تەقینا دووێ (Secondary): تەقینا ئێکێ تۆزا ل سەر عەرد و ڕەف و بۆریان بلند دکەت، و تەقینەکا مەزنتر و کوژەرتر چێدبیت.","کێمکرنا مەترسیێ: سیستەمێن کۆمکرنا تۆزێ، دەرگەهێن ڤالاکرنا تەقینێ (Explosion Vents)، و سیستەمێن ڤەمراندنێ.","پاقژی: چینەکا تۆزێ ب ستویریا ٠٫٨ ملم (1/32 inch) ل سەر پتر ژ ٥٪ یێ ڕووبەرێ عەردی دشێت مەترسیێ پەیدا بکەت (NFPA 654 / OSHA).","نموونە: ل سالا ٢٠٠٨ ل کارگەها شەکری Imperial Sugar (ئەمریکا)، تەقینا تۆزا شەکری ١٤ کارگەر کوشتن (CSB).","ستاندارد: NFPA 654 (ئێستا NFPA 660) و OSHA 29 CFR 1910.272 (بۆ کۆگەهێن دانەوێلان)."]},{heading:"٦. قۆناغێن گەشەکرنا ئاگری ل کارگەهێ",body:"٤ قۆناغێن ستاندارد — ل کارگەهان ئاگر دشێت لەزتر بیت:",points:["دەستپێک (Incipient): ئاگرەکێ بچووک — کەسەکێ ڕاهێنان دیتی دشێت ب تەمرینکا دەستی یا گونجای ڤەمرینیت، پشتی دانا ئاگەهداریێ و گازیکرنا ١١٥، و ڕێکا دەرکەفتنێ ل پشت وی بیت؛ ئەگەر ئێکسەر ڤەنەمری، دەرکەڤە.","گەشەکرن (Growth): ئاگر و دوکێل ب لەز زێدە دبن و سپرینکلەر کار دکەن — دەرکەڤە و گازی ١١٥ بکە.","گەشەکرنا تەمام (Fully Developed): پشتی Flashover — تەنێ تیمێن ١١٥.","کێمبوون (Decay): سووتەمەنی کێم دبیت، بەلێ مەترسیا Backdraft و هەرفتنێ دمینیت.","ل کارگەهان، کۆگەهێن بلند، پالێت، و شلەمەنی دشێن ئاگری ب لەزتر ژ مالان بگەهیننە قۆناغا تەمام.","تانکێن غاز و شلەمەنیێن ب فشار ئەگەر ب ئاگری گەرم ببن دشێن ب BLEVE بتەقن — دەوروبەرێ ب لەز ڤالا بکە.","پلانا کارگەهێ دڤێت ڕێکا گەهشتنا تیمێن ١١٥ و جهێن ئاڤا ئاگرکوژیێ (Hydrants) ئامادە و ڤەکری بهێلیت.","چاڤدێرێ ئاگری پشتی کارێ گەرم (Hot Work): ل دەمێ کاری و کێمترین ١ دەمژمێر پشتی ب دوماهیک هاتنێ، پاشان چاڤدێری هەتا ٣ دەمژمێرێن دی ل دویڤ بڕیارا بەرپرسێ مۆلەتێ (NFPA 51B)."]},{heading:"٧. بارێ ئاگری (Fire Load) و هەلسەنگاندنا مەترسیێ",body:"پشکنینا مەترسیێ ل کارگەهێ:",points:["بارێ ئاگری (Fire Load Density — MJ/m²): بڕا وزەیا کو ماددەیێن سووتەنێ د هەر مەترەکێ چارگۆشە دا دشێن بدەن. تێکڕایێن EN 1991-1-2 (Eurocode 1):","• خانی (Dwelling): نێزیکی ٧٨٠ MJ/m².","• نڤیسینگەهـ (Office): نێزیکی ٤٢٠ MJ/m².","• کتێبخانە (Library): نێزیکی ١٥٠٠ MJ/m².","• کۆگەهـ و کارگەهـ: ل دویڤ ماددەیێن هەلگرتی دهێتە حسێبکرن و گەلەک جاران ژ ڤان بلندترە.","هەلسەنگاندنا مەترسیێ (Risk Assessment): مەترسی = ئەگەرا ڕوودانێ (Likelihood) × گرانیا ئەنجامی (Severity).","• کێم (Low): ب ڕێکارێن ئاسایی دهێتە کۆنترۆلکرن.","• ناڤنجی (Medium): پێدڤی ب کۆنترۆلێن زێدە و چاڤدێریێ.","• بلند (High): پێدڤی ب کارێ لەز بەری بەردەوامبوونا کاری.","• گەلەک بلند (Extreme): کار ڕادوەستیت هەتا مەترسی کێم دبیت.","بەرگریا دیوار و بانان دژی ئاگری (Fire Resistance Rating) ل دویڤ جۆر و بکارئینانا ئاڤاهی ژ کۆدێن ئاڤاهیسازیێ دهێتە دیارکرن (وەک NFPA 101 و NFPA 5000).","هەلسەنگاندنا مەترسیێن کارگەهێ (وەک HVA) ب کێمی سالێ جارەکێ و پشتی هەر گوهۆڕینەکا مەزن نوو بکە."]}],media:[{kind:"video",src:"media/videos/fact_dust_explosion.mp4",title:"تەقینا تۆزێ",description:"نمایشا تەقینا تۆزێ"},{kind:"image",src:"media/images/fact_fire_classes.png",title:"خشتەیا پۆلێن ئاگری",description:"پۆلینکرنا ئاگری ل کارگەهان"}],quiz:[{question:"بۆ ئاگرێ پۆلا D، کیش تەمرینک گونجایە؟",options:[{text:"نێزیکترین تەمرینکا تۆزا هشک یا ABC",correct:!1},{text:"ئاڤ",correct:!1},{text:"تەمرینکا پۆلا D یا کو ناڤێ وی کانزای ل سەر لایبلا وێ هاتی",correct:!0},{text:"تەمرینکا CO₂ کو بەرەڤ بنێ ئاگری دهێتە ئاراستەکرن",correct:!1}],explanation:"تەنێ تەمرینکا پۆلا D یان ماددەیەک یێ کو ناڤێ وی کانزایێ دسۆژیت ل سەر لایبلا وی هاتی گونجایە؛ ماددە ژ کانزایەکێ بۆ یێ دی جودایە. ئاڤ، CO₂، و تۆزا ABC بکار نەئینە."},{question:"BLEVE چ واتە یە؟",options:[{text:"ئامێرێن تەنگاڤیێ بۆ دەرئێخستنا هەلما شلەمەنیا دسۆژیت (Burning Liquid Emergency Venting Equipment)",correct:!1},{text:"تەقینا هەلما شلەمەنیا کەلی (Boiling Liquid Expanding Vapor Explosion)",correct:!0},{text:"سیستەمێ سپرینکلەری",correct:!1},{text:"پۆلا غازێ",correct:!1}],explanation:"BLEVE تەقینا تانکەکا ب فشار یا شلەمەنیێ یە دەمێ ب ئاگری گەرم دبیت و هەلم ب لەز بەلاڤ دبیت."},{question:"پێنجگۆشەیا تۆزێ (Dust Pentagon) چەند توخمان هەیە؟",options:[{text:"٣",correct:!1},{text:"٤",correct:!1},{text:"٥",correct:!0},{text:"٦",correct:!1}],explanation:"پێنج توخم: سووتەمەنی + ئۆکسجین + گەرمی + بەلاڤبوون + جهێ داخستی."},{question:"ئەسیتیلین دگەل مسی (Copper) چ پەیدا دکەت؟",options:[{text:"چ ناقەومیت — مس بۆ ئەسیتیلینێ سەلامەتە",correct:!1},{text:"Copper Acetylide — ماددەیەکێ تەقەمەنی",correct:!0},{text:"پاقژکرن",correct:!1},{text:"چینەکا کەسک یا پاراستنێ ل سەر بۆرییا مسی",correct:!1}],explanation:"ئەسیتیلین دگەل مسی ماددەیەکێ تەقەمەنی یێ هەستیار (Copper Acetylide) چێدکەت کو ب لێدان یان گەرمیێ دتەقیت."},{question:"تۆزا ئەلەمنیۆمێ (Aluminum Powder) کیش مەترسی هەیە؟",options:[{text:"پۆلا A، وەکی دار و کاغەزی",correct:!1},{text:"پۆلا D و تەقینا تۆزێ",correct:!0},{text:"تەنێ غاز",correct:!1},{text:"چ مەترسی نینە",correct:!1}],explanation:"تۆزا ئەلەمنیۆمێ هەم کانزایێ سووتەنێ یە (پۆلا D) و هەم تۆزا سووتەنێ یە (NFPA 484 / 654، ئێستا NFPA 660)."},{question:"ل دویڤ EN 1991-1-2، تێکڕایا بارێ ئاگری ل خانیان (Dwelling) نێزیکی چەندە؟",options:[{text:"١٠٠ MJ/m²",correct:!1},{text:"٢٣٠ MJ/m²",correct:!1},{text:"٤٢٠ MJ/m²",correct:!1},{text:"٧٨٠ MJ/m²",correct:!0}],explanation:"تێکڕایا بارێ ئاگری ل خانیان نێزیکی ٧٨٠ MJ/m² یە، و ل نڤیسینگەهان نێزیکی ٤٢٠ MJ/m² (EN 1991-1-2، خشتەیا E.4)."}]},{id:21,code:"FACT-121",icon:"ShowerHead",accent:"#2563eb",title:"سیستەمێن ڤەمراندنا ئاگری ل کارگەهان",subtitle:"Portable Extinguishers + Fixed Systems (Sprinkler/Foam/CO₂)",summary:"تەمرینکێن دەستی و سیستەمێن جێگیر یێن ڤەمراندنا ئاگری ل کارگەهان",blocks:[{body:"کارگەهـ پێدڤی ب دوو ئاستێن ڤەمراندنا ئاگری نە: ١) تەمرینکێن دەستی (Portable Extinguishers) بۆ ئاگرێن بچووک د قۆناغا دەستپێکێ دا، ٢) سیستەمێن جێگیر (Fixed Suppression Systems) بۆ پاراستنا بەردەوام. ل دویڤ جۆرێ مەترسیێ: سپرینکلەر (NFPA 13)، کەف (NFPA 11 / 16)، CO₂ (NFPA 12)، تۆزا هشک (NFPA 17)، و Clean Agent (NFPA 2001). ئەڤ مۆدیولە ئەڤان سیستەمان و خشتەیا پشکنینێ ڕوون دکەت."},{heading:"١. تەمرینکێن دەستی — هەلبژارتن ل کارگەهێ",body:"٧ جۆرێن سەرەکی و خشتەیا هەلبژارتنێ:",points:["تۆزا ABC (Multi-purpose): بەلاڤترین جۆر بۆ کۆریدۆر و جهێن گشتی — A، B، C (نە D و K).","CO₂: بۆ تابلۆیێن کارەبێ و ژوورێن سێرڤەران — B، C.","کەف (AFFF / Foam): بۆ کۆگەهێن شلەمەنیان و جهێن دیوارێن ڕاگرتنێ — A، B.","Wet Chemical (کیمیایی یا شل): بۆ مەتبەخ و کافتریا کارگەهێ — K.","Clean Agent: بۆ ژوورێن سێرڤەر و کۆنترۆلێ.","پۆلا D (ماددەیەک یێ کو ناڤێ وی کانزایێ ل وێرێ بکار دهێت ل سەر لایبلا وی هاتی): بۆ تراشکرنا کانزایان و هەلاندنا ئەلەمنیۆمێ.","Water Mist (ئاڤا هوور یا بێ کانزا): بۆ A، و هندەک مۆدێل بۆ C — ل دویڤ لیستکرنا ئامێری.","ئاستێن مەترسیێ ل دویڤ NFPA 10 (کێمترین هەلسەنگاندنا تەمرینکا پۆلا A):","• مەترسیا کێم (Light Hazard — نڤیسینگەهـ): 2-A.","• مەترسیا ئاسایی (Ordinary Hazard — کارگەها ئاسایی): 2-A.","• مەترسیا زێدە (Extra Hazard — کارگەها ب سووتەمەنیا گەلەک): 4-A.","دووراتیا گەهشتنێ (Travel Distance) هەتا تەمرینکێ:","• پۆلا A: هەتا ٢٣ مەتر (٧٥ پێ) ل هەمی ئاستان.","• پۆلا B: ٩ یان ١٥ مەتر (٣٠ / ٥٠ پێ) ل دویڤ هەلسەنگاندنا تەمرینکێ و ئاستێ مەترسیێ."]},{heading:"٢. سیستەمێن سپرینکلەری — NFPA 13",body:"گرنگترین سیستەمێ جێگیر ل گەلەک کارگەهان:",points:["٤ جۆرێن سیستەمێن سپرینکلەری:","• بۆریێن تەڕ (Wet Pipe): بۆری هەمیشە پڕ ئاڤن — بەرسڤا لەزترین و بەلاڤترین جۆر.","• بۆریێن هشک (Dry Pipe): بۆری پڕ هەوا یان نایترۆجینێ ب فشارن — بۆ جهێن کو گەرمی لێ دچیتە خوار ٤°C.","• پێش-کارکرن (Pre-action): ڤالڤ تەنێ پشتی ناسینا ئاگری ب دەتێکتەران ڤەدبیت، پاشان سەرێ سپرینکلەری ب گەرمیێ ڤەدبیت — بۆ جهێن ئامێرێن هەستیار.","• Deluge: سەرێن ڤەکری، و هەمی پێکڤە ئاڤێ دڕژینن — بۆ جهێن مەترسیا بلند.","پلەیا گەرمیا ڤەبوونێ (Activation Temperature) و ڕەنگێ گلۆپا شووشەیی:","• ٥٧°C (پرتەقالی): پلەیا ئاسایی (Ordinary) — جهێن گەرمیا وان نزم.","• ٦٨°C (سۆر): پلەیا ئاسایی (Ordinary) — بەلاڤترین ل نڤیسینگەهـ و کارگەهان.","• ٧٩°C (زەرد) و ٩٣°C (کەسک): پلەیا ناڤنجی (Intermediate) — جهێن گەرمتر.","• ١٤١°C (شین): پلەیا بلند (High) — ژوورێن بۆیلەران و نێزیکی ئامێرێن گەرم.","ڕووبەرێ پاراستنێ بۆ هەر سەرەکێ ئاسایی (Standard Spray): هەتا نێزیکی ٢١ m² (Light)، ١٢ m² (Ordinary)، و ٩ m² (Extra Hazard).","چڕیا ئاڤێ (Density): 0.10-0.40 gpm/ft² (نێزیکی ٤-١٦ mm/min) ل دویڤ ئاستێ مەترسیێ.","NFPA 25: پشکنین و تاقیکرن ب خشتەیێن هەفتیانە، هەیڤانە، سالانە، و ٥ سالان.","سپرینکلەر تەنێ ل جهێ ئاگری ڤەدبن؛ هەمی سەر پێکڤە ڤەنابن (ژ بلی سیستەمێ Deluge)."]},{heading:"٣. سیستەمێن کەفێ — NFPA 11 / 16",body:"بۆ کۆگەهێن مەزن یێن شلەمەنیان:",points:["٣ جۆرێن کەفێ ل دویڤ ڕێژەیا بەرفرەهبوونێ (Expansion):","• کێم (Low-Expansion، هەتا 20:1): ئاگرێن تانکان و ڕژانا شلەمەنیان.","• ناڤنجی (Medium-Expansion، 20:1 هەتا 200:1): جهێن دیوارێن ڕاگرتنێ.","• بلند (High-Expansion، 200:1 هەتا 1000:1): هەنگارێن فڕۆکەیان و جهێن مەزن یێن داخستی.","جۆرێن ماددەیێ کەفێ (Concentrate):","• AFFF: بۆ هایدرۆکاربۆنان (بەنزین، دیزل).","• AR-AFFF (Alcohol-Resistant): بۆ سۆلڤێنتێن پۆلار (ئەلکهول، ئەسیتۆن).","• Fluoroprotein: بۆ تانکێن هەلگرتنێ.","• کەفا بێ فلۆرین (Fluorine-Free Foam — F3): جێگرێ کەفێن PFAS.","ڕێژەیا بکارئینانێ (Application Rate):","• ڕژانا هایدرۆکاربۆنان: کێمترین نێزیکی ٤٫١ L/min/m² (0.10 gpm/ft²).","• سۆلڤێنتێن پۆلار: ل دویڤ لیستکرنا بەرهەمئینەری، ب گشتی بلندتر.","مەترسیا PFAS: AFFF ماددەیێن فلۆرینی (PFAS) تێدا هەنە کو د لەشی و ژینگەهێ دا کۆم دبن؛ گەلەک وەلات بەرەڤ کەفا بێ فلۆرین (F3) دچن.","ل کارگەهان: کۆمەلگەهێن تانکان، جهێن بارکرنا تانکەران، و پالاوگەهان."]},{heading:"٤. سیستەمێن CO₂ و Clean Agent — NFPA 12 / 2001",body:"بۆ ژوورێن ئامێران و تژیکرنا تەمام (Total Flooding):",points:["تژیکرنا تەمام ب CO₂:","• چڕیا دیزاینێ: کێمترین ٣٤٪ (NFPA 12)، و بۆ هندەک ماددەیان پتر.","• مەترسی: چڕیا ڤەمراندنێ بۆ مرۆڤان کوژەرە — چ کەس نابیت د ژووری دا بمینیت.","• زەنگا پێش-بەردانێ و دەمێ ڕاوەستانێ (Time Delay): دڤێت بەس بیت بۆ ڤالاکرنا ژووری بەری بەردانا غازێ (NFPA 12).","• بکارئینان: ژوورێن جەنەڕەیتەران، جهێن تاقیکرنا مەکینەیان، و ئامێرێن چاپێ.","Clean Agent (FK-5-1-12 / HFC-227ea):","• NOAEL: ل جهێن کەس لێ، چڕیا دیزاینێ ژ ئاستێ بێ زیان (NOAEL) نابۆریت (NFPA 2001)؛ دیسا ژی ژووری ڤالا بکە.","• چڕیا دیزاینێ: ب گشتی نێزیکی ٤-٩٪ ل دویڤ جۆرێ ماددەی.","• بەردان (Discharge): ماددەیێن هالۆکاربۆنی د ١٠ چرکەیان دا (NFPA 2001).","• بکارئینان: ژوورێن سێرڤەران، کۆنترۆلێ، و سویچان.","• بهایێ وێ ژ سیستەمێن ئاڤێ گەلەک بلندترە.","Halon 1301: بەرهەمئینانا وێ ل دویڤ پرۆتۆکۆلا مۆنترێال ژ ١٩٩٤ ڤە ل وەلاتێن پێشکەفتی هاتیە ڕاگرتن، چونکو چینا ئۆزۆنێ تێکددەت؛ سیستەمێن نوو پێ ناهێنە دانان.","تاقیکرنا هیدرۆستاتیکی یا تەمرینکێن دەستی (NFPA 10): CO₂ هەر ٥ سالان، Clean Agent هەر ١٢ سالان؛ سیلەندەرێن سیستەمێن جێگیر ل دویڤ NFPA 12 / 2001 و یاسایێن سیلەندەران."]},{heading:"٥. سیستەمێن تۆزا هشک — NFPA 17",body:"بۆ مەترسیێن تایبەت:",points:["سیستەمێن ئامادەکری (Pre-Engineered Systems):","• مەتبەخێن بازرگانی: ئێستا ب گشتی سیستەمێن Wet Chemical (NFPA 17A) دهێنە بکارئینان، نە تۆزا هشک.","• ژوورێن ڕەنگکرنێ (Spray Booths).","• پاراستنا ئامێر و ترومبێلێن گران.","• تانکێن نوقمکرنێ (Dip Tanks).","ماددە (Agents):","• بیکاربۆناتا سۆدیۆمێ (Sodium Bicarbonate): B، C.","• بیکاربۆناتا پۆتاسیۆمێ (Purple-K): B، C — ل سەر ئاگرێن پۆلا B ژ سۆدیۆمێ ب هێزترە.","• فۆسفاتا ئەمۆنیۆمێ (Monoammonium Phosphate): A، B، C.","• کلۆریدا پۆتاسیۆمێ (Potassium Chloride): B، C.","ڤەبوون (Activation): دەتێکتەرێ گەرمیێ یان دەستگرەکێ دەستی (Manual Pull).","پشتی بەردانێ: تۆز ل هەمی جهان بەلاڤ دبیت و دشێت زیانێ بگەهینیتە ئامێرێن ئەلکترۆنی؛ پاقژکرن گرانە.","ڕووبەرێ پاراستنێ یێ هەر لۆلەکێ (Nozzle) ل دویڤ لیستکرنا سیستەمی دهێتە دیارکرن."]},{heading:"٦. ناسینا ئاگری — NFPA 72",body:"سیستەمێ ناسینێ — هێلا ئێکێ یا ئاگەهدارکرنێ:",points:["جۆرێن دەتێکتەران:","• دوکێل: فۆتۆئەلکتریک (Photoelectric) بۆ ئاگرێن هێدی (Smoldering)، ئایۆنیزەیشن (Ionization) بۆ ئاگرێن ب گڕ (Flaming).","• گەرمی: پلەیا جێگیر (Fixed Temperature، وەک ٥٧°C) یان بلندبوونا لەز (Rate-of-Rise).","• گڕ (Flame): UV/IR — گڕێ ب لەز دناسن.","• غاز: دەتێکتەرێن LEL و سێنسۆرێن CO.","• کێشانا نموونەیێن هەوای (Air-Sampling): بۆ ژوورێن سێرڤەران — هەستیارترین جۆر.","دووراتی و ڕووبەر:","• دوکێل: دووراتیا ناڤبەرا دەتێکتەران نێزیکی ٩ مەتر (30 ft) ل سەر بانێ ڕێک (NFPA 72).","• گەرمی: ل دویڤ دووراتیا لیستکری یا دەتێکتەری (Listed Spacing).","• گڕ: ل دویڤ گۆشەیا دیتنێ و دووراتیا لیستکری یا ئامێری.","ئاگەهدارکرن (Alarm Notification):","• دەنگ (Audible): ب گشتی کێمترین ١٥ dB ژ تێکڕایا دەنگێ جهی بلندتر (NFPA 72).","• ڕۆناهی (Strobe): بۆ جهێن ب دەنگەدەنگ و بۆ کەسێن کێماسیا بهیستنێ هەی.","• ئاگەهدارکرنا دەنگی (Voice / Mass Notification): بۆ ئاڤاهی و کارگەهێن مەزن.","پشکنین و تاقیکرن: ل دویڤ خشتەیێن NFPA 72 (گەلەک ئامێر سالێ جارەکێ دهێنە تاقیکرن)."]},{heading:"٧. خشتەیا پشکنین و ساخکرنێ",body:"ل دویڤ ستانداردێن NFPA:",points:["ڕۆژانە / هەفتیانە:","• پشکنینا چاڤی (فشارا گەیجان، زیان).","• پشکنینا هندێ کو چ تشت نەکەفتبنە بەر سپرینکلەران.","• هەلکرنا ئاگرپەمپێ بێی ڤەکرنا ئاڤێ (No-flow Test): پەمپا دیزلی هەر هەفتی، یا کارەبێ ب گشتی هەر هەیڤ (NFPA 25).","هەیڤانە:","• پشکنینا چاڤی یا تەمرینکێن دەستی (NFPA 10).","• پشکنینا پانێلا زەنگا ئاگری و نیشانێن خەلەتیێ (Trouble).","• پشکنینا دوگمێن زەنگێ (Manual Pull Stations) — دیار و نەگرتی.","سالانە:","• ساخکرنا سالانە یا تەمرینکێن دەستی ژ لایێ کەسێ شارەزا ڤە (نە تاقیکرنا هیدرۆستاتیکی).","• پشکنینا سپرینکلەران ژ سەر عەردی (NFPA 25).","• نموونەیا ماددەیێ کەفێ بۆ تاقیکرنێ.","• تاقیکرنا دەتێکتەر و زەنگان (NFPA 72).","هەر چەند سالان جارەکێ:","• تاقیکرنا هیدرۆستاتیکی یا تەمرینکان (تاقیکرنا فشارێ یا لەشێ وان، NFPA 10): هەر ٥ سالان بۆ ئاڤ، کەف، Wet Chemical، CO₂ و تۆزا هشک یا ستێنلێس ستیل (stainless steel)؛ هەر ١٢ سالان بۆ تۆزا هشک یا فشارا هەلگرتی (stored-pressure) یا لەشێ وێ ژ ئاسنێ نەرم (mild steel)، مسێ زەرد یێ لحیمکری (brazed brass) یان ئەلەمنیۆمێ، و بۆ Clean Agent. ب جودا، هەر ٦ سالان، تەمرینکێن تۆزا هشک یێن فشارا هەلگرتی یێن کو پێدڤی ب تاقیکرنا ١٢ سالان هەی، ژ لایێ کەسێ شارەزا ڤە ڤالا دکەن و ناڤا وان دپشکنن. ڕێسایێن دهۆکێ هێشتا نەهاتینە پشتڕاستکرن.","• پشکنینا ناڤخوەیی یا بۆریێن سپرینکلەری: هەر ٥ سالان (NFPA 25).","• گوهۆڕین یان تاقیکرنا نموونەیێن سەرێن سپرینکلەری پشتی ٥٠ سالان (سەرێن ئاسایی — NFPA 25).","تۆمارکرن: هەمی پشکنین و تاقیکرنان بنڤیسە و تۆماران ل دویڤ ستانداردان و داخوازا دەزگەهێن پەیوەندیدار بپارێزە."]}],media:[{kind:"video",src:"media/videos/fact_sprinkler_demo.mp4",title:"ڤەبوونا سپرینکلەری",description:"نمایشا سپرینکلەری"},{kind:"image",src:"media/images/fact_systems_chart.png",title:"خشتەیا سیستەمێن ڤەمراندنێ",description:"سیستەمێن جێگیر"}],quiz:[{question:"بۆ پترییا کارگەهان، گرنگترین سیستەمێ جێگیر کیژە؟",options:[{text:"تەمرینکێن دەستی",correct:!1},{text:"سپرینکلەر (NFPA 13)",correct:!0},{text:"تەنێ CO₂",correct:!1},{text:"چ ژ ڤان",correct:!1,fixed:!0}],explanation:"سپرینکلەر ب خوە کار دکەن و ئاگری د قۆناغا دەستپێکێ دا کۆنترۆل دکەن، حەتا دەمێ کەس ل جهی نەبیت؛ تەمرینکێن دەستی تەنێ بۆ ئاگرێن بچووکن."},{question:"سیستەمێ بۆریێن تەڕ (Wet Pipe) بۆ کیش جهی نەگونجایە؟",options:[{text:"ژوورێن ئامێران (ICT)",correct:!1},{text:"نڤیسینگەهێن ب پلەیا گەرمیا ئاسایی",correct:!1},{text:"جهێن کو گەرمی لێ دچیتە خوار ٤°C",correct:!0},{text:"کۆگەهێن گەرمکری یێن کو هەمی سالێ ژ ١٠°C بلندتر دمینن",correct:!1}],explanation:"ل جهێن سار ئاڤ د بۆریان دا دقەریسیت؛ سیستەمێ بۆریێن هشک (Dry Pipe) گونجایە."},{question:"ئەرێ سیستەمێن نوو ب Halon 1301 دهێنە دانان؟",options:[{text:"بەلێ",correct:!1},{text:"نەخێر — بەرهەمئینانا وێ ل دویڤ پرۆتۆکۆلا مۆنترێال هاتیە ڕاگرتن",correct:!0},{text:"بەلێ — هێشتا ماددێ ستاندارد یە بۆ ژوورێن ICT یێن نوو",correct:!1},{text:"بەلێ، بەس تەنێ ل ژوورێن سێرڤەران یێن نوو کو ماددێن پاقژ تێدا نەهێنە بکارئینان",correct:!1}],explanation:"Halon 1301 چینا ئۆزۆنێ تێکددەت؛ بەرهەمئینانا وێ ل وەلاتێن پێشکەفتی ژ ١٩٩٤ ڤە هاتیە ڕاگرتن."},{question:"بۆچی دڤێت هەمی کەس بەری بەردانا سیستەمێ CO₂ یێ تژیکرنا تەمام ژ ژووری دەرکەڤن؟",options:[{text:"پێدڤی ناکەت، CO₂ ب هەر چڕیەکێ د ژوورێ دا بێ زیانە",correct:!1},{text:"چونکو چڕیا ڤەمراندنێ (٣٤٪ و پتر) بۆ مرۆڤان کوژەرە",correct:!0},{text:"چونکو CO₂ ئاڤێ دڕژینیت",correct:!1},{text:"چونکو دەنگێ بەردانا CO₂ هندە بلندە کو دشێت بۆ هەمیشە زیانێ بگەهینیتە گوهێن مرۆڤان",correct:!1}],explanation:"چڕیا دیزاینا CO₂ ل سیستەمێن تژیکرنا تەمام کێمترین ٣٤٪ ە (NFPA 12)، و ئەڤ چڕییە د دەمەکێ کورت دا مرۆڤی بێهۆش دکەت و دکوژیت؛ ژبەرهندێ زەنگا پێش-بەردانێ و دەمێ ڕاوەستانێ هەنە."},{question:"ڕووبەرێ پاراستنێ یێ هەر سەرەکێ سپرینکلەری (Standard Spray) نێزیکی چەندە؟",options:[{text:"٢-٥ m²",correct:!1},{text:"١٢-٢١ m²",correct:!0},{text:"٣٠-٤٠ m²",correct:!1},{text:"٨٠-١٠٠ m²",correct:!1}],explanation:"ل دویڤ NFPA 13: نێزیکی ٢١ m² بۆ مەترسیا کێم و ١٢ m² بۆ مەترسیا ئاسایی؛ بۆ مەترسیا زێدە کێمترە (نێزیکی ٩ m²)."},{question:"تاقیکرنا هەفتیانە یا ئاگرپەمپا دیزلی چ کارە؟",options:[{text:"تەنێ پشکنینا چاڤی، بێی هەلکرنا پەمپێ",correct:!1},{text:"هەلکرنا پەمپێ بێی ڤەکرنا ئاڤێ (Start / No-flow Test)",correct:!0},{text:"تاقیکرنا هیدرۆستاتیکی",correct:!1},{text:"هەلکرنا پەمپێ دگەل ڕەوینا ئاڤێ یا تەمام بۆ ماوێ ڕۆژەکا تەمام",correct:!1}],explanation:"NFPA 25: پەمپا دیزلی هەر هەفتی و پەمپا کارەبێ ب گشتی هەر هەیڤ بێی ڤەکرنا ئاڤێ دهێتە هەلکرن و تاقیکرن."}]},{id:22,code:"BUS-122",icon:"Building2",accent:"#0f766e",title:"سەلامەتی ژ ئاگری ل دوکان، بازاڕ و مۆلان",subtitle:"دەرکەفتن، کۆگەهـ، کارەبا، غازا LPG و ڕۆلا کارمەندان د تەنگاڤیێ دا",summary:"دوکان، بازاڕ و مۆل پڕن ژ کڕیارێن ئاڤاهیێ نانیاسن، ژ کالایێن ب ساناهی دسووژن، ژ ئامێرێن کارەبێ و گەلەک جاران ژ سلندەرێن غازا LPG. ئەڤ وانە بۆ خودان، بەرپرس و کارمەندانە: چەوا دەرکەفتن و ئامێرێن ئاگری ڤەکری و بێ ئاستەنگ بهێلن، چەوا ڕێ ل ئاگرێن کارەبێ و غازێ بگرن، و هەر کارمەندەک دەمێ زەنگا ئاگری لێددەت چ دکەت. ڕێسایێن مۆلەتێ و پشکنینێ یێن ناڤخۆیی ژ لایێ بەرگرییا شارستانی و لایەنا مۆلەتدانێ ڤە دهێنە دانان؛ داخوازییێن وان پەیڕەو بکەن.",blocks:[{heading:"١. دەرکەفتن، ڕێکێن دەرکەفتنێ و کۆگەهـ",body:"کڕیار ب گشتی هەول ددەن ژ وێ ڕێکێ دەرکەڤن یا تێڕا هاتین، لەوا دڤێت هەمی ڕێکێن دەرکەفتنێ هەمی دەمان ئامادە بن:",points:["دەرکەفتن، کۆریدۆر و پلەکانان ب تەمامی ڤالا بهێلە: چ کالا، کارتۆن، عەرەبانە یان مێزێن فرۆشتنێ ل سەر ڕێکێ نەبن، هەتا بۆ دەمەکێ کورت ژی.","دڤێت دەرگەهێن دەرکەفتنێ هەر دەمێ خەلک ل ژوور بن ژ ناڤڤە ئێکسەر ڤەببن، بێ کلیل و بێ کۆد؛ بەری ڤەکرنا دوکانێ زنجیر، شیش و قفلێن زێدە ڕاکە.","نیشانێن دەرکەفتنێ دیار بهێلە: نابیت کالا، پۆستەر و خەملاندن دەرگەهێ دەرکەفتنێ یان نیشانا وی ڤەشێرن.","کالایێن زێدە د کۆگەهێ دا بهێلە، نە د کۆریدۆران دا، نە ل بن پلەکانان و نە ل وان جهێن کڕیار لێ دچن و دهێن.","کالا، کارتۆن یان کەرەستەیێن پێچانێ ل تەنشت تابلۆیێن کارەبێ، گلۆپان، سۆبەیان یان ئامێرێن چێشتلێنانێ کۆم نەکە.","ل بازاڕی یان مۆلێ، دگەل ڕێڤەبەریێ ل سەر دەرکەفتنێن هەڤپشک، زەنگا ئاگری و خالا کۆمبوونێ ڕێک بکەڤە، و بەشداریێ د ڕاهێنانێن هەڤپشک دا بکە."]},{heading:"٢. کارەبا: بارێ زێدە و وایەرێن درێژکەر",body:"زێدە بارکرنا پلاکان و گەرمبوونا وایەران ژ ئەگەرێن بەربەلاڤێن ئاگری ل دوکانانن:",points:["بارێ زێدە نەکە سەر پلاکان و پلاکێن زێدە (Power strip)، و وان پلاکێن زێدە بکار بینە یێن پاراستنا ژ بارێ زێدە تێدا.","وایەرێ درێژکەر (Extension lead) تەنێ بۆ کارێ دەمکییە و چ جاران جهێ وایەرێن جێگیر یێن ئاڤاهی ناگریت؛ ئەگەر پێدڤی ب پلاکێن پتر هەبیت، بهێلە کارەباچیەکێ شارەزا وان دانیت.","سەلاجە، فریزەر، سۆبە، فڕن و ئامێرێن مەزنێن دی ڕاستەوخۆ ب پلاکا دیواری ڤە گرێ بدە، چ جاران ب وایەرێ درێژکەر ڤە نە.","وایەران ل بن مافوور و بەڕان، د ناڤ دەرگەهان ڕا یان ل سەر ڕێڕەوان نەکێشە، کو دبیت بهێنە پەلچقاندن یان خەلک پێ بکەڤن.","وایەر و فیشێن خرابووی ئێکسەر بگوهۆڕە. بێهنا سووتنێ، فیشەکا گەرم، پریسک یان سویچێ پاراستنێ (Breaker) کو دووبارە دکەڤیت، واتە: کارەبێ ببڕە و کارەباچیەکێ شارەزا بینە."]},{heading:"٣. سلندەرێن غازا LPG ل دوکان و بازاڕان",body:"غازا LPG ژ هەوایێ گرانترە: غازا دەردکەڤیت ل نێزیکی عەردی و ل جهێن نزم وەک ئاڤەڕۆ و قاتێن ژێرێ کۆم دبیت.",points:["ل دوکانێ تەنێ کێمترین ژمارا سلندەران بهێلە یا کارێ تە پێدڤی پێ هەی؛ یێن مای ل کۆگەهەکا جودا و هەوادار بهێلە، باشترە ل دەرڤە ل هەوایا ڤەکری.","چ جاران سلندەران ل ژێر ئاستێ عەردی، ل قاتێ ژێرێ یان ل نێزیک ئاڤەڕۆیان نەهێلە.","سلندەران ب ستوونی و سەرێ شیری پاراستی بهێلە، ل جهەکێ کڕیار نەگەهنێ، دوور ژ گەرمی، ئاگر و تشتێن دسووژن.","چ جاران سلندەران ل سەر پلەکانان، ل تەنشت دەرگەهێن دەرکەفتنێ یان ل هەر جهەکێ ڕێکا دەرکەفتنێ بگریت دانەنە.","تەنێ تەکنیکارەکێ شارەزا ڕێگولاتەر، لوولە و ئامێران گرێ ددەت. چ جاران ب ئاگری ل دەرکەفتنا غازێ نەگەڕە.","ژمارا سلندەرێن دوکانەک دشێت بهێلیت و جهێ وان، ژ لایێ بەرگرییا شارستانی و لایەنا مۆلەتدانێ ڤە دهێتە دیارکرن."]},{heading:"٤. ئەگەر بێهنا غازێ هات",body:`١. چ ئاگران هەلنەکە و چ گلۆپ، ئامێر یان مەکینەیان ڤەنەکە و نەکوژینە. ل ناڤ جهی تەلەفۆنێ بکار نەئینە.
٢. فرۆشتنێ ڕاوەستینە و ب هێمنی کڕیار و کارمەندان ژ نێزیکترین دەرکەفتنێ دەربێخە.
٣. شیرێ غازێ تەنێ بگرە ئەگەر نێزیکی تە بیت و تو بشێی بگەهییێ بێ کو بچییە وی جهێ غاز لێ کۆم بوویە و بێ چ پریسکان؛ ئەگەر نە، نەچە نێزیکی وی.
٤. خەلکی ژ دەرگەهی دوور بێخە و دوکانێن جیران ئاگەهدار بکە.
٥. ژ دەرڤە پەیوەندیێ ب ١١٥ بکە، و نەهێلە کەس بزڤڕیتە ژوور هەتا پسپۆر نەبێژن جه سەلامەتە.`,critical:!0},{heading:"٥. ڕۆلا کارمەندان دەمێ زەنگا ئاگری لێددەت",body:"هەر کارمەندەک بەری تەنگاڤیێ ڕۆلا خوە دزانیت. پلانا تەنگاڤیێ بۆ هەر ئەرکەکی د هەر دەوامەکێ دا کەسەکی دیار دکەت:",points:["ئاگەهدارکرن: ب دەنگێ بلند بێژە «ئاگر!»، ئەگەر دوگمەیا زەنگا ئاگری (Call point) هەبیت نێزیکترین لێ بدە، و پشتڕاست ببە کو کەسەک ژ جهەکێ سەلامەت پەیوەندیێ ب ١١٥ دکەت.","ڕێنیشاندانا کڕیاران: فرۆشتنێ ڕاوەستینە، ب هێمنی بێژە کڕیاران دەرکەڤن و نێزیکترین دەرکەفتنێ نیشا وان بدە، نە تەنێ دەرگەهێ سەرەکی.","پشکنین: تووالێت، ژوورێن تاقیکرنا جلکان، کۆگەهـ و نڤیسینگەهان د ڕێکا دەرکەفتنێ دا بپشکنە، تەنێ ئەگەر سەلامەت بیت، و دەرگەهان ل پشت خوە بگرە.","هاریکاری: هاریکاریا وان بکە یێن پێدڤی پێ هەی، وەک پیر، زارۆکێن ب تنێ و کەسێن خودان پێدڤیێن تایبەت. چ جاران ئەسانسۆرێ بکار نەئینە.","ل خالا کۆمبوونێ: کارمەندان بژمێرە، هەر کەسەکێ بەرزە ڕاگەهینە، و بێژە ئاگرکوژان کا دبیت خەلک ل کیڤە مابن و ل سەر سلندەرێن غازێ و مەترسیێن دی.","کەس نازڤڕیتە ژوور هەتا بەرگرییا شارستانی نەبێژیت جه سەلامەتە."]},{heading:"٦. دەرئێخستنا قەرەبالغیێ ب سەلامەتی",body:"ل دوکان یان مۆلەکێ قەرەبالغ، ڕێنیشاندانا کارمەندان دیار دکەت کا هەمی کەس چەند ب لەز دەردکەڤن:",points:["ب هێمنی باخڤە و ڕێنماییێن کورت و ڕوون بدە، وەک: «ژ ڤێ دەرکەفتنێ دەرکەڤن. ب ڕێڤە بچن، نەڕەڤن.»","هەمی دەرکەفتنێن هەین بکار بینە، و ئەگەر دەرکەفتنەک قەرەبالغ بوو یان دوکێلێ گرت، خەلکی بەرەڤ دەرکەفتنەکا دی ڕێ بکە.","نەهێلە خەلک بۆ پارەدانێ، کۆمکرنا کالایان یان زڤڕینا ژوور ڕاوەستن.","ژمارا خەلکێ ل ژوور د ناڤ سنوورێ دیارکری یێ ئاڤاهی دا بهێلە، ب تایبەتی د جەژن و ڕۆژێن داشکاندنێ دا.","ل مۆلێ، ڕێنماییێن تیمێ تەنگاڤیێ یێ مۆلی و ڕاگەهاندنان پەیڕەو بکە، و ب دوورییەکا باش ژ ئاڤاهی بچە خالا کۆمبوونێ."]},{heading:"٧. ئامێرێن ئاگری، کیتا هەوارهاتنا ئێکێ و AED",body:"ئامێر تەنێ ژیانێ ڕزگار دکەن ئەگەر خەلک وان ببینن، بگەهنێ و بشێن بکار بینن:",points:["تەمرینک، دوگمەیێن زەنگا ئاگری و بەتانیێن ئاگری دیار، ل جهێ خوە و بێ ئاستەنگ بهێلە؛ هەر ڕۆژ بپشکنە کو چ تشت ل پێشیا وان نینە.","تەمرینکێ تەنێ بکار بینە ئەگەر تە ڕاهێنان کربیت، ئاگر بچووک و د دەستپێکێ دا بیت، لایبل نیشان بدەت کو بۆ ڤی ئاگری گونجایە، خەلک ئاگەهدار بووبن، پەیوەندی ب ١١٥ هاتبیتە کرن و ڕێکا دەرکەفتنا تە ل پشت تە بیت. ئەگەر نە، دەرکەڤە و دەرگەهی بگرە.","هەر تەمرینکەک هەر هەیڤ پێدڤی ب پشکنینەکا چاڤی هەیە (ل جهێ خوە، مێخا سەلامەتیێ و مۆر ساخلەم، پیڤەرا فشارێ ل ناڤچەیا کەسک، بێ زیان) و ب خزمەتکرنێ ژ لایێ کەسەکێ شارەزا ڤە؛ خشتەیا ناڤخۆیی ژ لایێ بەرگرییا شارستانی ڤە دهێتە دانان.","کیتەکا هەوارهاتنا ئێکێ یا تەمام ل جهەکێ بهێلە کارمەند ب لەز بگەهنێ، و بزانە کێ د هەر دەوامەکێ دا ڕاهێنانا هەوارهاتنا ئێکێ کرییە.","ئەگەر دوکان یان مۆل ئامێرێ شۆکا دلی (AED) هەبیت، هەمی کارمەند دزانن ل کیڤەیە. ئەگەر کەسەک کەفت و ب ئاسایی هەناسە نەدا: پەیوەندیێ ب ١٢٢ بکە، فشارا سنگی (CPR) دەست پێ بکە و ئێکسەر کەسەکی بهنێرە دا AED بینیت."]}],media:[{kind:"image",src:"media/images/w8_shop_evacuation.webp",title:"دەرئێخستنا کڕیاران ژ دوکانێ",description:"کارمەندەک کڕیاران بەرەڤ نێزیکترین دەرکەفتنێ دبەت و هەڤکارەکێ وی کۆگەهێ دپشکنیت"}],quiz:[{question:"کۆگەهـ پڕە و کالایەکا نوو گەهشت. کارتۆنێن زێدە دشێن ل کیڤە بهێنە دانان؟",options:[{text:"د کۆریدۆرا دەرکەفتنا ئاگری دا، هەتا دوماهیا ڕۆژێ",correct:!1},{text:"ل بن پلەکانان، هەتا کو کڕیار وان نەبینن و پێ نەکەڤن",correct:!1},{text:"ل کۆگەهەکا دی یان جهەکێ دوور ژ دەرکەفتن و ڕێڕەوان",correct:!0},{text:"ل پێشیا تەمرینکێ، کو جهەکێ ڤالا ل سەر عەردی هەی",correct:!1}],explanation:"دڤێت دەرکەفتن، کۆریدۆر و پلەکان هەمی دەمان ڤالا بن، هەتا بۆ دەمەکێ کورت ژی، و نابیت چ تشت ئامێرێن ئاگری بگریت. کالایێن زێدە دچنە کۆگەهەکا دوور ژ دەرکەفتن و ڕێڕەوان."},{question:"سەلاجەیەکا نوو یا نیشاندانێ پێدڤی ب کارەبێ هەیە. ڕێکا سەلامەت یا گرێدانا وێ کیژە؟",options:[{text:"ب وێ پلاکا زێدە ڤە گرێ بدە یا گلۆپ و سندوقا پارەی ژ بەری نوکە پێ ڤە گرێدای",correct:!1},{text:"ڕاستەوخۆ ب پلاکا دیواری ڤە؛ ئەگەر پێدڤی بوو کارەباچی پلاکان زێدە دکەت",correct:!0},{text:"وایەرێ درێژکەر ل بن مافووری بکێشە دا کەس پێ نەکەڤیت",correct:!1},{text:"دوو وایەرێن درێژکەر پێکڤە گرێ بدە دا بگەهنە پلاکا نک دەرگەهی",correct:!1}],explanation:"ئامێرێن مەزن ڕاستەوخۆ ب پلاکا دیواری ڤە دهێنە گرێدان. وایەرێ درێژکەر دەمکییە و ب ساناهی بارێ زێدە دگریت، و وایەرێ ل بن مافووری دبیت بهێتە پەلچقاندن و گەرم ببیت."},{question:"کارمەند بێهنەکا گران یا غازێ ل نێزیک سلندەرێن دوکانێ دکەن، و شیر ل ناڤەڕاستا بێهنێ دایە. چ دروستە؟",options:[{text:"بچە نک شیری، بگرە و پانکەیێ ڤەکە دا غاز ژ دوکانێ دەرکەڤیت",correct:!1},{text:"گلۆپان ڤەکە دا دەرکەفتنێ ببینی و لوولەیێ ب چەقماخێ تاقی بکە",correct:!1},{text:"ژ ناڤ دوکانێ پەیوەندیێ ب کۆمپانیا غازێ بکە دەمێ تو ل دەرکەفتنێ دگەڕێی",correct:!1},{text:"ژ شیری دوور بکەڤە، هەمی کەسان دەربێخە و ژ دەرڤە پەیوەندیێ ب ١١٥ بکە",correct:!0}],explanation:"شیر تەنێ دهێتە گرتن ئەگەر بێ چوونا ناڤ غازێ و بێ چ پریسکان بگەهییێ. ل ڤێرێ نەشێی، لەوا کەس ناچیتە نێزیکی وی: بێ سویچ، بێ تەلەفۆن ل ژوور، هەمی کەس دەردکەڤن و ژ دەرڤە پەیوەندی ب ١١٥ دهێتە کرن."},{question:"زەنگا ئاگری ل دوکانەکا قەرەبالغ لێددەت. ئەو کارمەندێ بەرپرسێ تووالێت و کۆگەهان چ دکەت؟",options:[{text:"ئەگەر سەلامەت بیت د ڕێکێ دا وان دپشکنیت و ل خالا کۆمبوونێ ڕادگەهینیت",correct:!0},{text:"ل نک سندوقا پارەی دمینیت دا هەمی فرۆشتنێ ب دوماهیک بینیت بەری دەرکەڤیت",correct:!1},{text:"کۆگەهان قفل دکەت دا کەس د دەمێ ئاگری دا چ کالایان ژێ نەبەت",correct:!1},{text:"پشتی ژمارتنێ ب تنێ دزڤڕیتە ناڤ ئاڤاهی دا ل کەسێن بەرزە بگەڕیت",correct:!1}],explanation:"پشکنینا تووالێت و کۆگەهان د ڕێکا دەرکەفتنێ دا، تەنێ ئەگەر سەلامەت بیت، پشتڕاست دکەت کو کەس ل پشت نەمایە. ئەنجام ل خالا کۆمبوونێ دهێتە ڕاگەهاندن؛ کەس نازڤڕیتە ژوور."},{question:"د دەمێ دەرئێخستنێ دا، کڕیار ل دەرگەهێ سەرەکی قەرەبالغ دبن و دەرکەفتنەکا دی ڤالایە. کارمەند چ دکەن؟",options:[{text:"دبێژنە هەمی کەسان ل ناڤ دوکانێ چاڤەڕێ بکەن هەتا دەرگەهێ سەرەکی ڤالا دبیت",correct:!1},{text:"ب هێمنی و ب ڕێنماییێن کورت و ڕوون خەلکی بەرەڤ دەرکەفتنا ڤالا ڕێ دکەن",correct:!0},{text:"ئەسانسۆران ڤەدکەن دا خەلکەکێ پتر پێکڤە ژ نهۆمێ دەرکەڤن",correct:!1},{text:"داخوازێ ژ کڕیاران دکەن ب لەز پارێ بدەن دا ڕیز زووتر بلڤیت",correct:!1}],explanation:"خەلک ب گشتی ژ وێ ڕێکێ دەردکەڤن یا تێڕا هاتین. کارمەند هەمی دەرکەفتنێن هەین بکار دئینن و ب هێمنی خەلکی بەرەڤ دەرکەفتنەکا ڤالا دبەن؛ ئەسانسۆر چ جاران د ئاگری دا بکار ناهێن."}]},{id:23,code:"BUS-123",icon:"CookingPot",accent:"#c2410c",title:"سەلامەتی ژ ئاگری ل ڕێستۆران و مەتبەخێن بازرگانی",subtitle:"ئاگرێ ڕۆن و چەوریێ، سیستەمێ دوکێلکێشێ، غاز و ڕاهێنانا کارمەندان",summary:"مەتبەخێ بازرگانی گەرمی، ڕۆن، چەوری و غازێ ل جهەکێ تەنگ پێکڤە کۆم دکەت، و ئاگرەک د تاوەیەکێ یان فرایەرەکێ دا دشێت د چەند چرکەیان دا بگەهیتە دوکێلکێشێ (Hood) و بۆرییا وی. ئەڤ وانە بۆ خودان، بەرپرس، ئاشپەز و کارمەندێن خزمەتێیە: چەوا دگەل ئاگرێ ڕۆنی مامەلێ بکەن، سیستەمێ ڤەمراندنا ئاگری یێ دوکێلکێشێ چ دکەت، چەوا غازێ ب سەلامەتی بکار بینن، بۆچی دڤێت چەوری بهێتە پاقژکرن و چەوا کڕیاران دەربێخن. داخوازییێن بەرگرییا شارستانی و لایەنا مۆلەتدانێ پەیڕەو بکەن.",blocks:[{heading:"١. ئاگرێ ڕۆن و چەوریێ: چ جاران ئاڤ نە",body:"ڕۆن و دوهنێ دسووژیت پێدڤی ب مامەلەکا تایبەت هەیە:",points:["چ جاران ئاڤێ نەکە سەر ڕۆن یان دوهنێ دسووژیت: ئاڤ ئێکسەر دبیتە هەلم و ڕۆنێ سووتی وەک گوپکەکا ئاگری دپژقینیت.","تاوە یان فرایەرا دسووژیت هەلنەگرە و نەلڤینە.","ئاگرەکێ بچووک د تاوەیەکێ دا: تەنێ ئەگەر ب سەلامەتی بگەهییێ، گەرمیێ یان غازێ ل سەر ئامێری ببڕە، پاشان قاپاخەکێ کانزایی ب سەر تاوەیێ دا بکێشە یان بەتانیا ئاگری بدە سەر، و لانەبە هەتا سار دبیت.","تەمرینکا تۆزا ABC یان یا کەفێ بۆ فرایەرێ (Deep fryer) نە گونجایە: ڕۆن گەرم دمینیت و دشێت دیسان هەلبیت.","ئەگەر ئاگر نە بچووک بیت، گەهشتە دوکێلکێشێ یان ئێکسەر ڤەنەمری: دەرکەڤە، دەرگەهی بگرە و پەیوەندیێ ب ١١٥ بکە."],critical:!0},{heading:"٢. تەمرینکا کیمیایی یا شل (پۆلا K / پۆلا F)",body:"پۆلێن ئاگری ل ڤێرێ ب پیتێن NFPA 10 هاتینە نڤیسین وەک ژێدەرێ پرۆژەی؛ سیستەمێ فەرمی یێ دهۆکێ هێشتا نەهاتییە پشتڕاستکرن. بەرامبەرێن EN 2: NFPA A = EN A؛ NFPA B (شلەمەنی) = EN B؛ NFPA B (غاز) = EN C؛ NFPA C (ئامێرێن کارەبێ یێن کارەبا تێدا) چو پۆل د EN دا نینە؛ NFPA D = EN D؛ NFPA K = EN F. ژبەر هندێ پۆلا K (NFPA) و پۆلا F (EN 2) ئێک پۆلن: ڕۆن و دوهنێن چێشتلێنانێ.",points:["تەمرینکا کیمیایی یا شل (Wet Chemical) بۆ ڕۆن و دوهنێن چێشتلێنانێ هاتییە چێکرن: چینەکا وەکی سابوونێ ل سەر ڕۆنی چێدکەت کو هەوایێ دبڕیت و ڕۆنی سار دکەت.","ئەگەر مەتبەخ سیستەمێ ڤەمراندنا دوکێلکێشێ هەبیت، ئێکەم جار سیستەمی کار پێ بکە (ب خوە یان ب دەسکێ کارپێکرنا دەستی)، و پشتی هنگێ تەمرینکێ بکار بینە. نیشانەکا ل نک تەمرینکێ ڤێ چەندێ دبێژیت.","بەری تەنگاڤیێ لایبلێ بخوینە: پۆل، مەودایێ کارکرنێ و چەوا بکار دهێت. هندەک تەمرینکێن کیمیایی یێن شل ب ڕێکەکا جودا ژ PASS کار پێ دهێتە کرن؛ لایبل و ڕێنماییێن کۆمپانیا چێکەر پەیڕەو بکە.","تەنێ بکار بینە ئەگەر تە ڕاهێنان کربیت، ئاگر بچووک بیت، زەنگا ئاگری هاتبیتە لێدان و ڕێکا دەرکەفتنا تە ل پشت تە بیت.","ڕەنگێ تەمرینکێ پۆلا وێ نینە: هەمی جاران لایبلێ بخوینە."]},{heading:"٣. سیستەمێ ڤەمراندنا ئاگری یێ دوکێلکێشێ",body:"گەلەک مەتبەخێن بازرگانی سیستەمەکێ جێگیر یێ ڤەمراندنا ئاگری د دوکێلکێشێ دا ل سەر فرایەر، ئامێرێن برژاندنێ و تەباخان هەیە. کارمەند خزمەتا وی ناکەن، بەلێ دڤێت هەمی کەس بزانن چەوا کار دکەت:",points:["دەمێ ئاگرەک ل بن دوکێلکێشێ سیستەمی گەرم دکەت، ب خوە کار دکەت و ماددەیەکا ڤەمراندنێ ژ سەرێن پژاندنێ (Nozzles) دپژینیتە سەر ڕووێن چێشتلێنانێ و د ناڤ دوکێلکێش و بۆرییا وی دا.","دەمێ کار دکەت، غاز یان کارەبا ئامێرێن چێشتلێنانێ یێن ل بن دوکێلکێشێ ژی دبڕیت. پشتی هنگێ تەنێ کەسەکێ شارەزا وان ڤەدگەڕینیت.","ئەگەر ب خوە کار نەکر، دەسکێ کارپێکرنا دەستی (Pull station) بکار بینە. ئەو ل سەر ڕێکا دەرکەفتنێ ژ مەتبەخێ یە، دڤێت هەر ئاشپەزەک بزانیت ل کیڤەیە، و نابیت چ تشت ڕێکا وی بگریت.","فلتەرێن دوکێلکێشێ پاقژ و ل جهێ خوە بهێلە. سەرێن پژاندنێ پاقژ بهێلە، و چ جاران چ تشتەکی ل سەر وان دانەنە و وان نەچەمینە و نەلڤینە.","ئامێرێن چێشتلێنانێ یێن ل بن دوکێلکێشێ نەلڤینە، زێدە نەکە و نەگوهۆڕە بێ کو دانەرێ سیستەمی بپشکنیت: سەرێن پژاندنێ بەرەڤ ئامێرێن دیارکری هاتینە ئاراستەکرن.","کۆمپانیەکا شارەزا ب ڕێکوپێکی سیستەمی دپشکنیت و خزمەت دکەت و کارتا خزمەتکرنێ پێڤە دکەت؛ ماوە ژ لایێ بەرگرییا شارستانی و لایەنا مۆلەتدانێ ڤە دهێتە دانان."]},{heading:"٤. سلندەر، مانیفۆلد و بۆرییێن غازێ",body:"غاز ل مەتبەخێ تەنێ دەمێ ب دروستی هاتبیتە دانان و بکار ئینان سەلامەتە:",points:["سلندەرێن غازێ و مانیفۆلدا وان (Manifold، ئەو بۆرییا چەند سلندەران پێکڤە گرێ ددەت) ل دەرڤەی مەتبەخێ بهێلە، ل جهەکێ هەوادار، ب ستوونی و پاراستی ژ گەرمیێ و ژ دەستێوەردانێ؛ چ جاران ل قاتێ ژێرێ یان ل ژێر ئاستێ عەردی نە.","تەنێ تەکنیکارەکێ شارەزا یێ غازێ بۆری، ڕێگولاتەر و ئامێران دادنیت، گرێ ددەت، چێدکەت و خزمەت دکەت. کارمەند تەنێ ئەگەر ڕاهێنان کربیت سلندەران دگوهۆڕن.","ڕاهێنانێ ب کارمەندان بکە دا هەر ڕۆژ ل کێماسیێن ئاشکەرا بگەڕێن، وەک لوولە یان گرێدانەکا خرابووی، گڕەکا ڤەدمریت و هەلبوویی نامینیت یان بێهنا غازێ، و وان ڕاگەهینن و ئامێری بکار نەئینن.","ئەگەر غاز ب پانکەیا کێشانێ ڤە هاتبیتە گرێدان (Interlock)، دەمێ پانکە ڕادوەستیت غاز ژی دهێتە بڕین. چ جاران ڤێ گرێدانێ تێنەپەڕینە و ژ کار نەئێخە.","هەر ئاشپەزەک دزانیت شیرێ غازێ یێ مەتبەخێ ل کیڤەیە، و تەنێ وەسا بکار دئینیت کا ڕێسایا بێهنا غازێ ل خوارێ ڕێ ددەت.","چ جاران ب ئاگری ل دەرکەفتنا غازێ نەگەڕە."]},{heading:"٥. ئەگەر بێهنا غازێ ل مەتبەخێ هات",body:`١. چ ئاگران هەلنەکە و چ گلۆپ، پانکە یان ئامێران ڤەنەکە و نەکوژینە. ل ناڤ جهی تەلەفۆنێ بکار نەئینە.
٢. شیرێ غازێ تەنێ بگرە ئەگەر نێزیکی تە بیت و تو بشێی بگەهییێ بێ کو بچییە وی جهێ غاز لێ کۆم بوویە و بێ چ پریسکان؛ ئەگەر نە، نەچە نێزیکی وی.
٣. ب هێمنی کارمەند و کڕیاران دەربێخە و جیرانان ئاگەهدار بکە.
٤. ژ دەرڤە پەیوەندیێ ب ١١٥ بکە، و نەزڤڕە ژوور هەتا پسپۆر نەبێژن جه سەلامەتە.`,critical:!0},{heading:"٦. چەوری: پاقژکرنا دوکێلکێش، فلتەر و بۆرییێ",body:"ئەو چەوریا د دوکێلکێش، فلتەر و بۆرییا کێشانێ دا کۆم دبیت، سووتەمەنییە و چاڤەڕێی گڕەکێ یە:",points:["گڕێن قەلاندن، برژاندن یان فلامبێ (Flambé) دشێن چەوریا کۆمبووی هەلکەن، و ئاگرەک د بۆرییێ دا دشێت د ناڤ ئاڤاهی دا بەلاڤ ببیت.","فلتەر، ڕووێن دوکێلکێشێ، دیوار، عەرد و ئامێران ل دویڤ خشتەیەکا دیارکری پاقژ بکە، دا چەوری کۆم نەبیت.","بهێلە کۆمپانیەکا شارەزا بۆرییا کێشانێ ب ڕێکوپێکی پاقژ بکەت و تۆمارێ بپارێزە. چەند جاران ل دویڤ جۆر و بڕێ چێشتلێنانێ یە؛ داخواز ژ لایێ بەرگرییا شارستانی و لایەنا مۆلەتدانێ ڤە دهێتە دانان.","فرایەرێ تەنێ پشتی ڕۆن سار بوو ڤالا و پاقژ بکە، و چ جاران فرایەرێ دەمێ ڕۆن گەرم بیت نەلڤینە.","کارتۆن، پەڕۆ، کاغەز و دەفرێن ڕۆنی دوور ژ ئامێرێن چێشتلێنانێ و گەرمیێ بهێلە."]},{heading:"٧. ڕاهێنانا کارمەندان و دەرئێخستنا کڕیاران",body:"هەمی کەس ل ڕێستۆرانێ ژ ڕۆژا ئێکێ یا کاری پلانێ دزانن:",points:["پلانا تەنگاڤیێ دیار دکەت کێ زەنگا ئاگری لێددەت، کێ پەیوەندیێ ب ١١٥ دکەت، کێ غازێ دبڕیت ئەگەر سەلامەت بیت، کێ کڕیاران ڕێنیشان ددەت و کێ ل خالا کۆمبوونێ کارمەندان دژمێریت.","کارمەندێن خزمەتێ ب هێمنی دبێژنە کڕیاران کو ژ نێزیکترین دەرکەفتنێ دەرکەڤن، و ناهێلن بۆ پارەدانێ یان کۆمکرنا تشتێن خوە ڕاوەستن.","تووالێت، هۆلێن خوارنێ و کۆگەهان د ڕێکا دەرکەفتنێ دا بپشکنە، تەنێ ئەگەر سەلامەت بیت، و دەرگەهان ل پشت خوە بگرە.","دەرگەهێ پشتێ و دەرکەفتنا مەتبەخێ ڤالا بهێلە، و چ جاران دەرگەهێن دەرکەفتنێ قفل نەکە دەمێ کارمەند یان کڕیار ل ژوور بن.","ل ڕۆژا ئێکێ، دەرکەفتن، دەسکێ کارپێکرنا دەستی، تەمرینک، بەتانیا ئاگری و شیرێ غازێ نیشا هەر کارمەندەکێ نوو بدە، و ب ڕێکا ڕاهێنانان پلانێ تاقی بکەن.","ل خالا کۆمبوونێ، بێژە ئاگرکوژان کا سیستەمێ دوکێلکێشێ کار کرییە یان نە، غاز هاتییە بڕین یان نە، و کەس بەرزە یە یان نە."]}],media:[{kind:"image",src:"media/images/w8_kitchen_grease_fire.webp",title:"ئاگرێ ڕۆنی ل مەتبەخەکێ بازرگانی",description:"ئاشپەزەک قاپاخەکێ کانزایی ب سەر تاوەیەکا دسووژیت دا دکێشیت؛ دەسکێ کارپێکرنا دەستی و تەمرینکا کیمیایی یا شل ل نێزیک دەرکەفتنێ دیارن"}],quiz:[{question:"ئاگرەکێ بچووک د تاوەیەکا ل سەر تەباخێ دا هەلبوو. کارێ دروست چییە؟",options:[{text:"پەرداخەکا ئاڤێ بکە سەر تاوەیێ دا ڕۆن ب لەز سار ببیت و ڤەمریت",correct:!1},{text:"تاوەیێ هەلگرە و ببە دەرڤە دا ئاگر ژ مەتبەخێ دەرکەڤیت",correct:!1},{text:"گەرمیێ ببڕە ئەگەر سەلامەت بیت و قاپاخەکێ کانزایی بدە سەر",correct:!0},{text:"تەمرینکا تۆزا ABC یا نڤیسینگەهێ بینە و بپژینە سەر تاوەیێ",correct:!1}],explanation:"دانانا قاپاخی ل سەر تاوەیێ هەوایێ دبڕیت، و بڕینا گەرمیێ ڕێ ل گەرمبوونا پتر یا ڕۆنی دگریت. ئاڤ ڕۆنێ دسووژیت وەک گوپکەکا ئاگری دپژقینیت، لڤاندنا تاوەیێ ئاگری بەلاڤ دکەت، و تۆزا ABC بۆ ڕۆنێ چێشتلێنانێ نەهاتییە چێکرن."},{question:"ئاگرەک ل بن دوکێلکێشێ ڤەنامریت. مەتبەخ سیستەمێ دوکێلکێشێ و تەمرینکا کیمیایی یا شل هەیە. چ ئێکەم جار دهێت؟",options:[{text:"سیستەمێ دوکێلکێشێ ب دەسکێ دەستی کار پێ بکە، پاشان تەمرینکێ",correct:!0},{text:"ئێکەم جار تەمرینکێ بکار بینە و سیستەمی بۆ ئاگرەکێ مەزنتر بهێلە",correct:!1},{text:"پانکەیا کێشانێ ڕاوەستینە و فلتەران دەربێخە دا دوکێل دەرکەڤیت",correct:!1},{text:"چاڤەڕێ بکە هەتا سیستەم ب خوە کار دکەت بەری چ تشتەکی بکەی",correct:!1}],explanation:"سیستەمێ دوکێلکێشێ غاز یان کارەبێ دبڕیت و ڕووێن چێشتلێنانێ، دوکێلکێش و بۆرییێ ب ماددەیا ڤەمراندنێ دگریت. تەمرینکا کیمیایی یا شل بۆ بکارئینانێ پشتی کارپێکرنا سیستەمی هاتییە چێکرن، وەکی نیشانا ل نک وێ دبێژیت."},{question:"بۆچی نابیت ئامێرێن چێشتلێنانێ یێن ل بن دوکێلکێشێ بێ دانەرێ سیستەمی بهێنە لڤاندن یان گوهۆڕین؟",options:[{text:"ئامێرێن گرانتر دشێن کاشییێن عەردی ل بن دوکێلکێشێ بشکێنن و خراب بکەن",correct:!1},{text:"سەرێن پژاندنێ بەرەڤ ئامێرێن دیارکری نە و دبیت ئامێرەکێ نوو نەگرن",correct:!0},{text:"لڤاندنا وان دەنگێ مەتبەخێ بۆ ئاشپەز و کڕیاران گەلەک زێدە دکەت",correct:!1},{text:"ئامێرێن نوو هەمی جاران سیستەمەکێ ئاگری یێ تایبەت ب خوە هەیە",correct:!1}],explanation:"سیستەم وان ئامێران دپارێزیت یێن بۆ وان هاتییە دیزاینکرن. ئەگەر ئامێرەک هاتە لڤاندن یان گوهۆڕین، دڤێت دانەر بپشکنیت کا سەرێن پژاندنێ هێشتا وی دگرن یان نە."},{question:"سلندەرێن غازا LPG و مانیفۆلدا ڕێستۆرانەکێ دڤێت ل کیڤە بن؟",options:[{text:"ل قاتێ ژێرێ، کو سار دمینن و ژ ڕێکا کارمەندان دوورن",correct:!1},{text:"ل ناڤ مەتبەخێ ل بن تەباخێ، نێزیکی وان ئاگران یێن غازێ ددەنێ",correct:!1},{text:"ل کۆگەها هۆلا خوارنێ، ل پشت کورسیێن ل سەر ئێک دانایی",correct:!1},{text:"ل دەرڤە ل جهەکێ هەوادار، ب ستوونی و پاراستی ژ گەرمیێ",correct:!0}],explanation:"غازا LPG ژ هەوایێ گرانترە و ل جهێن نزم وەک قاتێ ژێرێ کۆم دبیت. سلندەر ل دەرڤە ل جهەکێ هەوادار، ب ستوونی و دوور ژ گەرمیێ دهێنە دانان، و تەکنیکارەکێ شارەزا گرێدانان دکەت."},{question:"بۆچی پاقژکرنا چەوریێ ژ دوکێلکێش، فلتەر و بۆرییێ کارەکێ سەلامەتیا ژ ئاگری یە؟",options:[{text:"چەوریا کۆمبووی دشێت ژ گڕێن چێشتلێنانێ هەلبیت و د بۆرییێ دا بەلاڤ ببیت",correct:!0},{text:"چەوری تەنێ بێهنا خوارنێ دگوهۆڕیت و مەترسیا ئاگری زێدە ناکەت",correct:!1},{text:"بۆرییێن پاقژ وەسا دکەن کو سیستەمێ دوکێلکێشێ گەلەک جاران ب خەلەتی کار بکەت",correct:!1},{text:"چینەکا چەوریێ کانزایێ بۆرییێ ژ گەرمیا مەزنا چێشتلێنانێ دپارێزیت",correct:!1}],explanation:"گڕێن قەلاندن، برژاندن یان فلامبێ دشێن چەوریا د دوکێلکێش و بۆرییێ دا هەلکەن، و ئاگرەک د بۆرییێ دا دشێت د ناڤ ئاڤاهی دا بەلاڤ ببیت. پاقژکرنا ب ڕێکوپێک ڤێ سووتەمەنیێ ڕادکەت."}]},{id:24,code:"BUS-124",icon:"Building",accent:"#6d28d9",title:"سەلامەتی ژ ئاگری ل ئوتێل و جهێن مانا میڤانان",subtitle:"زەنگێن شەڤێ، ئاگەهداریێن میڤانان، ڕۆلا کارمەندان و ئەو میڤانێن پێدڤی ب هاریکاریێ",summary:"ل ئوتێلێ، میڤان د ئاڤاهیەکێ دا دنڤن کو نانیاسن، و هندەک ژ وان نەشێن بێ هاریکاری دەرکەڤن. لەوا ئاگرێ شەڤێ مەزنترین مەترسییە. ئەڤ وانە بۆ خودان، بەرپرس، کارمەندێن پێشوازیێ و کارمەندێن شەڤێ یە: دڤێت چ بێژنە میڤانان، ڕێسایا دەرگەهێ ژوورێ، هەر کارمەندەک ب شەڤ چ دکەت، چەوا هاریکاریا میڤانێن خودان پێدڤیێن تایبەت بکەن، و چەوا زەنگێن دوکێلێ و دەرگەهێن بەرگرێ ئاگری هەمی کەسان دپارێزن. داخوازییێن بەرگرییا شارستانی و لایەنا مۆلەتدانێ پەیڕەو بکەن.",blocks:[{heading:"١. بۆچی شەڤ مەزنترین مەترسییە",body:"پلانا ئاگری یا ئوتێلێ دڤێت د خرابترین دەم دا ژی کار بکەت:",points:["میڤانێن نڤستی هێدی هشیار دبن و دبیت تێک بچن، و ئاڤاهی و دەرکەفتنێن وی نانیاسن.","پشتی زەنگ لێددەت، دبیت تەنێ چەند خولەکەک بۆ دەرکەفتنا ب سەلامەتی هەبن.","دوکێل د کۆریدۆران دا بەلاڤ دبیت و ب پلەکانان دا بلند دبیت؛ دەرگەهێن گرتی بەلاڤبوونا دوکێل، گەرمی و ئاگری هێدی دکەن.","ب شەڤ کێمترین کارمەند ل سەر کارن، لەوا دڤێت پلان تەنێ دگەل تیمێ شەڤێ کار بکەت، و دڤێت کارمەندێن تێرا هەبن بۆ هاریکاریا وان میڤانێن نەشێن ب خوە دەرکەڤن."]},{heading:"٢. زەنگ، ئامێرێن هەستکرنا دوکێلێ و دەرگەهێن بەرگرێ ئاگری",body:"ئەڤە میڤانان دەمێ دنڤن دپارێزن، بەس ئەگەر کار بکەن:",points:["د هەر ژوورەکا میڤانان دا ئامێرێ هەستکرنا دوکێلێ و زەنگەک هەیە کو دەنگێ وێ تێرا هشیارکرنا میڤانەکێ نڤستی بلندە.","ئەگەر هەبیت، ژوورەکێ ب زەنگا ڕووناهیا دپەڕیت یان پارچەیا لەرزۆک (Vibrating pad) پێشکێشی وان میڤانان بکە یێن کەڕ یان بهیستنا وان کێم.","دەرگەهێن بەرگرێ ئاگری (Fire door) ل کۆریدۆر و پلەکانان ب خوە دگرن. چ جاران وان ب پشتگیرەکێ یان ب گرێدانێ ڤەکری نەهێلە، و دەرگەهەکێ ب تەمامی ناگریت ئێکسەر ڕاگەهینە.","سیستەمێ سپرینکلەری د هەر ژوورەکا میڤانان دا، ل وێرێ یێ هاتییە دانان، پاراستنەکا زێدە ددەت.","هەر ڕۆژ بپشکنە کو ڕێکێن دەرکەفتنێ ڤالانە، دەرگەهێن دەرکەفتنێ ڤەدبن و ڕۆناهیا تەنگاڤیێ کار دکەت؛ ماوەیێن تاقیکرن و خزمەتکرنێ ژ لایێ بەرگرییا شارستانی ڤە دهێنە دانان."]},{heading:"٣. هەر میڤانەک دڤێت چ بزانیت",body:"ل دەمێ تۆمارکرنا هاتنێ، ئاگەهدارییێن ئاگری بدە هەر میڤانەکی:",points:["پلانا دەرکەفتنێ ل سەر لایێ ناڤخۆیی یێ دەرگەهێ ژوورێ نیشان ددەت کا ژوور ل کیڤەیە و ڕێکێن بەرەڤ نێزیکترین دەرکەفتنان.","بێژە میڤانان دەنگێ زەنگا ئاگری چەوایە و دوو نێزیکترین دەرکەفتن ل کیڤەنە، و پێشنیار بکە کو دەرگەهێن د ناڤبەرا ژوورا خوە و دەرکەفتنێ دا بژمێرن؛ ئەڤە د تاریێ یان د دوکێلێ دا هاریکار دبیت.","کلیلا ژوورێ ل نک نڤینێ بهێلە و دەمێ دەردکەڤی دگەل خوە ببە.","دەمێ زەنگ لێددەت: ئێکسەر دەرکەڤە، دەرگەهان ل پشت خوە بگرە و پلەکانان بکار بینە، چ جاران ئەسانسۆرێ نە.","دەرگەهێن دەرکەفتنێ ل سەر ڕێکێن دەرکەفتنێ هەمی دەمان ژ ناڤڤە بێ کلیل ڤەدبن."]},{heading:"٤. ڕێسایا دەرگەهێ ژوورێ",body:"ڤێ ڕێسایێ فێری کارمەندان بکە و ل سەر ئاگەهداریا ئاگری د هەر ژوورەکێ دا بنڤیسە:",points:["بەری ڤەکرنا دەرگەهێ ژوورێ، ب پشتا دەستێ خوە دەرگەهی و دەسکێ وی بپشکنە. ئەگەر گەرم بوو، یان دوکێل ژ دۆرا وی دهات، گرتی بهێلە.","ئەگەر دەرگەهـ سار بوو، هێدی ڤەکە و ئامادە بە کو ئێکسەر بگری ئەگەر ل دەرڤە دوکێل یان ئاگر هەبیت.","ئەگەر کۆریدۆر ڤالا بوو، دەرکەڤە، دەرگەهی ل پشت خوە بگرە و بچە نێزیکترین دەرکەفتنێ؛ ئەگەر دوکێل هەبیت، خوە نزم بکە.","ئەگەر هەمی ڕێک گرتی بن: ل ژوورێ بمینە و دەرگەهی گرتی بهێلە، کەلێنێن دۆرا دەرگەهی و کونێن هەوایێ ب خاولی یان جهێن نڤستنێ بگرە، پانکە و کۆندیشنێ ڤەمرینە، پەیوەندیێ ب ١١٥ بکە و ژمارا ژوورێ بێژە، و ل بەر پەنجەرێ نیشانان بدە.","ژ نهۆمێن بلند خوە نەهاڤێژە خوارێ؛ چاڤەڕێی ئاگرکوژان بە."]},{heading:"٥. ڕۆلا کارمەندان ب شەڤ",body:"پلانا شەڤێ دیار دکەت کێ چ دکەت، هەتا ئەگەر تەنێ ئێک یان دوو کارمەند ل سەر کار بن:",points:["پێشوازی زەنگێ پشتڕاست دکەت، ئێکسەر پەیوەندیێ ب ١١٥ دکەت و ناڤونیشان، جهێ ئاگری و ژمارا میڤانێن ل ئوتێلێ دبێژیت.","پێشوازی لیستا ژوورێن میڤان تێدا و لیستا وان میڤانێن پێدڤی ب هاریکاریێ دبەتە خالا کۆمبوونێ.","کارمەند د ڕێکا دەرکەفتنێ دا میڤانان ئاگەهدار دکەن و بەرەڤ دەرکەفتنان دبەن، و ژوور، تووالێت و کۆریدۆران تەنێ ل وێرێ دپشکنن یا سەلامەت بیت؛ چ جاران ناچنە ناڤ دوکێلێ و دەرگەهەکێ گەرم ڤەناکەن.","ل خالا کۆمبوونێ، لیستا ژوورێن میڤان تێدا دگەل وان کەسێن ئامادە بەراورد بکە.","دەمێ ئاگرکوژ دگەهن، پێشوازیا وان بکە و بێژە کیژ ژوور دبیت هێشتا میڤان تێدا بن، ئەو میڤانێن پێدڤی ب هاریکاریێ ل کیڤە چاڤەڕێ دکەن و هەر مەترسیەکا تایبەت، وەک غازێ.","کەس نازڤڕیتە ژوور هەتا بەرگرییا شارستانی نەبێژیت جه سەلامەتە."]},{heading:"٦. میڤانێن خودان پێدڤیێن تایبەت",body:"بەری وێ شەڤا پێدڤی پێ هەی، پلانێ بۆ وان دانە:",points:["ل دەمێ تۆمارکرنا هاتنێ، ب ڕێزگرتن و دوور ژ خەلکێ دی پسیارێ ژ میڤانان بکە کا د تەنگاڤیێ دا پێدڤی ب هاریکاریێ دبن بۆ دەرکەفتنێ، و لیستەکا ناڤ و ژمارێن ژوورێن وان ل پێشوازیێ بهێلە.","ئەگەر بشێی، ژوورەکێ ل نهۆمەکا نزم و نێزیکی دەرکەفتنەکێ بدە ڤان میڤانان.","چ جاران د ئاگری دا ئەسانسۆرا ئاسایی بکار نەئینە. ئەو میڤانێ نەشێت پلەکانان بکار بینیت، د ناڤ دەرگەهێن بەرگرێ ئاگری ڕا ل سەر هەمان نهۆم ژ ئاگری دوور دهێتە برن، یان دگەل کارمەندەکی ل جهێ پەنادانێ یێ ل تەنشت پلەکانێن پاراستی چاڤەڕێ دکەت، وەکی پلانا ئوتێلێ دبێژیت.","چ جاران میڤانەکی ب تنێ ل جهێ پەنادانێ نەهێلە، و ئێکسەر و ب دروستی بێژە ئاگرکوژان کا ل کیڤە چاڤەڕێ دکەت.","نابیت پلان پشت ب ئاگرکوژان ببەستیت بۆ ڕزگارکرنا وان میڤانێن چاڤەڕێ دکەن: دڤێت کارمەندێن ڕاهێنای یێن تێرا هەبن بۆ هاریکاریا وان."]},{heading:"٧. فێرکرن و ڕاهێنان",body:"ب شەڤ کارمەند تەنێ وێ دشێن بکەن یا ڕاهێنان پێ کری:",points:["بەری ئێکەم دەوامێ شەڤێ، هەر کارمەندەکێ نوو فێر بکە: زەنگ، دەرکەفتن، دەرگەهێن بەرگرێ ئاگری، لیستێن ژووران و ڕۆلا وی ب خوە.","ڕاهێنانان ئەنجام بدە، ژ وان ژی د وان دەمان دا یێن کێمترین کارمەند ل سەر کار، و وەسا ڕاهێنانێ بکەن کو دەرکەفتنەک یان پلەکانەک گرتی بیت.","پلانا تەنگاڤیێ و لیستێن ژووران ل پێشوازیێ ل بەر دەست بهێلە، و لیستان د هەر تۆمارکرنەکا هاتن و چوونێ دا نوو بکە.","چەند جاران ڕاهێنان دهێنە کرن و چ فێرکرن پێدڤییە، ژ لایێ بەرگرییا شارستانی و لایەنا مۆلەتدانێ ڤە دهێنە دانان."]}],media:[{kind:"image",src:"media/images/w8_hotel_night_evacuation.webp",title:"دەرئێخستنا میڤانان ب شەڤ ل ئوتێلێ",description:"کارمەندەکێ شەڤێ ب چرایەکا دەستی میڤانان د کۆریدۆرێ ڕا بەرەڤ پلەکانێن دەرکەفتنێ دبەت، و دەرگەهەکێ بەرگرێ ئاگری ل پشت وان گرتییە"}],quiz:[{question:"پلانا دەرکەفتنێ یا ل سەر لایێ ناڤخۆیی یێ دەرگەهێ ژوورا میڤانی دڤێت چ نیشان بدەت؟",options:[{text:"ژوور ل کیڤەیە و ڕێکێن بەرەڤ دوو نێزیکترین دەرکەفتنان",correct:!0},{text:"تەنێ ژمارا تەلەفۆنا ئوتێلێ و دەمێ چوونێ ژ ئوتێلێ",correct:!1},{text:"ڕێکا بەرەڤ ئەسانسۆرێ و ڕێکا بەرەڤ دەرگەهێ سەرەکی ب تنێ",correct:!1},{text:"جهێ ڕێستۆرانا ئوتێلێ و جهێ ڕاوەستاندنا ترمبێلان",correct:!1}],explanation:"پلانا ل سەر دەرگەهی جهێ ژوورێ و ڕێکێن بەرەڤ دەرکەفتنان نیشان ددەت، دا میڤان ب لەز و هەتا د تاریێ دا ژی ڕێکا خوە ببینیت. ئەسانسۆر د ئاگری دا بکار ناهێت."},{question:"زەنگ ب شەڤ لێددەت. میڤانەک هەست دکەت کو دەسکێ دەرگەهێ ژوورێ گەرمە. دڤێت چ بکەت؟",options:[{text:"دەرگەهی ب لەز ڤەکەت و د کۆریدۆرێ ڕا بەرەڤ نێزیکترین پلەکانان بڕەڤیت",correct:!1},{text:"دەرگەهی کێمەکێ ڤەکەت دا بەرێ خوە بدەتە کۆریدۆرێ و پاشان بڕیارێ بدەت",correct:!1},{text:"دەرگەهی گرتی بهێلیت، کەلێنان بگریت، پەیوەندیێ ب ١١٥ بکەت و نیشانان بدەت",correct:!0},{text:"ب ئەسانسۆرێ بچیتە خوارێ، چونکی دبیت کۆریدۆر پڕی دوکێل بیت",correct:!1}],explanation:"دەسکێ گەرم واتە ئاگر یان دوکێلا گەرم ل پشت دەرگەهی هەیە. دەرگەهێ گرتی میڤانی دپارێزیت: کەلێن و کونێن هەوایێ بگرە، پەیوەندیێ ب ١١٥ بکە، ژمارا ژوورێ بێژە و ل بەر پەنجەرێ نیشانان بدە."},{question:"د دەمێ دەرئێخستنا شەڤێ دا، کیژ ئەرک یێ پێشوازیێ یە؟",options:[{text:"ل نک مێزێ دمینیت دا بەرسڤا تەلەفۆنێن میڤانان بدەت هەتا ئاگر ڤەدمریت",correct:!1},{text:"پەیوەندیێ ب ١١٥ دکەت و لیستا ژوورێن میڤان تێدا دبەتە خالا کۆمبوونێ",correct:!0},{text:"دچیتە ناڤ هەمی ژووران، ژ وان ژی ژوورێن پڕی دوکێل، دا ل وان بگەڕیت",correct:!1},{text:"بەری دەرکەفتنا ژ ئاڤاهی جانتایێن میڤانان کۆم دکەت",correct:!1}],explanation:"پێشوازی ئێکسەر پەیوەندیێ ب ١١٥ دکەت و لیستێن ژووران دبەت، دا ل خالا کۆمبوونێ ژمارتن بهێتە کرن و ئاگرکوژ بزانن کیژ ژوور دبیت هێشتا میڤان تێدا بن. کەس ناچیتە ناڤ دوکێلێ."},{question:"میڤانەکێ کورسییا چەرخدار بکار دئینیت ل نهۆما سێیێ یە دەمێ زەنگ لێددەت. چ دروستە؟",options:[{text:"کارمەندەک وی ب ئەسانسۆرا ئاسایی دبەتە خوارێ، چونکی ژ پلەکانان زووترە",correct:!1},{text:"کارمەند وی ب تنێ ل جهێ پەنادانێ دهێلن و ل دەرڤە چاڤەڕێی ئاگرکوژان دکەن",correct:!1},{text:"کارمەند دبێژنێ ل ژوورا خوە بمینیت هەتا زەنگ ب خوە ڕادوەستیت",correct:!1},{text:"کارمەندەک وی دبەتە جهێ پەنادانێ، دگەل دمینیت و ئاگرکوژان ئاگەهدار دکەت",correct:!0}],explanation:"ئەسانسۆرا ئاسایی د ئاگری دا بکار ناهێت. میڤان ژ ئاگری دوور دهێتە برن یان دگەل کارمەندەکی ل جهێ پەنادانێ چاڤەڕێ دکەت، چ جاران ب تنێ ناهێتە هێلان، و ئاگرکوژ ئێکسەر دزانن ل کیڤەیە."},{question:"بۆچی نابیت دەرگەهێن بەرگرێ ئاگری ل کۆریدۆرێن ئوتێلێ ب پشتگیرەکێ ڤەکری بهێنە هێلان؟",options:[{text:"دەرگەهێن ڤەکری درەنگێ شەڤێ هەوایا سار ژ پلەکانان دئینن ناڤ کۆریدۆرێن میڤانان",correct:!1},{text:"دەرگەهێ گرتی دوکێل، گەرمی و ئاگری هێدی دکەت و ڕێکا دەرکەفتنێ دپارێزیت",correct:!0},{text:"دەرگەهێن ڤەکری وەسا دکەن کو میڤان دەنگێ زەنگێ گەلەک بلند ل ژوورێن خوە ببهیزن",correct:!1},{text:"دەرگەهێن بەرگرێ ئاگری گرانن و پشتگیر ب دەمێ ڕە ڕەزەیێن وان خراب دکەت",correct:!1}],explanation:"دەرگەهێ بەرگرێ ئاگری تەنێ دەمێ گرتی بیت دپارێزیت: بەلاڤبوونا دوکێل، گەرمی و ئاگری هێدی دکەت و ڕێکا دەرکەفتنێ بۆ میڤانان سەلامەت دهێلیت. دەرگەهێ ب پشتگیرەکێ ڤەکری ئەڤێ پاراستنێ نادەت."}]},{id:25,code:"BUS-125",icon:"Fuel",accent:"#b45309",title:"سەلامەتیا بەنزینخانان",subtitle:"Ignition Control, Static, Spills, Emergency Stop & LPG",summary:"بەنزینخانە بڕەکا مەزن ژ شلەمەنی و غازێن سووتەنێ هەلدگرن و دفرۆشن. ئەڤ مۆدیولە نیشا کارمەند، سەرپەرشتیار و ڕێڤەبەران ددەت کا چاوا ژێدەرێن هەلبوونێ و کارەبا ستاتیکی کۆنترۆل بکەن، دگەل ڕژانا سووتەمەنیێ مامەلێ بکەن، دوگمەیا ڕاوەستاندنا تەنگاڤیێ بکار بینن، غازا LPG ب سەلامەتی تژی بکەن و چ بکەن ئەگەر ئاگر ل نک پەمپێ هەلبوو.",blocks:[{body:"بەنزین هەتا ل هەوایێ سار ژی هەلمێ سووتەنێ ددەت (خالا هەلبوونا وێ نێزیکی -٤٣°C یە)، و هەلما وێ ژ هەوای گرانترە: ل سەر عەردی بەلاڤ دبیت و ل جهێن نزم وەک کەنالێن ئاڤێ، چال و قاتێن ژێرێ کۆم دبیت. چریسکەک، ئاگرەک، جگارەیەک یان مەکینەیەکا کاردکەت دشێت وێ هەلکەت. ڕێسایێن مۆلەتدان، دیزاین و ئامێرێن بەنزینخانان ژ لایێ بەرگرییا شارستانی و دەزگەها مۆلەتدانێ ڤە دهێنە دانان: داخوازێن وان پەیڕەو بکە. ئەڤ مۆدیولە ڕوون دکەت کا هەر کارمەندەک، سەرپەرشتیارەک و ڕێڤەبەرەک دڤێت چ بکەت."},{heading:"١. کۆنترۆلکرنا ژێدەرێن هەلبوونێ ل نک پەمپان",body:"بەری تژیکرنێ و ل دەمێ تژیکرنێ، کارمەند پشتڕاست دبیت کو:",points:["مەکینەیا ترمبێلێ ل نک پەمپێ هاتیە ڤەمراندن.","کەس ل نێزیک پەمپان جگارەیان ناکێشیت و چەقماق یان ئاگرێ ئاشکرا بکار نائینیت، و نیشانێن «جگارە قەدەغەیە» و «مەکینێ ڤەمرینە» ل نێزیک پەمپان هاتینە دانان.","کۆنترۆل بەردەوامە: تو هەر ترمبێلەکێ و هەر کەسەکێ ل نک پەمپان دبینی، و پەمپێ تەنێ هنگێ هەلدکەی دەمێ چ مەترسی نەبیت.","تو تژی ناکەی ئەگەر مەکینە کار دکەت، ئەگەر کەسەک ل نێزیک جگارەیێ دکێشیت یان ئەگەر دەبە نە یا پەسەندکری بیت؛ ئەگەر کڕیار ڕازی نەبوو، گازی سەرپەرشتیاری بکە.","مۆبایل: ڕێسایا بەنزینخانا خوە پەیڕەو بکە (هندەک ڕێنمایی دخوازن کو مۆبایل و ڕادیۆ ل نک پەمپان نەهێنە بکارئینان)، و هشیاریا خوە ل سەر ژێدەرێن سەرەکی یێن هەلبوونێ بهێلە: جگارە، ئاگر، مەکینەیێن کاردکەن و کارەبا ستاتیکی.","گۆڕەپانا پەمپان پاقژ دهێتە هێلان، بێی پەڕۆ، کارتۆن یان ماددەیێن دی یێن سووتەنێ ل نێزیک پەمپان."]},{heading:"٢. کارەبا ستاتیکی و دەبەیێن سووتەمەنیێ",body:"چریسکەکا کارەبا ستاتیکی ل سەرێ لوولەیا پەمپێ (nozzle) دشێت هەلمێ سووتەمەنیێ هەلکەت:",points:["باشترە کڕیار ل دەمێ تژیکرنێ ل دەرڤەیی ترمبێلێ بمینن: خلیسکاندن ل سەر کورسیێ کارەبا ستاتیکی کۆم دکەت. ئەگەر پێدڤی بوو بزڤڕنە د ترمبێلێ دا، بەری جارەکا دی دەست بدەنە سەرێ لوولەیێ، دەستێ خوە ل پارچەیەکا ئاسنی یا ترمبێلێ بدەن، دوور ژ جهێ تژیکرنێ.","دەبەیا سووتەمەنیێ تەنێ تژی بکە دەمێ ل سەر عەردی بیت؛ چ جاران د سندۆقا پشتێ، ل سەر کورسیێ یان د پشتا پیکاپێ دا تژی نەکە.","بەری ڤەکرنا دەبەیێ، سەرێ لوولەیێ ل دەبەیێ بدە، و ل دەمێ تژیکرنێ سەرێ لوولەیێ ب دەڤێ دەبەیێ ڤە بهێلە.","تەنێ دەبەیێن گونجای و پەسەندکری یێن سووتەمەنیێ تژی بکە، چ جاران نە شووشە، سەتل یان قوتیێن خوارنێ؛ کیژ دەبە و کیژ قەبارە دهێنە قەبوولکرن، دەزگەها مۆلەتدانێ دیار دکەت.","دەبەیێ ب باشی بگرە؛ دەبەیێن سووتەمەنیێ و سلندەرێن غازێ چ جاران د ناڤ ترمبێلێ دا ل جهێ سەرنشینان ناهێنە ڤەگوهاستن."]},{heading:"٣. ڕژانا سووتەمەنیێ",body:"کارمەندێن ڕاهێنای دشێن دگەل ڕژانەکا بچووک مامەلێ بکەن، بۆ نموونە ژ تژیکرنا زێدە؛ ڕژانەکا مەزن تەنگاڤییە:",points:["١. ڕژانێ ڕاوەستینە: دەسکا لوولەیێ بەردە یان پەمپێ ڕاوەستینە؛ ئەگەر نەڕاوەستیا، دوگمەیا ڕاوەستاندنا تەنگاڤیێ بپەستێنە.","٢. خەلکی و ترمبێلان دوور بێخە؛ کەس ل نێزیک مەکینەیەکێ هەلناکەت، جگارەیێ ناکێشیت و چ ئامێرەکێ کارەبێ ڤەناکەت.","٣. ب دەستکێشان، ڕژانێ ب خیزێ یان ماددەیا مژەر (absorbent) یا د کیتا ڕژانێ دا داپۆشە؛ ب ناڤ سووتەمەنیێ دا نەمەشە.","٤. سووتەمەنیێ ب ئاڤێ نەشۆ: ئاڤ وێ دبەتە ناڤ کەنالێن ئاڤێ، کو هەلم لێ کۆم دبیت و دشێت بتەقیت.","٥. ماددەیێ تەڕبووی د قوتیەکا ئاسنی یا گرتی دا کۆم بکە: هێشتا سووتەنێ یە.","ئێکسەر گازی ١١٥ بکە ئەگەر سووتەمەنی گەهشتە کەنالێن ئاڤێ یان جادێ، ئەگەر بێهنا سووتەمەنیێ د ناڤ ئاڤاهیەکی دا هات، ئەگەر ڕژان مەزن بوو یان ئەگەر ئاگر گرت."]},{heading:"٤. دوگمەیا ڕاوەستاندنا تەنگاڤیێ",body:"دوگمەیا ڕاوەستاندنا تەنگاڤیێ (Emergency Stop) کارەبێ ل هەمی پەمپان پێکڤە دبڕیت. جهێ دانانا وێ و چەند جاران دهێتە تاقیکرن، بەرگرییا شارستانی و دەزگەها مۆلەتدانێ دیار دکەن:",points:["هەر کارمەندەک دزانیت هەر دوگمەیەکا ڕاوەستاندنا تەنگاڤیێ ل کیڤەیە، ل ژوورێ ل نک کاشێری و ل دەرڤە ل گۆڕەپانا پەمپان، و ڕاهێنان ل سەر پەستاندنا وێ کرییە.","وێ بپەستێنە بۆ هەر ڕژانەکا تو نەشێی ڕاوەستینی، هەر ئاگرەکی، هەر دەرکەفتنەکا غازێ ل جهێ LPG و هەر ترمبێلەکا ل پەمپێ بدەت.","وێ دیار و ب نیشانەکا ئاشکرا بهێلە، و چ جاران ب کەلوپەلان، ڕەفێن نمایشێ یان ترمبێلێن ڕاوەستیای نەگرە.","پلانا تەنگاڤیێ یا بەنزینخانێ نەخشەیەکا جهی تێدایە کو تانک، پەمپ، دوگمەیێن ڕاوەستاندنا تەنگاڤیێ، تەمرینک، کیتا ڕژانێ و خالا کۆمبوونێ نیشان ددەت.","هەر کارمەندەک نیشانا دروست یا بەنزینخانێ دزانیت و دزانیت چاوا جهێ وێ بۆ ١١٥ ڕوون بکەت."]},{heading:"٥. تژیکرنا غازا ترمبێلان (LPG)",body:"غازا LPG وەک شلەمەنیەکا ب فشار دهێتە هەلگرتن. دەمێ دەردکەڤیت، عەورەکێ غازێ چێدکەت کو ژ هەوای گرانترە و دشێت ل جهەکێ دوور ژ دەرکەفتنێ هەلبیت. د پرۆفایلا ژێدەرێ پرۆژەی دا ئاگرێ LPG پۆلا B یا NFPA یە (غاز)؛ د سیستەمێ EN 2 دا پۆلا C یە.",points:["تەنێ کارمەندێن ڕاهێنای غازا LPG تژی دکەن؛ کڕیار ب خوە تژی ناکەن، ئەگەر دەزگەها مۆلەتدانێ ڕێ نەدابیت.","کارمەند ل دەمێ هەمی تژیکرنێ ل نک ترمبێلێ دمینیت، هەتا ئامێر دهێتە ڤەمراندن و ڤالڤ دهێنە گرتن.","مەکینە دهێنە ڤەمراندن، و کەس ل نێزیک جهێ تژیکرنێ جگارەیێ ناکێشیت و ئاگری بکار نائینیت.","دەستکێش و پاراستنا چاڤان بکار بینە: غازا LPG یا شل پێستی ب سەرمایێ دسووژیت.","بەری گرێدانێ ڤالڤا تژیکرنێ یا ترمبێلێ بپشکنە؛ ئەگەر غاز ژ گرێدانێ دەرکەفت، تژیکرنێ ڕاوەستینە.","ئەگەر غاز هەر دەردکەڤیت یان ئاگر گرت: دوگمەیا ڕاوەستاندنا تەنگاڤیێ بپەستێنە، خەلکی دوور بێخە و گازی ١١٥ بکە. ڤالڤا غازێ تەنێ بگرە ئەگەر ب سەلامەتی بگەهییێ؛ چ جاران ئاگرێ غازێ ڤەنەمرینە ئەگەر نەشێی غازێ ڕاوەستینی."]},{heading:"٦. ئاگر ل نک پەمپێ",body:"ئەگەر ترمبێلەک یان پەمپەک ئاگر گرت:",points:["ئێکسەر دوگمەیا ڕاوەستاندنا تەنگاڤیێ بپەستێنە و زەنگا ئاگری لێبدە.","بێژە شوفێری کو سەرێ لوولەیێ د ترمبێلێ دا بهێلیت و دوور بکەڤیت؛ هەمییان ژ ترمبێلان دەربێخە و ژ پەمپان دوور بێخە.","گازی ١١٥ بکە (و ١٢٢ ئەگەر کەسەک بریندار بوو) و ئێکەم جار ناڤ و نیشانا بەنزینخانێ بێژە.","هەمییان ب کێمی ٣٠ مەتر (١٠٠ پێ) ژ ترمبێلا ئاگرگرتی دوور بهێلە، و نەهێلە ترمبێلێن دی بهێنە ناڤ بەنزینخانێ.","کاپۆتێ (قەپاغێ مەکینێ) یان سندۆقا پشتێ یا ترمبێلەکا ئاگرگرتی ڤەنەکە: هەوایێ تازە ئاگری مەزنتر دکەت.","کارمەندەکێ ڕاهێنای دشێت تەمرینکێ بکار بینیت تەنێ ل سەر ئاگرەکێ بچووک و تازە دەستپێکری، ب تەمرینکەکا لایبلا وێ سووتەمەنیا شل دگریت (پۆلا B؛ NFPA B یا شلەمەنیان = EN B)، دەمێ ڕێکا دەرکەفتنێ ل پشت وی بیت و ئاگەهداری هاتبیتە دان. ژ وێ دووراتیێ دەستپێ بکە یا ل سەر لایبلێ هاتی؛ ئەگەر ئاگر ئێکسەر ڤەنەمری، دوور بکەڤە.","ڤان هەنگاڤان ب ڕاهێنانێن ب ڕێکوپێک دگەل هەمی کارمەندان دووبارە بکە، و هەر ڕاهێنانەکێ تۆمار بکە."],critical:!0}],media:[{kind:"image",src:"media/images/w8_fuel_station_safety.webp",title:"تژیکرنا سەلامەت ل نک پەمپێ",description:"مەکینە ڤەمراندی، دەبە ل سەر عەردی، دوگمەیا ڕاوەستاندنا تەنگاڤیێ و تەمرینک ئامادە"}],quiz:[{question:"کڕیارەک ل دەمێ تژیکرنێ زڤڕییە د ترمبێلێ دا و نوکە دزڤڕیتە نک پەمپێ. بەری دەست بدەتە سەرێ لوولەیێ، دڤێت چ بکەت؟",options:[{text:"دەستێ خوە ل ئاسنێ ترمبێلێ بدەت، دوور ژ جهێ تژیکرنێ",correct:!0},{text:"دەسکا لوولەیێ ب پەڕۆیەکێ هشک پاقژ بکەت",correct:!1},{text:"سەرێ لوولەیێ ب لەز دەربێخیت و پەمپێ دووبارە هەلکەت",correct:!1},{text:"د ترمبێلێ دا بمینیت هەتا پەمپ ب خوە ڕادوەستیت",correct:!1}],explanation:"خلیسکاندن ل سەر کورسیێ کارەبا ستاتیکی کۆم دکەت. دەستدانا ل ئاسنی دوور ژ جهێ تژیکرنێ وێ کارەبێ ڤالا دکەت بەری دەست بگەهیتە سەرێ لوولەیێ، کو چریسکەک دشێت لێ هەلمێ هەلکەت."},{question:"سووتەمەنی ژ لوولەیەکا کو ناهێتە گرتن ل سەر عەردێ بەنزینخانێ دڕژیت. ئێکەم کار چییە؟",options:[{text:"سووتەمەنیێ ب ئاڤێ بەرەڤ کەنالێن ئاڤێ بشۆ",correct:!1},{text:"ڕژانێ ب پەمپێ یان ب دوگمەیا تەنگاڤیێ ڕاوەستینە",correct:!0},{text:"ترمبێلێ هەلکە و ژ نک ڕژانێ دوور ببە",correct:!1},{text:"ماددەیا مژەر ل دۆرێ بڕێژە بەلێ پەمپێ نەڕاوەستینە",correct:!1}],explanation:"ئێکەم ژێدەرێ ڕژانێ ڕاوەستینە، پاشان ژێدەرێن هەلبوونێ و خەلکی دوور بێخە و ڕژانێ ب ماددەیا مژەر کۆنترۆل بکە. ئاڤ سووتەمەنیێ دبەتە ناڤ کەنالان، کو هەلم لێ کۆم دبیت، و هەلکرنا مەکینەیەکێ دشێت هەلمێ هەلکەت."},{question:"دەمێ دەبەیەکا سووتەمەنیێ دهێتە تژیکرن، دڤێت ل کیڤە بیت؟",options:[{text:"د پشتا پیکاپەکێ دا، ئامادە بۆ چوونێ",correct:!1},{text:"ل سەر کورسیێ پشتێ، و سەرنشینەک وێ دگریت",correct:!1},{text:"ل سەر عەردی، و سەرێ لوولەیێ ب دەبەیێ ڤە",correct:!0},{text:"د سندۆقا پشتێ دا، و قەپاغێ وێ ب تەمامی ڤەکری",correct:!1}],explanation:"د ناڤ ترمبێلێ دا، فەرش یان ڕووپۆشا پلاستیکی یا پیکاپێ دەبەیێ ژ عەردی جودا دکەن، لەوما کارەبا ستاتیکی یا ژ ڕژانا سووتەمەنیێ نەشێت دەرکەڤیت و دشێت ل سەرێ لوولەیێ چریسکێ بدەت (NIOSH). ل سەر عەردی و دەمێ سەرێ لوولەیێ ب دەبەیێ ڤە، کارەبا ب سەلامەتی دچیتە عەردی."},{question:"ل دەمێ تژیکرنا LPG، غاز ژ گرێدانێ دەردکەڤیت. دڤێت کارمەند چ بکەت؟",options:[{text:"تژیکرنێ ڕاوەستینیت، ڤالڤان بگریت و خەلکی و مەکینەیان دوور بێخیت",correct:!0},{text:"تژیکرنێ ب لەز ب دوماهیک بینیت و پاشان گرێدانێ قایم بکەت",correct:!1},{text:"ب تەمرینکا CO₂ ل دەرکەفتنێ بدەت دا گرێدانێ سار بکەت",correct:!1},{text:"ژ شوفێری بخوازیت مەکینێ هەلکەت و ئێکسەر بچیت",correct:!1}],explanation:"غازا LPG یا دەردکەڤیت عەورەکێ غازێ چێدکەت کو دشێت هەلبیت. تژیکرنێ ڕاوەستینە، ئەگەر ب سەلامەتی بگەهییێ غازێ بگرە و ژێدەرێن هەلبوونێ دوور بهێلە؛ ئەگەر دەرکەفتن نەڕاوەستیا، دوگمەیا ڕاوەستاندنا تەنگاڤیێ بپەستێنە و گازی ١١٥ بکە."},{question:"ترمبێلەک ل نک پەمپێ ئاگر گرت. کیژ کار دروستە؟",options:[{text:"بەری هەر تشتەکی سەرێ لوولەیێ ژ ترمبێلێ دەربێخە",correct:!1},{text:"کاپۆتێ ڤەکە دا ئاگر بهێتە دیتن و بگەهییێ",correct:!1},{text:"ب لوولەیا ئاڤێ ئاڤێ ل سەر سووتەمەنیا دسۆژیت بڕێژە",correct:!1},{text:"دوگمەیا تەنگاڤیێ بپەستێنە، جهی ڤالا بکە و گازی ١١٥ بکە",correct:!0}],explanation:"دوگمەیا ڕاوەستاندنا تەنگاڤیێ سووتەمەنیێ ل هەمی پەمپان دبڕیت. سەرێ لوولەیێ ل جهێ وێ بهێلە، کاپۆتێ گرتی بهێلە و هەمییان ب باشی دوور بێخە؛ ئاڤ سووتەمەنیا دسۆژیت بەلاڤ دکەت."}]},{id:26,code:"IND-126",icon:"Package",accent:"#0f766e",title:"سەلامەتیا کۆگەهان ژ ئاگری",subtitle:"Stacking, Clearances, Sprinklers, Battery Charging & Security",summary:"ل کۆگەهێ، ئاگر دشێت د چەند خولەکان دا ب کۆمەکا کەلوپەلان دا هەتا بانی هەلکشیت. ئەڤ مۆدیولە نیشا کارمەند، سەرپەرشتیار و ڕێڤەبەران ددەت کا چاوا کەلوپەلان ب سەلامەتی کۆم بکەن و هەلگرن، سپرینکلەران کاراکری بهێلن، باترییێن فۆرکلیفتان شەحن بکەن، دگەل باترییێن لیتیۆم-ئایۆن و کەلوپەلێن مەترسیدار مامەلێ بکەن و ئاڤاهی ب شەڤ بپارێزن.",blocks:[{body:"د کەلوپەلێن ل سەر ئێک کۆمکری و ڕەفێن بلند دا، ئاگر ب لەز بەرەڤ سەرێ کۆمێ هەلدکشیت و پاشان ب ئالیان دا بۆ هەمی ئاستان بەلاڤ دبیت؛ د تاقیکرنان دا ل سەر قوتیێن ل سەر ڕەفێن ب بلندیا ١٠ مەتران، ئاگر گەلەک جاران د ماوێ دوو خولەکان دا گەهشتە سەرێ ڕەفان (ڕێبەرێ حکوومەتا بەریتانی بۆ سەلامەتیا کارگەه و کۆگەهان ژ ئاگری). بارێ ئاگری (Fire Load) یێ کۆگەهێ ل دویڤ وان کەلوپەلانە یێن تێدا دهێنە هەلگرتن، و گەلەک جاران ژ یێ خانی و نڤیسینگەهان بلندترە. ڕێسایێن خوارێ ڕێکارێن باشێن گشتینە؛ هەر ئاڤاهیەک دڤێت بەری هەمی تشتان داخوازێن بەرگرییا شارستانی و دەزگەها مۆلەتدانێ ب جهـ بینیت."},{heading:"١. کۆمکرنا کەلوپەلان و جهێ ڤالا",body:"کەلوپەلێن هەلگرتی دڤێت جێگیر بن و ڕێکێ ل خەلکی، سپرینکلەران و ئاگرکوژان نەگرن:",points:["کەلوپەلان ب ڕەنگەکێ جێگیر کۆم بکە: ب پشتگری، ب ئێکدا گرێدای و ب بلندیەکا سنووردار، دا نەخلیسکن و نەهەرفن.","زێدە ژ پێدڤی کۆم نەکە: هەر جهەکێ هەلگرتنێ زێدەترین بڕەکا نڤیسی هەیە.","ب کێمی ١ مەتر جهێ ڤالا د ناڤبەرا سەرێ کەلوپەلان و بانی، کاریتێن بانی یان گلۆپان دا بهێلە (ڕێنماییا HSE یا بەریتانی).","ل بن سەرێن سپرینکلەران، ئەو جهێ ڤالا بهێلە یێ دیزاینا سپرینکلەری دیار دکەت؛ کێمترین ڕێژەیا گشتی ل دویڤ OSHA ٤٥ سانتیمەترە (١٨ ئینچ)، و هندەک جۆرێن سپرینکلەران پێدڤی ب پتر هەنە.","چ جاران نەهێلە ڕەف و کەلوپەل سەرێن سپرینکلەران داپۆشن.","کەلوپەلێن سووتەنێ ل سەر ئامێرێن کارەبێ، گلۆپ یان سۆبەیان کۆم نەکە، هەتا ئەگەر ڤەمراندی ژی بن.","پالێتێن ڤالا، ماددەیێن پاکێتکرنێ و پاشماوەیان ل جهەکێ دیارکری دوور ژ ئاڤاهی، دەرکەفتن و پەنجەران، یان ل جهەکێ ب سپرینکلەر هەلگرە."]},{heading:"٢. ڕێڕەو، دەرکەفتن و دەرگەهێن ئاگری",body:"ڕێکێن ڤەکری ڕێ ددەن خەلک دەرکەڤن و تیمێن ١١٥ بگەهنە ئاگری:",points:["ڕێڕەو و دەرباز ڤەکری و ساخلەم بهێلە؛ ڕێڕەوێن هەمیشەیی ل سەر عەردی نیشانکرینە.","چ جاران کەلوپەلان د ڕێکێن دەرکەفتنێ دا یان ل بەر دەرکەفتن، دەرگەهێن ئاگری، پەردێن ئاسنی یێن ئاگری (fire shutters)، تەمرینک یان دوگمەیێن زەنگا ئاگری دانەنێ.","جهەکێ ڤالا د ناڤبەرا کەلوپەلان و دیوارێن ناڤخوەیی دا بهێلە دا ئاگرکوژ بگەهنە ئاگری (ڕێنماییا بەریتانی: ٠٫٥ مەتر).","دەرکەفتنێن ئاگری دڤێت ژ ناڤدا بێی کلیل ڤەببن هەر دەمێ کەسەک د ئاڤاهی دا بیت.","تەنێ شوفێرێن ڕاهێنای و مۆلەتدار فۆرکلیفتان دئاژۆن، و پیادە د ڕێڕەوێن نیشانکری دا دمەشن."]},{heading:"٣. سپرینکلەر: کاراکری بهێلە",body:"سپرینکلەر ئاگری ب شێوەیەکێ ئۆتۆماتیکی کۆنترۆل دکەن، هەتا ب شەڤ دەمێ کەس نەبیت، بەلێ تەنێ ئەگەر چ تشت ڕێکێ ل وان نەگریت:",points:["چ جاران چ تشتی ب سەرێن سپرینکلەران یان بۆریێن وان ڤە هەلنەاویسە، و چ جاران وان ڕەنگ نەکە، دانەپۆشە و لێ نەدە؛ هەر سەرەکێ زیانلێکەفتی یان ئاڤ ژێ دچۆڕیت ئێکسەر ڕاگەهینە.","ڤالڤێن کۆنترۆلا سپرینکلەران ب تەمامی ڤەکری دمینن. تەنێ کەسەکێ مۆلەتدار دشێت ئێکێ بگریت، ل دویڤ ڕێکارا جهی بۆ ڕاوەستاندنا پاراستنا ژ ئاگری، و دگەل چاڤدێریا ئاگری یا زێدە هەتا جارەکا دی دهێتە ڤەکرن.","ئەگەر تە ڤالڤەکا گرتی یان سەرەکێ داپۆشی دیت، ئێکسەر بێژە سەرپەرشتیاری: دبیت ئەو جهـ بێ پاراستن بیت.","سپرینکلەر تەنێ ل وی جهی ڤەدبن یێ گەرمیا ئاگری دگەهیتێ، لەوما ئاگرەک ل بن سەرەکێ داپۆشی دشێت بێی کو بهێتە دیتن مەزن ببیت.","پشکنین، تاقیکرن و ساخکرن ل دویڤ NFPA 25 و داخوازێن بەرگرییا شارستانی دهێنە کرن؛ تۆماران بپارێزە.","هندەک بەرهەم نابیت ب چ ڕەنگان ل جهێن ب سپرینکلەر بهێنە هەلگرتن؛ پەڕا زانیاریێن سەلامەتیێ (SDS) ڤێ چەندێ دیار دکەت."]},{heading:"٤. شەحنکرنا باترییێن فۆرکلیفتان",body:"دەمێ باترییێن ئەسیدی (lead-acid) دهێنە شەحنکرن، غازا هایدرۆجین ژێ دەردکەڤیت کو غازەکا گەلەک سووتەنێ یە؛ ئەگەر کۆم ببیت و چریسکەک یان ئاگرەک بگەهیتێ، دشێت بتەقیت:",points:["تەنێ ل جهێ دیارکری یێ شەحنکرنێ شەحن بکە: جهەکێ ب هەواگوهۆڕینا باش (ب هەواگوهۆڕینێ ل بلندیێ ل سەر باترییان)، دوور ژ کەلوپەلێن هەلگرتی و ژێدەرێن هەلبوونێ.","ل جهێ شەحنکرنێ نە جگارە، نە ئاگر، نە کارێ گەرم و نە مۆبایل.","بەری گرێدان یان ڤەکرنا باترییێ، شەحنکەری ڤەمرینە، دا چریسک چێنەبیت.","ئامێر و تشتێن ئاسنی یێن دی ل سەر باترییان دانەنێ، و بەری کارکرنێ ل سەر وان دەمژمێر، ئەنگوستیلک و تشتێن ئاسنی یێن دی ژ خوە بکە.","ل دەمێ شەحنکرنێ قەپاغێ باترییێ ڤەکە، و ئامێرێن پاراستنێ یێن بۆ ڤی کاری دیارکری بکار بینە (دەستکێش، بەروانک و پاراستنا چاڤان دژی ئەسیدی).","سلندەرێن غازێ (LPG) یێن فۆرکلیفتێن ب غازێ ل دەرڤە بگوهۆڕە، دوور ژ ژێدەرێن هەلبوونێ.","تەنێ کارمەندێن ڕاهێنای باتریان دگوهۆڕن یان شەحن دکەن."]},{heading:"٥. باترییێن لیتیۆم-ئایۆن",body:"باترییێن لیتیۆم-ئایۆن یێن زیانلێکەفتی، زێدە گەرمبووی یان ب شێوەیەکێ خەلەت شەحنکری دشێن ئاگر بگرن یان بتەقن، و گەرمیا خانەیەکا تێکچووی دشێت بگەهیتە خانەیا ل نک وێ (thermal runaway):",points:["ڕێنماییێن دروستکەری بۆ هەلگرتن، بکارئینان و شەحنکرنێ پەیڕەو بکە، و تەنێ ئەو شەحنکەرێ بۆ وێ باترییێ هاتیە چێکرن بکار بینە.","باتری و ئامێران ل جهێن هشک و فێنک، دوور ژ سۆبە و ژێدەرێن دی یێن گەرمیێ هەلگرە، و دەمێ تژی بوون ژ شەحنێ ڤەکە.","ل نیشانێن مەترسیێ بگەڕە: پەنەمین یان قلیشین، دەنگێ فیشکێ، چۆڕین، بلندبوونا گەرمیێ یان دوکێل. باترییا هەر ئێک ژ ڤان نیشانان تێدا بیت ئێکسەر ژ کار دهێتە دەرێخستن.","ئەگەر دەستدان لێ سەلامەت بیت، وێ ببە جهێ دیارکری دوور ژ ماددەیێن سووتەنێ، بۆ نموونە قوتیەکا ئاسنی یا بەرگرێ ئاگری دگەل خیزێ، و ب ڕێکا پەسەندکری بۆ ژناڤبرنێ بفرێکە.","ئەگەر باتری دوکێلێ ددەت یان دسۆژیت، هەلنەگرە: خەلکێ دی ئاگەهدار بکە، زەنگا ئاگری لێبدە، دەرکەڤە و گازی ١١٥ بکە. خانەیێن لیتیۆم-ئایۆن لیتیۆما کانزایی تێدا نینە و ب ئاڤەکا گەلەک دهێنە سارکرن؛ ئاگرەک د باترییێن هەلگرتی دا کارێ تیمێن ١١٥ یە.","ئاگرێ باتریان دشێت پشتی ڤەمرینێ جارەکا دی هەلبیت؛ بۆ تیمێن ١١٥ بێژە کا باتری ل کیڤە دهێنە هەلگرتن."],critical:!0},{heading:"٦. پاقژی و کەلوپەلێن مەترسیدار",body:"پاشماوەیێن کێمتر واتە سووتەمەنیا کێمتر بۆ ئاگری، و هەلگرتنا دروست ڕووداوەکێ بچووک بچووک دهێلیت:",points:["جهێن هەلگرتنێ ژ ماددەیێن پاکێتکرنێ یێن بەلاڤ و پاشماوەیان پاقژ بهێلە؛ پاشماوەیان د قوتیێن گونجای دا کۆم بکە و ب ڕێکی ڕاکە.","ل جهێن هەلگرتنێ جگارەکێشان قەدەغەیە.","بەری هەلگرتنا هەر بەرهەمەکێ مەترسیدار، لایبل و پەڕا زانیاریێن سەلامەتیێ (SDS) یا وی بخوینە؛ بەشێ ٧ یێ SDS مەرجێن هەلگرتنێ و ئەو ماددەیێن پێکڤە ناگونجن دیار دکەت.","ماددەیێن پێکڤە نەگونجای ژێک جودا بهێلە: ئەگەر پێکڤە بهێنە هەلگرتن، دشێن ئاگری لەزتر مەزن بکەن یان دوکێلا ژەهراوی بەلاڤ بکەن.","دەبە و قوتیێن زیانلێکەفتی یان یێن دچۆڕن نەخە ناڤ کۆگەهێ؛ وان د سینیەکێ یان حەوزەکێ ڕاگرتنێ (bund) دا دانێ و ڕێنماییێن دابینکەری پەیڕەو بکە.","تۆمارەکێ نوو یێ کەلوپەلێن مەترسیدار و جهێن وان بپارێزە، ل جهەکێ کو د تەنگاڤیێ دا بشێی بدەیە تیمێن ١١٥."]},{heading:"٧. پاراستنا شەڤێ و زەنگا ئاگری",body:"ئاگرێ دەمێ ئاڤاهی گرتی دەستپێ دکەت دشێت بێی کو بهێتە دیتن مەزن ببیت، و ئاڤاهیێن ڤالا ئارمانجا ئاگربەردانا ب ئانقەست (arson) نە:",points:["دەرڤەیێ ئاڤاهی ب باشی ڕۆناهی بکە و سنوورێ جهی پاراستی بهێلە؛ دەرگەه، پەنجەرە و کونێن بانی بگرە بێی کو ڕێکێن دەرکەفتنێ بگری.","قوتیێن مەزنێن پاشماوەیان ل نک دیوارێ ئاڤاهی دانەنێ؛ سەلکێن پاشماوەیان د جهەکێ پەرژینکری و قوفلکری دا دوور ژ ئاڤاهی هەلگرە.","شلەمەنی و غازێن سووتەنێ قوفل بکە دا کەسێن ب دزی دهێنە ژوور نەشێن بکار بینن.","زەنگا ئاگری و زەنگا دزیێ دهێنە چاڤدێریکرن، و کەسەک ئێکسەر بەرسڤا هەر زەنگەکێ ددەت.","پاسەوان دزانن چاوا زەنگا ئاگری لێبدەن، چاوا ب نیشانا دروست گازی ١١٥ بکەن و چاوا ل بەر دەرگەهی دگەل کلیل و نەخشەیا جهی پێشوازیێ ل تیمێن ١١٥ بکەن.","کەسێن ب شێوەیەکێ گومانلێکری دلڤن و هەر ئاگرەکێ بچووک یێ ئەگەرێ وی نەدیار ڕاگەهینە؛ دبیت نیشانا ئاگربەردانا ب ئانقەست بن.","هەلسەنگاندنا مەترسیێن ئاگری ب کێمی سالێ جارەکێ و پشتی هەر گوهۆڕینەکا مەزن د وێ چەندێ دا یا تو هەلدگری یان چاوا هەلدگری نوو بکە."]}],media:[{kind:"image",src:"media/images/w8_warehouse_fire_safety.webp",title:"کۆگەهەکا ڕێکخستی و سەلامەت ژ ئاگری",description:"ڕێڕەوێن ڤەکری، جهێ ڤالا ل بن سپرینکلەران و جهەکێ جودا بۆ شەحنکرنێ"}],quiz:[{question:"ل دویڤ ڕێنماییا HSE یا بەریتانی، چەند جهێ ڤالا دڤێت د ناڤبەرا سەرێ کەلوپەلێن هەلگرتی و بانی، کاریتان یان گلۆپان دا بهێتە هێلان؟",options:[{text:"ب کێمی ١ مەتر",correct:!0},{text:"ب کێمی ١٠ سانتیمەتر",correct:!1},{text:"ب کێمی ٢٥ سانتیمەتر",correct:!1},{text:"چ نە، ئەگەر کۆم جێگیر بیت",correct:!1}],explanation:"ڕێنماییا HSE بۆ کۆگەهان ب کێمی ١ مەتر د ناڤبەرا سەرێ کەلوپەلان و بانی، کاریتێن بانی یان گلۆپان دا دخوازیت؛ ل بن سپرینکلەران، ئەو جهێ ڤالا یێ دیزاینا سپرینکلەری دیار دکەت دهێتە پەیڕەوکرن (کێمترین ڕێژەیا گشتی ل دویڤ OSHA ٤٥ سانتیمەترە)."},{question:"دەمێ شەحنکرنا باترییێن فۆرکلیفتان، کیژ ڕێکار دروستە؟",options:[{text:"د ناڤبەرا ڕەفان دا شەحن بکە دا فۆرکلیفت بۆ دەوامێ پاشتر ئامادە بیت",correct:!1},{text:"باترییێ ڤەکە دەمێ شەحنکەر هێشتا هەلکری بیت",correct:!1},{text:"جهێ شەحنکرنێ یێ ب هەواگوهۆڕین بکار بینە، بێ جگارە و ئاگر",correct:!0},{text:"ئامێرێن ئاسنی ل سەر باترییێ دانێ دا نێزیک بن",correct:!1}],explanation:"شەحنکرن غازا هایدرۆجین بەلاڤ دکەت. جهەکێ دیارکری یێ ب هەواگوهۆڕین و بێ ژێدەرێن هەلبوونێ نەهێلیت ئەو غاز کۆم ببیت و هەلبیت؛ ڤەمراندنا شەحنکەری بەری ڤەکرنێ و دووراتیا ئامێرێن ئاسنی ژ باترییێ ڕێکێ ل چریسکان دگرن."},{question:"ل دەمێ ژمارتنا کەلوپەلان، تە ڤالڤەکا کۆنترۆلا سپرینکلەران گرتی دیت. دێ چ کەی؟",options:[{text:"ئێکسەر بۆ سەرپەرشتیاری ڕادگەهینم دا ب سەلامەتی بهێتە ڤەکرن",correct:!0},{text:"وێ گرتی دهێلم، چونکی زەنگا ئاگری دێ ئاگەهدار کەت",correct:!1},{text:"نیڤی ڤەدکەم دا فشارا ئاڤێ د بۆریان دا نزم بمینیت",correct:!1},{text:"نیشانەکێ ل سەر دادنێم و د پشکنینا هەیڤا بێت دا دپشکنم",correct:!1}],explanation:"ڤالڤەکا کۆنترۆلێ یا گرتی دشێت جهەکێ تەمام بێ پاراستنا سپرینکلەری بهێلیت. دڤێت ئێکسەر بهێتە ڕاگەهاندن و ژ لایێ کەسەکێ مۆلەتدار ڤە ل دویڤ ڕێکارا جهی بهێتە ڤەکرن."},{question:"باترییەکا لیتیۆم-ئایۆن یا هەلگرتی پەنەمییە و گەرم دبیت. کارێ دروست چییە؟",options:[{text:"ژ کار دەربێخە؛ ئەگەر دوکێلێ دا، زەنگێ لێبدە و گازی ١١٥ بکە",correct:!0},{text:"دیسان بخە سەر شەحنێ دا خانە هەڤسەنگ ببن و سار ببن",correct:!1},{text:"د کارتۆنی دا بپێچە و ل سەر ڕەفێ بهێلە هەتا بهێتە برن",correct:!1},{text:"جارەکێ ب CO₂ لێبدە و دیسان بزڤڕینە سەر ڕەفێ",correct:!1}],explanation:"پەنەمین و گەرمی نیشانێن تێکچوونا باترییێ نە. باترییێ ژ کار دەربێخە و ئەگەر دەستدان لێ سەلامەت بوو، دوور ژ ماددەیێن سووتەنێ جودا بکە؛ ئەگەر دوکێلێ دا یان سۆت، دەست لێ نەدە: زەنگێ لێبدە، دەرکەڤە و گازی ١١٥ بکە."},{question:"کیژ ڕێکار باشترین پاراستنێ ددەتە کۆگەهەکا گرتی دژی ئاگربەردانا ب ئانقەست؟",options:[{text:"قوتیێن مەزنێن پاشماوەیان ل نک دیواری دا پاسەوان وان ببینن",correct:!1},{text:"ڤەمراندنا زەنگێ ب شەڤ دا زەنگێن خەلەت نەبن",correct:!1},{text:"پاشماوە دوور ژ ئاڤاهی و زەنگەکا ب چاڤدێری",correct:!0},{text:"هێلانا شلەمەنیێن سووتەنێ ل نک دەرگەهی بۆ گەهاندنا سپێدێ",correct:!1}],explanation:"ئاگربەردەر گەلەک جاران پاشماوە و شلەمەنیێن سووتەنێ یێن ل جهی بکار دئینن. دووراتیا قوتیێن پاشماوەیان ژ ئاڤاهی، قوفلکرنا ماددەیێن سووتەنێ و زەنگێن کو دهێنە چاڤدێریکرن و بەرسڤ دهێتە دان مەترسیێ کێم دکەن (ڕێبەرێ حکوومەتا بەریتانی)."}]},{id:27,code:"IND-127",icon:"HardHat",accent:"#ca8a04",title:"سەلامەتیا جهێن ئاڤاهیسازیێ",subtitle:"Fire Plan, Hot Work, Temporary Electrics, Cylinders, Excavations & UXO",summary:"ئاڤاهیێن د قۆناغا ئاڤاکرنێ دا گەلەک جاران هێشتا سپرینکلەر یان زەنگێن ئاگری یێن کاردکەن نینن، بەلێ پڕی ژێدەرێن هەلبوونێ و کەرەستەیێن سووتەنێ نە. ئەڤ مۆدیولە نیشا کارگەر، سەرپەرشتیار و ڕێڤەبەران ددەت کا چاوا پلانێ بۆ ئاگری دانن؛ کارێ گەرم، کارەبا کاتی و سلندەرێن سووتەمەنی و غازێ کۆنترۆل بکەن؛ مەترسیێ ل نک داربەستان و چالێن کۆلانێ بناسن؛ هەوارهاتنا ئێکێ بدەن؛ و چ بکەن دەمێ ل دەمێ کۆلانێ تشتەکێ گومانلێکری دهێتە دیتن.",blocks:[{body:"ل دویڤ NFPA، ئەگەرێن سەرەکی یێن ئاگری ل ئاڤاهیێن د قۆناغا ئاڤاکرنێ دا ئامێرێن خوارنچێکرنێ، ئامێرێن دابەشکرنا کارەبێ و ڕۆناهیێ، و ئامێرێن گەرمکرنێ نە. دبیت سپرینکلەر، دەتێکتەرێن دوکێلێ و زەنگێن ئاگری هێشتا کار نەکەن، و جهێن ڤەکری خەلکێ بێ مۆلەت و ئاگربەردانا ب ئانقەست ڕادکێشن. ڕێسا، مۆلەت و ڕوخسەتێن جهێن ئاڤاهیسازیێ ژ لایێ بەرگرییا شارستانی و دەزگەها مۆلەتدانێ ڤە دهێنە دانان: داخوازێن وان پەیڕەو بکە. ئەڤ مۆدیولە ڕێسایێن بنەڕەتی بۆ هەر کەسەکێ ل جهی ددەت."},{heading:"١. پلانا ئاگری یا جهی و خالا کۆمبوونێ",body:"بەری دەستپێکرنا کاری، گرێبەستکارێ سەرەکی یێ جهی ب دەست ڤە، پلانا ئاگری ئامادە دکەت:",points:["هەلسەنگاندنەکا مەترسیێن ئاگری و پلانەکا تەنگاڤیێ یا نڤیسی، بەری دەستپێکرنا کاری ئامادە و دگەل بلندبوونا ئاڤاهی نووکری.","کەسەکێ دیارکری ڕێگرتنا ل ئاگری ل جهی ڕێڤە دبەت (د NFPA 241 دا: ڕێڤەبەرێ بەرنامێ ڕێگرتنا ل ئاگری).","ڕێکێن دەرکەفتنێ ژ هەر جهەکێ کاری، ڤەکری و ب نیشان، و چ جاران قوفلکری نابن دەمێ خەلک ل جهی؛ هەر جهەکێ بکاربیت، دوو ڕێک ب دوو ئاراستەیێن جودا.","زەنگەکا ئاگری کو هەمی کەس ل سەر دەنگێ جهی گوه لێ ببن، و نیشانێن ڕێنماییێن ئاگری ل خالێن ئاگری، دەرگەهێن جهی و جهێن خوارنێ.","خالێن ئاگری دگەل تەمرینکێن گونجای، و کەسێن دیارکری یێن ڕاهێنان ل سەر بکارئینانا وان دیتی.","خالەکا کۆمبوونێ کو هەمی کەس لێ دهێنە ژمارتن، ب ژمارتنا کەسان یان ب گەڕیانا ل جهی.","ڕاهێنانێن دەرکەفتنێ بۆ تاقیکرنا پلان و ڕاهێنانێ؛ هەر کارگەرەکێ نوو و هەر میوانەک ل دەستپێکێ پلانێ فێر دبیت."]},{heading:"٢. کارێ گەرم: مۆلەت و چاڤدێرێ ئاگری",body:"لەحیمکرن، بڕین، هێرانا ب ئامێران (grinding) و کارێ ب ئاگری گەلەک ئاگران ل جهێن ئاڤاهیسازیێ هەلدکەن. ئەگەر ڕێکەکا دی کاری بکەت، وێ بکار بینە؛ ئەگەر نە:",points:["تەنێ ب مۆلەتا کارێ گەرم (Hot Work Permit) کار بکە کو ژ لایێ وی کەسی ڤە هاتبیتە دان یێ دەستهەلاتا پەسەندکرنێ هەی.","ماددەیێن سووتەنێ ژ ١١ مەتران (٣٥ پێ) دۆرا کاری ڕاکە، یان ب بەتانی یان پەردێن بەرگرێ ئاگری وان بپارێزە، یان کاری ببە جهەکێ سەلامەت.","تەمرینکەکا گونجای ل جهێ کاری ئامادە بهێلە.","چاڤدێرێ ئاگری (Fire Watch) ل دەمێ کاری و ل دەمێ بێهنڤەدانێ، و ب کێمی ١ دەمژمێر پشتی ب دوماهیک هاتنا کاری دمینیت؛ بەرپرسێ مۆلەتێ دشێت چاڤدێریەکا درێژتر بخوازیت (NFPA 51B).","کارێ گەرم ب ڕەنگەکی پلان بکە کو گەلەک بەری دوماهیکا ڕۆژا کاری ب دوماهیک بهێت، دا پشکنین بەری گرتنا جهی بهێنە کرن (HSE یا بەریتانی: ٢ دەمژمێران بەری هنگێ)."]},{heading:"٣. کارەبا کاتی",body:"تێلێن کارەبێ یێن کاتی ل جهی ئاگر و کارەبێدان چێدکەن دەمێ زێدە بار ل سەر بیت، زیان پێ گەهشتبیت یان ژ لایێ کەسێن نەشارەزا ڤە هاتبنە گوهۆڕین:",points:["دامەزراندنێن کاتی تەنێ ژ لایێ کارەباچیەکێ شارەزا ڤە دهێنە دیزاینکرن، دانان، گوهۆڕین و پشکنین؛ کەسەکێ دی چ تشتان لێ زێدە ناکەت و ناگوهۆڕیت.","ئەو پلاکێن کارگەر بکار دئینن ب ئامێرەکێ پاراستنێ ژ دەرکەفتنا کارەبێ (RCD) دهێنە پاراستن، کو دەمێ کارەبا بەرەڤ عەردی دەردکەڤیت ب لەز کارەبێ دبڕیت؛ دوگمەیا تاقیکرنا وێ ب ڕێکوپێکی بپەستێنە. RCD مەترسیێ کێم دکەت بەلێ جهێ دامەزراندنەکا سەلامەت ناگریت.","زێدە بار نەخە سەر پلاک و پلاکێن چەندڕێ، تێلێن درێژکرنێ نەخە ناڤ ئێکدو، و بەری بکارئینانێ تێلێن پێچای ب تەمامی ڤەکە.","بۆ تێلێن درێژکرنێ تێلا نەرم یا گونجای بکار بینە، ب بلندی ژ عەردی؛ تێل و ئامێرێن زیانلێکەفتی ژ کار دەربێخە و ب شریتێ عەزلێ نەپێچە.","تێلێن کاتی یان تابلۆیێن دابەشکرنا کارەبێ د ڕێکێن دەرکەفتنێ دا دانەنێ، و پاشماوەیان ژ تابلۆیێن کارەبێ دوور بهێلە."]},{heading:"٤. سووتەمەنی و سلندەرێن غازێ ل جهی",body:"سووتەمەنی، LPG، ئەسیتیلین و ئۆکسجین بڕەکا مەزن ژ وزەیا هەلگرتی دئیننە جهی:",points:["تەنێ کێمترین بڕا پێدڤی ل جهی بهێلە، د کۆگەهەکا پاراستی و ب هەواگوهۆڕینا باش دا، دوور ژ ماددەیێن سووتەنێ و جهێن کاری، و چ جاران د ناڤ ئاڤاهیێ د قۆناغا ئاڤاکرنێ دا نە.","بۆ سووتەمەنیێ تەنێ دەبەیێن پەسەندکری بکار بینە، و چ جاران سووتەمەنیێ د دەرکەفتن، پلەکان یان ڕێڕەوان دا هەلنەگرە.","ئامێران ل جهەکێ دیارکری سووتەمەنی بکە، دەمێ مەکینە ڤەمراندی بن، بێ جگارە و تەمرینکەک ل نێزیک بیت.","سلندەرێن غازێ ب ڕاستی و گرێدای بهێلە دا نەکەڤن، دەمێ نەهێنە بکارئینان سەرپۆشێ ڤالڤێ ل سەر بیت، و دوور ژ چریسک، پاشماوەیێن لەحیمێ یێن گەرم و ئاگری.","سلندەرێن ئۆکسجینێ ژ سلندەرێن غازا سووتەنێ جودا هەلگرە: ب کێمی ٦ مەتر (٢٠ پێ) د ناڤبەرا وان دا، یان ل پشت دیوارەکێ بەرگرێ ئاگری (OSHA).","ل دوماهیکا ڕۆژێ سووتەمەنی و سلندەران قوفل بکە دا کەسێن ب دزی دهێنە ژوور نەشێن بکار بینن.","ئەگەر سلندەرەک غاز ژێ دەرکەفت یان ئاگر گرت: ڤالڤێ تەنێ بگرە ئەگەر ب سەلامەتی بگەهییێ؛ چ جاران ئاگرێ غازێ ڤەنەمرینە ئەگەر نەشێی غازێ ڕاوەستینی؛ هەمییان دوور بێخە و گازی ١١٥ بکە."]},{heading:"٥. داربەست و چالێن کۆلانێ: مەترسیێ بناسە و ڕاوەستە",body:"کەفتن ژ بلندیێ و هەرفتنا خەندەکێ کارگەرێن ئاڤاهیسازیێ دکوژن. دیزاینکرنا داربەستان و پشتگرێن خەندەکێ کارێ پسپۆرێن شارەزایە؛ هەر کەسەکێ ل جهی دڤێت مەترسیێ بناسیت و ڕاوەستیت:",points:["داربەستێ تەنێ پشتی هنگێ بکار بینە دەمێ کەسەکێ شارەزا بەری دەوامێ پشکنیبیت؛ چ جاران داربەستەکا زیانلێکەفتی، نەتەمام یان بێ ڕێلێن پاراستنێ بکار نەئینە، و چ جاران ب خوە نەگوهۆڕە.","کارکرن ل بلندیا ١٫٨ مەتر (٦ پێ) یان پتر ژ ئاستەکێ نزمتر، یان ل نێزیک لێڤەکا ڤەکری یان کونەکێ، پێدڤی ب پاراستنا دژی کەفتنێ هەیە: ڕێلێن پاراستنێ، سەرپۆش یان هارنەسەکا گرێدای ب خالەکا گرێدانێ یا قایم ڤە.","چ جاران نەچە ناڤ خەندەکەکا بێ پاراستن. ل دویڤ OSHA، چالێن کۆلانێ یێن کویراتیا وان ١٫٥ مەتر (٥ پێ) یان پتر پێدڤی ب سیستەمەکێ پاراستنێ هەنە کو بۆ وی جهی هاتبیتە دیزاینکرن، ژ بلی ئەگەر د بەرەکێ قایم دا هاتبنە کۆلان.","کۆمێن ئاخێ، کەرەستە و ئامێران ب کێمی ٠٫٦ مەتر (٢ پێ) ژ لێڤێ دوور بهێلە.","کەسەکێ شارەزا هەر ڕۆژ و پشتی بارانێ چالێن کۆلانێ دپشکنیت.","ل دەمێ نیشانێن هەرفتنێ (قلیش د عەردی دا، دیوارێن پەنەمی، ئاڤا دچۆڕیتە ژوور، ئاخا دکەڤیت): ئێکسەر دەرکەڤە، نەهێلە کەسێن دی بچنە ژوور و بێژە سەرپەرشتیاری؛ کار تەنێ دەمێ مەترسی دهێتە کۆنترۆلکرن دەستپێ دکەتەڤە."]},{heading:"٦. گەهشتنا ١١٥ و هەوارهاتنا ئێکێ",body:"ل دەمێ ئاگری یان برینداربوونێ، هەر خولەکەک گرنگە:",points:["دەرگەهێ سەرەکی یێ جهی، دەرگەه و ڕێکێن گەهشتنێ بۆ ترمبێلێن ئاگرکوژیێ یێن ١١٥ و ئەمبوولانسان ڤەکری بهێلە؛ ترمبێلان لێ ڕانەوەستینە و کەرەستەیان لێ دانەنێ.","هایدرانتێن ئاگری، جهێن ئاڤێ و ئامێرێن ئاگرکوژیێ دیار و ب ساناهی گەهشتن بهێلە.","جهێن مەزن بەری دەستپێکرنا کاری و هەر دەمێ ڕێکێن گەهشتنێ یان مەترسی دهێنە گوهۆڕین پەیوەندیێ ب بەرگرییا شارستانی دکەن، و پاکێتەکا زانیاریان (نەخشەیا جهی، مەترسی، سووتەمەنی، غاز و باترییێن هەلگرتی) بۆ تیمێن ١١٥ ئامادە دهێلن.","کەسەکێ ڕاهێنان ل سەر هەوارهاتنا ئێکێ دیتی و جانتایەکا هەوارهاتنا ئێکێ یا تژی ل جهی هەنە.","نیشانا جهی، ڕێنماییێن گەهشتنێ و ژمارێن ١١٥ و ١٢٢ ل نک تەلەفۆنان، د نڤیسینگەها جهی دا و ل دەرگەهی دانە.","پشتی کەفتنێ ژ بلندیێ، کەسێ بریندار نەلڤینە، ژ بلی ئەگەر جهـ نەسەلامەت بیت یان پێدڤی ب CPR هەبیت؛ گازی ١٢٢ بکە."]},{heading:"٧. تشتەکێ گومانلێکری ل دەمێ کۆلانێ",body:"تەقەمەنیێن کەڤن یێن نەتەقی دشێن ل دەمێ کۆلانێ بهێنە دیتن، هەتا ل وان جهان ژی یێن سەلامەت دهێنە هزرکرن، و دشێن بتەقن ئەگەر بهێنە لڤاندن یان لێدان. ئەگەر ئامێرەک، کارگەرەک یان ئامرازەک تشتەکێ گومانلێکری دەربێخیت:",points:["ئێکسەر ئامێری و کاری ڕاوەستینە.","چ جاران دەست نەدە وی تشتی، نەلڤینە، هەلنەگرە، ل دۆر نەکۆلە و دەرنەئینە، و چ جاران نەخە ناڤ سەتلا ئامێری یان ترمبێلەکێ.","هەمییان ژ وی جهی دەربێخە، و نەهێلە خەلک و ئامێر بچنە ناڤ دا.","بەری مۆبایل یان ڕادیۆیێ بکار بینی گەلەک دوور بکەڤە (ب کێمی ٥٠ مەتر، UNMAS)، پاشان گازی ١١٥ بکە و ڕێنماییێن بەرگرییا شارستانی پەیڕەو بکە.","ژ جهەکێ سەلامەت، جهێ وی تشتی ژ بیر نەکە و بۆ تیمێن ١١٥ بێژە؛ کار تەنێ دەمێ لایەنێن پەیوەندیدار دبێژن جهـ سەلامەتە دەستپێ دکەتەڤە."],critical:!0}],media:[{kind:"image",src:"media/images/w8_construction_site_fire_safety.webp",title:"جهەکێ ئاڤاهیسازیێ یێ ئامادە بۆ ئاگری",description:"مۆلەتا کارێ گەرم دگەل چاڤدێرێ ئاگری، سلندەرێن گرێدای و ڕێکا گەهشتنێ یا ڤەکری"}],quiz:[{question:"ل دویڤ NFPA 51B، پشتی ب دوماهیک هاتنا کارێ گەرم چاڤدێرێ ئاگری دڤێت چەند ل جهی بمینیت؟",options:[{text:"ب کێمی ١ دەمژمێر، یان پتر ئەگەر مۆلەت بخوازیت",correct:!0},{text:"هەتا لەحیمکار ئامێرێن خوە کۆم دکەت و ژ جهی دچیت",correct:!1},{text:"نێزیکی ١٠ خولەکان، ئەگەر هەتا هنگێ دوکێل نەهاتە دیتن",correct:!1},{text:"چ چاڤدێری پێدڤی نینە دەمێ تەمرینکەک ل نێزیک بیت",correct:!1}],explanation:"پریشک دشێن ل جهێن ڤەشارتی بمینن و پشتی دەمەکی ئاگری هەلکەن. NFPA 51B چاڤدێرێ ئاگری ب کێمی ١ دەمژمێر پشتی کاری دخوازیت، و بەرپرسێ مۆلەتێ دشێت چاڤدێریەکا درێژتر بخوازیت."},{question:"تێلەکا درێژکرنێ ل جهی عەزلا وێ زیان پێ گەهشتییە. دڤێت چ بهێتە کرن؟",options:[{text:"ژ کار دەربێخە و بدە کەسەکێ شارەزا دا بگوهۆڕیت",correct:!0},{text:"جهێ زیانلێکەفتی ب شریتێ عەزلێ بپێچە و کاری بەردەوام بکە",correct:!1},{text:"وێ بخە ناڤ تێلەکا دی دا هەر ئێک کارەبەکا کێمتر هەلگریت",correct:!1},{text:"تەنێ بۆ ئامێرێن دەستی یێن بچووک بکار بینە هەتا کار ب دوماهیک دهێت",correct:!1}],explanation:"تێلێن زیانلێکەفتی کارەبێدان و ئاگری چێدکەن. دهێنە ژ کار دەرێخستن و ژ لایێ کەسەکێ شارەزا ڤە ب دروستی دهێنە گوهۆڕین یان چاککرن، چ جاران ب شریتی ناهێنە پێچان (HSE یا بەریتانی)؛ RCD مەترسیێ کێم دکەت بەلێ تێلەکا زیانلێکەفتی سەلامەت ناکەت."},{question:"قلیش د عەردی دا دیار دبن و ئاخ دکەڤیتە ناڤ خەندەکەکێ کو هەڤالەک تێدا کار دکەت. چ دروستە؟",options:[{text:"هەمییان دەربێخە، نەهێلە کەس بچیتە ژوور و بێژە سەرپەرشتیاری",correct:!0},{text:"بەشێ مای ب لەز ب دوماهیک بینە بەری دیوار بلڤیت",correct:!1},{text:"بچە ژوور و دیواری ب تەختێن داری یێن زێدە ڕاگرە",correct:!1},{text:"ئامێرێ کۆلانێ ل سەر لێڤێ ڕاوەستینە دا گرانیا وی ئاخێ ڕاگریت",correct:!1}],explanation:"قلیش و ئاخا دکەڤیت نیشانێن هەرفتنێ نە. کارگەر ئێکسەر دەردکەڤن و ل دەرڤە دمینن هەتا کەسەکێ شارەزا خەندەکێ سەلامەت دکەت؛ ئامێرەکێ گران ل سەر لێڤێ هەرفتنێ پتر دکەت."},{question:"ئامێرێ کۆلانێ تشتەکێ ژەنگگرتی دەردئینیت کو وەک گولەیا تۆپێ دیار دبیت. کارێ دروست چییە؟",options:[{text:"ب هێدی ب سەتلا ئامێری هەلگرە و ل ئالیەکی دانە",correct:!1},{text:"ئاخێ ژ سەر پاقژ بکە دا بزانی کا ڕاستەقینەیە یان نە",correct:!1},{text:"کاری ڕاوەستینە، جهی ڤالا بکە و ژ دوور گازی ١١٥ بکە",correct:!0},{text:"ببە نڤیسینگەها جهی هەتا پۆلیس دگەهن",correct:!1}],explanation:"تەقەمەنی دشێن بتەقن دەمێ دهێنە لڤاندن یان لێدان. ئێکسەر ڕاوەستە، هەمییان دوور بێخە، چ جاران نەلڤینە و ژ جهەکێ دوور گازی ١١٥ بکە، و ل نێزیک وی تشتی مۆبایل یان ڕادیۆیێ بکار نەئینە (UNMAS)."},{question:"کیژ ڕێکخستن بۆ سلندەرێن غازێ ل جهێ ئاڤاهیسازیێ دروستە؟",options:[{text:"ل سەر ئالیێ خوە دانای دا نەکەڤن",correct:!1},{text:"ل سەر پلەکانان، چونکی فێنکترین جهێ جهی یە",correct:!1},{text:"ئۆکسجین و ئەسیتیلین پێکڤە د ئێک کۆگەهێ دا ب زنجیرێ گرێدای",correct:!1},{text:"ب ڕاستی و گرێدای، سەرپۆش ل سەر، دوور ژ چریسک و گەرمیێ",correct:!0}],explanation:"سلندەر ب ڕاستی و گرێدای و ب سەرپۆشێ ڤالڤێ دهێنە هەلگرتن، دوور ژ چریسک و گەرمیێ، و ئۆکسجین ژ غازا سووتەنێ جودا دهێتە هەلگرتن (OSHA 1926.350). پلەکان ڕێکێن دەرکەفتنێ نە و دڤێت ژ سووتەمەنی و سلندەران ڤالا بن."}]},{id:28,code:"BUS-128",icon:"FireExtinguisher",accent:"#b91c1c",title:"بەتانیا ئاگری، تەمرینکێن ل سەر چەرخان و تەمرینکێن ترمبێلان",subtitle:"کەنگی و چەوا ب سەلامەتی بکار بینی، و بۆچی ئاگرێن باتریێن لیتیۆم-ئایۆن پێدڤی ب هشیاریەکا تایبەت هەنە",summary:"ژبلی تەمرینکێن دەستی، جهێن کاری بەتانیا ئاگری، تەمرینکێن مەزن یێن ل سەر چەرخان و تەمرینکێن د ترمبێلان دا بکار دئینن. هەر ئێک سنوورێن خوە هەنە. ئەڤ وانە دیار دکەت کەنگی و چەوا ب سەلامەتی بکار بینی، و چ بکەی دەمێ باتریەکا لیتیۆم-ئایۆن گەلەک گەرم دبیت یان ئاگر دگریت.",blocks:[{body:`هەر ئامێرەکێ ئاگرکوژیێ کارەک و سنوورەک هەیە. هەمان پشکنینا «بەلێ یان نە» بۆ هەمیان دهێتە بکارئینان: ئاگر بچووک و تازە دەستپێکری یە، ئامێر بۆ وی ئاگری دگونجیت، ڕێکا دەرکەفتنێ ل پشت تە یە، ئاگەهداری هاتییە دان و پەیوەندی ب ١١٥ هاتییە کرن، و تە ڕاهێنان دیتییە. ئەگەر هەر بەرسڤەک «نە» بیت، دەرکەڤە. کیژ ستانداردێ تەمرینکان ل دهۆکێ دهێتە جێبەجێکرن (NFPA 10 یان EN 3) و کێ دشێت خزمەتا تەمرینکان بکەت هێشتا نەهاتینە پشتڕاستکرن؛ داخوازییێن بەرگرییا شارستانی و لایەنێ مۆلەتدەر پەیڕەو بکە.

پۆلێن ئاگری ل ڤێرێ ب پیتێن NFPA 10 هاتینە نڤیسین وەک ژێدەرێ پرۆژەی؛ سیستەمێ فەرمی یێ دهۆکێ هێشتا نەهاتییە پشتڕاستکرن. بەرامبەرێن EN 2: NFPA A = EN A؛ NFPA B (شلەمەنی) = EN B؛ NFPA B (غاز) = EN C؛ NFPA C (ئامێرێن کارەبێ یێن کارەبا تێدا) چو پۆل د EN دا نینە؛ NFPA D = EN D؛ NFPA K = EN F.`},{heading:"١. بەتانیا ئاگری: ئاگرێ تاوەیەکا بچووک",body:"بەتانیا ئاگری پارچەیەکا قوماشێ بەرگەگرێ ئاگری یە د پاکەتەکێ دا کو ب لەز دەردکەڤیت. ب بڕینا هەوایێ ئاگرێ بچووک د تاوەیێ یان مەنجەلێ دا ڤەدمرینیت:",points:["ل نێزیک دەرگەهێ مەتبەخێ بهێلە، نە ل تەنیشت سۆبەیێ، دا بشێی بگەهییێ و هێشتا دەرکەڤی.","دەسکێن وێ یێن قوماشی (tabs) ب هێز بکێشە خوار دا بەتانی دەرکەڤیت.","ل بەرامبەری خوە بگرە و لێڤێن وێ ل سەر دەستێن خوە بپێچە، دا دەست و ڕوویێ تە بهێنە پاراستن.","ب هێدی ل سەر تاوەیێ دانە؛ نەهاڤێژە. پشتڕاست ببە کو هەمی تاوەیێ دادپۆشیت.","گەرمیێ تەنێ ڤەمرینە ئەگەر ب سەلامەتی بگەهیە سویچا وێ.","بەتانیێ ل جهێ وێ بهێلە و تاوەیێ نەلڤینە. بەتانیێ بلند نەکە دا بزانی ئاگر ڤەمرییە یان نە، هەتا هەمی تشت ب تەمامی سار دبیت.","پەیوەندیێ ب ١١٥ بکە هەتا ئەگەر ئاگر ڤەمری دیار ببیت ژی؛ ئەگەر ئێکسەر ڤەنەمری، دەرکەڤە و دەرگەهی بگرە. چ جاران ئاڤێ نەکە سەر ڕۆنێ دسۆژیت."]},{heading:"٢. بەتانیا ئاگری: ئاگر ب جلکان ڤە",body:"ئەگەر ئاگر ب جلکێن کەسەکی گرت:",points:["ئەو کەس ڕادوەستیت، خوە دهاڤێژیتە عەردی، ڕوویێ خوە ب دەستان دادپۆشیت و خوە دگێڕیت هەتا گڕ ڤەدمریت.","ئەگەر بەتانیا ئاگری هەبیت، ل دۆر گڕێ و وی کەسی بپێچە و هاریکاریا وی بکە دا خوە بهاڤێژیتە عەردی و خوە بگێڕیت.","دەستێن خوە ب لێڤێن بەتانیێ بپارێزە.","پاشان سۆتنێ ب ئاڤا فێنک یا ڕەوان ٢٠ خولەکان سار بکە، بلقان نەتەقینە و پەیوەندیێ ب ١٢٢ بکە.","بەتانیا ئاگری ئێک جار دهێتە بکارئینان و پاشان دهێتە گوهۆڕین. ئەوا بکڕە یا لایبلا وێ نیشان ددەت کیژ ستاندارد پێ دهێتە، بۆ نموونە EN 1869؛ بەتانیەکا بێ نیشانا ستانداردێ دبیت کار نەکەت. کیژ ستاندارد ل ڤێرێ دهێتە پەسەندکرن هێشتا نەهاتییە پشتڕاستکرن."]},{heading:"٣. تەمرینکێن ل سەر چەرخان",body:"تەمرینکێن ل سەر چەرخان گەلەک ماددە ژ تەمرینکا دەستی پتر هەلدگرن، ل سەر عەرەبانەکێ ب لوولەیەکا درێژ. ئەو جهێن وەکی کۆگەهێن سووتەمەنیێ، کارگەهێن چاککرنێ و جهێن بارکرنێ دپارێزن:",points:["تەنێ ئەو کارمەندێن ل سەر وی مۆدێلی ڕاهێنان دیتین بکار دئینن: کۆنترۆل، ڕێزبەندیا هەنگاڤان و دویراهی ژ مۆدێلەکێ بۆ یێ دی جودانە، لەوا لایبلێ پەیڕەو بکە.","هەر جهەکێ بشێی دووان دوو کار بکەن: کەسەک عەرەبانێ و ڤالڤێ وەکی لایبل نیشان ددەت کۆنترۆل دکەت، یێ دی لوولە و سەرێ لوولەیێ دگریت. هندەک مۆدێل بۆ ئێک کەسێ ڕاهێنان دیتی هاتینە چێکرن.","ئامێری ببە جهەکێ د ناڤ وێ دویراهیێ دا یا ل سەر لایبلێ، ڕێکا دەرکەفتنێ ل پشت تە بیت، و هەنگاڤێن لایبلێ ب ڕێزبەندی پەیڕەو بکە.","پشکنینا «بەلێ یان نە» هەمان پشکنینە: تەمرینکا ل سەر چەرخان ئاگرەکێ مەزن بۆ ڤەمراندنێ سەلامەت ناکەت.","پشتی هەر بکارئینانەکێ، ژ لایێ تەکنیکارەکێ شارەزا ڤە دهێتە تژیکرنەڤە."]},{heading:"٤. تەمرینکێن ترمبێلان",body:"بارهەلگر، فۆرکلیفت، پاس و ترمبێلێن کۆمپانیێ گەلەک جاران تەمرینکەکا بچووک دگەل خوە دبەن، بەلێ پتریا ئاگرێن ترمبێلان نە بۆ هندێ نە کو شۆفێر ڤەمرینیت:",points:["ب زوویترین دەم کو سەلامەت بیت ل کەناری ڕێکێ ڕاوەستە، مەکینێ ڤەکوژینە، هەمی کەسان دەربێخە و گەلەک ژ ترمبێلێ و ژ هاتنوچوونێ دویر بکەڤن، ب کێمی ٣٠ مەتر (١٠٠ پێ).","پەیوەندیێ ب ١١٥ بکە (و ب ١٢٢ ئەگەر کەسەک بریندار بیت) و ترمبێلێن دی ئاگەهدار بکە؛ چ جاران بۆ تشتێن خوە نەزڤڕە.","چ جاران کاپۆتێ یان سندۆقا پشتێ ڤەنەکە ئەگەر تە هزر کر ئاگر د ناڤدایە: هەوایێ تازە ئاگری گڕ دکەت.","تەمرینکا ترمبێلێ تەنێ ل سەر ئاگرەکێ بچووک یێ تازە دەستپێکری بکار بینە، تەنێ ئەگەر تە ڕاهێنان دیتبیت، هەمی کەس دەرکەفتبن و ڕێکا ڤەگەڕیانا تە ڤەکری بیت. بۆ ئاگرێ د جهێ مەکینێ دا، کاپۆتێ گرتی بهێلە؛ هندەک دەزگەهێن ئاگرکوژیێ ڕێنمایێ ددەن کو ب ڕێکا شەبەکا پێشیێ (grille) یان کەلێنا ل لێڤا کاپۆتێ ئاراستە بکەی.","ئەگەر تو د گومانێ دا بی، نێزیکی ئاگری نەبە. چ جاران ئاڤێ نەکە سەر ئاگرێ مەکینێ.","فۆرکلیفت و ترمبێلێن دی یێن ب باتریێ کار دکەن: ئەگەر باتری د ئاگری دا بیت، وەکی ئاگرێ باتریێ مامەلێ دگەل بکە (پشکا ٥)."]},{heading:"٥. ئاگرێن باتریێن لیتیۆم-ئایۆن",body:"باتریێن لیتیۆم-ئایۆن د مۆبایل، لاپتۆپ، ئامێرێن کارەبێ یێن دەستی، پاسکیلێن کارەبێ، فۆرکلیفت و سیستەمێن هەلگرتنا کارەبێ دا هەنە. دەمێ زیان دبینن، زێدە دهێنە شەحنکرن یان خراب دبن، دشێن گەلەک گەرم ببن، غازا ژەهراوی بەردەن، ئاگر بگرن یان بتەقن:",points:["نیشانێن مەترسیێ: بێهنەکا سەیر، گەرمی، وەرەمین یان گوهۆڕینا شێوەی یان ڕەنگی، دەنگێن تەقینێ یان دوکێل. ئێکسەر بکارئینان یان شەحنکرنا وێ ڕاوەستینە.","ئەگەر سەلامەت بیت، فیشێ دەربێخە و ژ هەر تشتەکێ دسۆژیت دویر بکە.","ئەگەر ئاگر گرتبیت: هەمی کەسان دەربێخە، دەرگەهی بگرە و ژ دەرڤە پەیوەندیێ ب ١١٥ بکە؛ بێژە کو ئاگرێ باتریێ یە.","دوکێلێ هەلنەمژە: باتریا زیان دیتی دشێت غازەکا ژەهراوی بەردەت کو دبیت نەهێتە دیتن.","سارکرن ب گەلەک ئاڤێ ڕێکا پێشنیارکری یە، بەلێ تەنێ کەسێن ڕاهێنان دیتی ب ئامێرێن گونجای دکەن؛ تۆزا ABC یا ئاسایی و CO₂ ئاگری ب تەمامی ڕاناوەستینن.","باتریێن لیتیۆم-ئایۆن نە پۆلا D نە: ماددێن پۆلا D تەنێ بۆ باتریێن لیتیۆما کانزایی و کانزایێن دسۆژن نە.","ڕێگری: تەنێ شەحنەرێ کۆمپانیا چێکەر یان یێ ئەو پەسەند دکەت بکار بینە، ل سەر ڕووبەرەکێ ڕەق، دویر ژ تشتێن دسۆژن و دویر ژ دەرکەفتنان شەحن بکە، و باتریێن زیان دیتی ژ بکارئینانێ دەربێخە."],critical:!0},{heading:"٦. پشکنین و خزمەت",body:"هەمی ڤان ئامێران ئامادە بهێلە:",points:["د پشکنینا ب چاڤ یا ب ڕێکوپێک دا، بەتانیێن ئاگری ژی بپشکنە: ل جهێ خوە، ب ساناهی دگەهنێ، پاکەت ساخلەم و دەسکێن وێ ب ئازادی شۆڕ.","تەمرینکێن ل سەر چەرخان و یێن ترمبێلان هەمان پشکنینا ب چاڤ وەکی تەمرینکێن دی وەردگرن: ل جهێ خوە، مێخ و مۆر ساخلەم، پیڤەرا فشارێ د ناڤچەیا کەسک دا ئەگەر هەبیت، بێ زیان.","پشتی هەر بکارئینانەکێ تژیکرنەڤە؛ چاککرنا سالانە و تاقیکرنێن فشارێ ژ لایێ تەکنیکارەکێ شارەزا ڤە دهێنە کرن. ڕێسایێن خزمەتێ یێن ناڤچەیی و کێ دشێت خزمەتا تەمرینکان بکەت هێشتا نەهاتینە پشتڕاستکرن.","بەتانیا ئاگری یا بکارئینای بگوهۆڕە و ئێکسەر ڕاپۆرتا هەر تەمرینکەکا بکارئینای بدە."]}],media:[{kind:"image",src:"media/images/w8_fire_blanket_pan.webp",title:"بکارئینانا بەتانیا ئاگری ل سەر ئاگرێ تاوەیەکا بچووک",description:"کارکەرەکا ل مەتبەخا کارمەندان بەتانیا ئاگری ل بەرامبەری خوە دگریت، دەستێن وێ ل پشت قوماشی پاراستینە، و ب هێدی ل سەر تاوەیەکا دسۆژیت دادنیت؛ دەرگەهێ ل پشت وێ ڤەکری یە."}],quiz:[{question:"تاوەیەکا بچووک یا ڕۆنی ل سەر سۆبەیێ ئاگر گرت. بەتانیا ئاگری ل دەڤ تە یە. ڕێکا دروست چییە؟",options:[{text:"دەستێن خوە ب لێڤێن وێ بپارێزە، ب هێدی ل سەر تاوەیێ دانە و ل وێرێ بهێلە",correct:!0},{text:"ژ لایێ دی یێ مەتبەخێ بەتانیێ بهاڤێژە سەر تاوەیێ دا تو ژ ئاگری دویر بمینی",correct:!1},{text:"تاوەیێ داپۆشە، پاشان پشتی خولەکەکێ بەتانیێ بلند بکە دا بزانی ئاگر ڤەمرییە",correct:!1},{text:"ئێکەم پەرداخەکا ئاڤێ بکە سەر تاوەیێ، پاشان ب بەتانیێ داپۆشە",correct:!1}],explanation:"بەتانیێ ب هێدی ل سەر تاوەیێ دانە و دەستێن تە ل پشت وێ پاراستی بن، ئەگەر ب سەلامەتی بشێی گەرمیێ ڤەمرینە، بهێلە هەتا هەمی تشت سار دبیت و پەیوەندیێ ب ١١٥ بکە. چ جاران ئاڤ ل سەر ڕۆنێ دسۆژیت نە."},{question:"ئاگر ب جلکێن هەڤالەکێ کاری گرت. تو چ دکەی؟",options:[{text:"وی ڕادوەستینم، خوە دهاڤێژیتە عەردی و دگێڕیت، و ئەگەر هەبیت بەتانیێ ل دۆر گڕێ دپێچم",correct:!0},{text:"دبێژمێ ب لەز بەرەڤ نێزیکترین بۆرییا ئاڤێ بڕەڤیت دا ئاڤ گڕێ ل سەر لەشێ وی ڤەمرینیت",correct:!1},{text:"تەمرینکا CO₂ ڕاستەوخوە و ژ نێزیک ڤە بەرەڤ ڕوو و سنگا وی دبەردەم هەتا گڕ ڤەدمریت",correct:!1},{text:"ب دەستێن خوە یێن ڕووت و هندی بشێم ب لەز جلکێن وی یێن دسۆژن ژ لەشێ وی دکەم",correct:!1}],explanation:"ڕاوەستان، خوە هاڤێتنا عەردی و گێڕان گڕێ ڤەدمرینن، و بەتانیا ئاگری یا ل دۆر گڕێ هاتییە پێچان هاریکاریێ دکەت؛ دەستێن خوە ب لێڤێن وێ بپارێزە. پاشان سۆتنێ ب ئاڤا فێنک یا ڕەوان ٢٠ خولەکان سار بکە و پەیوەندیێ ب ١٢٢ بکە."},{question:"کێ دڤێت تەمرینکا ل سەر چەرخان بکار بینیت؟",options:[{text:"کارمەندێن ل سەر وی مۆدێلی ڕاهێنان دیتین، ل دویڤ لایبلێ، ب باشی دووان دوو",correct:!0},{text:"هەر کارمەندەکێ دەمێ زەنگ لێددەت نێزیکترین کەس بیت ل ئاگری",correct:!1},{text:"تەنێ پاسەڤانێ دەرگەهی، چونکی ئەو تەمرینک ل نێزیک دەرگەهێ سەرەکی دهێنە هێلان",correct:!1},{text:"هەر کەسەکێ ب کێمی جارەکێ تەمرینکەکا دەستی یا بچووک ل مالێ بکار ئینابیت",correct:!1}],explanation:"تەمرینکێن ل سەر چەرخان ژ مۆدێلەکێ بۆ یێ دی جودانە. تەنێ کارمەندێن ل سەر وی مۆدێلی ڕاهێنان دیتین بکار دئینن، ل دویڤ لایبلێ، ب باشی دووان دوو، و تەنێ پشتی هەمان پشکنینا «بەلێ یان نە»."},{question:"دوکێل ژ بن کاپۆتا بارهەلگرەکا کۆمپانیێ دەردکەڤیت. کارێ دروست چییە؟",options:[{text:"ڕاوەستە، مەکینێ ڤەکوژینە، هەمیان دەربێخە و دویر ببە، پەیوەندیێ ب ١١٥ بکە و کاپۆتێ نەڤەکە",correct:!0},{text:"کاپۆتێ ب تەمامی ڤەکە دا بشێی تەمرینکێ ڕاستەوخوە بەرەڤ مەکینێ بگری",correct:!1},{text:"ئاژۆتنێ بەردەوام بکە هەتا نێزیکترین کارگەها چاککرنێ دا وەستا بەرێ خوە بدەتێ",correct:!1},{text:"ئاڤا بوتلەکێ ب ڕێکا کەلێنا بن کاپۆتێ بکە سەر مەکینێ",correct:!1}],explanation:"ڤەکرنا کاپۆتێ هەوایێ تازە ددەتە ئاگری و ئاگر گڕ دکەت. هەمی کەسان دەربێخە و ب کێمی ٣٠ مەتر (١٠٠ پێ) دویر ببە، پەیوەندیێ ب ١١٥ بکە، و چ جاران ئاڤێ نەکە سەر ئاگرێ مەکینێ."},{question:"باتریا ئامێرەکێ کارەبێ یێ دەستی ل سەر ڕەفا شەحنکرنێ وەرەم دکەت و دوکێل ژێ دەردکەڤیت. تو چ دکەی؟",options:[{text:"ئەگەر سەلامەت بیت فیشێ دەردئێخم و دویر دکەم؛ ئەگەر ئاگر گرت، دەردکەڤم و پەیوەندیێ ب ١١٥ دکەم",correct:!0},{text:"ب تۆزا پۆلا D دادپۆشم، چونکی باتریێن لیتیۆم-ئایۆن ئاگرێن کانزایانە",correct:!1},{text:"دکەمە د دۆلابەکێ کانزایی دا و دەرگەهی ب هێز دگرم دا دوکێل ل ناڤ دا بمینیت",correct:!1},{text:"شەحنکرنێ بەردەوام دکەم، چونکی وەرەم دەمێ باتری ب تەمامی تژی دبیت کێم دبیت",correct:!1}],explanation:"وەرەمین و دوکێل نیشانێن مەترسیێ نە. ئەگەر سەلامەت بیت، فیشێ دەربێخە و ژ تشتێن دسۆژن دویر بکە؛ ئەگەر ئاگر گرت، هەمی کەسان دەربێخە، دەرگەهی بگرە و پەیوەندیێ ب ١١٥ بکە. باتریێن لیتیۆم-ئایۆن نە پۆلا D نە."}]}],t={lessons:e};export{t as default,e as lessons};
